{"file_path": "/workspace/services/brief_dates.jac", "content": """"Deterministic brief-week date logic for the spoken local weekly brief.

Weekdays belong to their current Monday; weekend dates belong to the
upcoming Monday (Saturday = -2, Sunday = -1 relative to it).
"""

import from datetime { date, datetime, timedelta }

"""Normalize the input to a plain date (today when None)."""
def _as_date(now: date | datetime | None = None) -> date {
    if now is None {
        return date.today();
    }
    if isinstance(now, datetime) {
        return now.date();
    }
    return now;
}

"""Return the Monday that anchors the brief week for `now` (today if None)."""
def brief_monday(now: date | datetime | None = None) -> date {
    d = _as_date(now);
    wd = d.weekday();
    if wd >= 5 {
        return d + timedelta(days=7 - wd);
    }
    return d - timedelta(days=wd);
}

"""Return the day index of `now` relative to its brief Monday."""
def brief_day_index(now: date | datetime | None = None) -> int {
    d = _as_date(now);
    return (d - brief_monday(d)).days;
}

"""Return the spoken-style label, e.g. "Monday, September 28, 2026"."""
def brief_week_label(now: date | datetime | None = None) -> str {
    monday = brief_monday(_as_date(now));
    return monday.strftime("%A") + ", " + monday.strftime("%B") + " " + str(monday.day) + ", " + str(monday.year);
}

"""Preview the brief week for an ISO date string (empty means today)."""
walker:pub preview_week {
    has date_str: str = "";

    can run with Root entry {
        raw = self.date_str.strip();
        d: date = date.today();
        if raw {
            try {
                d = date.fromisoformat(raw);
            } except ValueError {
                report {"error": "Enter a valid date in YYYY-MM-DD format."};
                return;
            }
        }
        monday = brief_monday(d);
        report {
            "date": d.isoformat(),
            "monday": monday.isoformat(),
            "label": brief_week_label(d),
            "day_index": brief_day_index(d),
            "is_weekend": d.weekday() >= 5
        };
    }
}
"}

