{"file_path": "/workspace/services/brief_dates.test.jac", "content": """"Behavior tests for the brief_dates service (annex of brief_dates.jac)."""

test "weekdays anchor to their current monday" {
    monday = date(2026, 9, 21);
    for offset in range(5) {
        d = monday + timedelta(days=offset);
        assert brief_monday(d) == monday, f"bad monday for {d}";
        assert brief_day_index(d) == offset, f"bad index for {d}";
        assert brief_week_label(d) == "Monday, September 21, 2026";
    }
}

test "saturday anchors to upcoming monday" {
    d = date(2026, 9, 26);
    assert brief_monday(d) == date(2026, 9, 28);
    assert brief_day_index(d) == -2;
    assert brief_week_label(d) == "Monday, September 28, 2026";
}

test "sunday anchors to upcoming monday" {
    d = date(2026, 9, 27);
    assert brief_monday(d) == date(2026, 9, 28);
    assert brief_day_index(d) == -1;
    assert brief_week_label(d) == "Monday, September 28, 2026";
}

test "datetime input is accepted" {
    dt = datetime(2026, 9, 26, 18, 30);
    assert brief_monday(dt) == date(2026, 9, 28);
    assert brief_day_index(dt) == -2;
}

test "none means today" {
    assert brief_monday(None) == brief_monday(date.today());
    assert brief_day_index() == brief_day_index(date.today());
}

test "label has no zero padding and no prefix" {
    label = brief_week_label(date(2026, 3, 4));
    assert label == "Monday, March 2, 2026", label;
    assert not label.startswith("Week of");
}

test "preview_week walker reports a weekend preview" {
    result = root spawn preview_week(date_str="2026-09-26");
    assert len(result.reports) == 1;
    r = result.reports[0];
    assert r["monday"] == "2026-09-28";
    assert r["label"] == "Monday, September 28, 2026";
    assert r["day_index"] == -2;
    assert r["is_weekend"] == True;
}

test "preview_week walker rejects invalid input" {
    result = root spawn preview_week(date_str="not-a-date");
    assert len(result.reports) == 1;
    assert "error" in result.reports[0];
}

test "preview_week walker defaults to today" {
    result = root spawn preview_week();
    assert result.reports[0]["monday"] == brief_monday(date.today()).isoformat();
}
"}

{"file_path": "/workspace/components/WeekPlanner.jac", "content": """"Week planner: shows the current brief week and previews a chosen date."""

sv import from ..services.brief_dates { preview_week }

"""Planner card pair: current brief week plus a date preview form."""
def:pub WeekPlanner() -> JsxElement {
    has current: dict = {};
    has current_loading: bool = True;
    has current_error: str = "";
    has chosen: str = "";
    has preview: dict = {};
    has preview_loading: bool = False;
    has preview_error: str = "";

    async can with entry {
        try {
            result = root spawn preview_week(date_str="");
            if result.reports and len(result.reports) > 0 {
                r = result.reports[0];
                if r["error"] {
                    current_error = r["error"];
                } else {
                    current = r;
                }
            } else {
                current_error = "No response from the date service.";
            }
        } except Exception {
            current_error = "Could not load the current brief week.";
        }
        current_loading = False;
    }

    def handle_change(e: ChangeEvent) {
        chosen = e.target.value;
    }

    async def run_preview(value: str) -> None {
        if not value {
            preview_error = "Choose a date to preview.";
            preview = {};
            return;
        }
        preview_loading = True;
        preview_error = "";
        try {
            result = root spawn preview_week(date_str=value);
            if result.reports and len(result.reports) > 0 {
                r = result.reports[0];
                if r["error"] {
                    preview_error = r["error"];
                    preview = {};
                } else {
                    preview = r;
                }
            } else {
                preview_error = "No response from the date service.";
            }
        } except Exception {
            preview_error = "Could not preview that date.";
        }
        preview_loading = False;
    }

    def handle_submit(e: FormEvent) {
        e.preventDefault();
        run_preview(chosen);
    }

    def handle_clear(e: MouseEvent) {
        chosen = "";
        preview = {};
        preview_error = "";
    }

    return <main className="planner">
        <header className="planner-header">
            <h1>Weekly Brief Planner</h1>
            <p>Plan your spoken local weekly brief. Weekdays belong to their current Monday; weekend dates roll forward to the upcoming Monday.</p>
        </header>
        <div className="planner-grid">
            <section className="card card-current" aria-label="Current brief week">
                <p className="card-eyebrow">Current brief week</p>
                {if current_loading {
                    <p className="status">Loading the current brief week...</p>
                } elif current_error {
                    <p className="status status-error" role="alert">{current_error}</p>
                } else {
                    <h2 className="week-label" data-testid="current-label">{current["label"]}</h2>
                    <div className="stats">
                        <div className="stat">
                            <span className="stat-label">Anchor Monday</span>
                            <span className="stat-value">{current["monday"]}</span>
                        </div>
                        <div className="stat">
                            <span className="stat-label">Today</span>
                            <span className="stat-value">{current["date"]}</span>
                        </div>
                        <div className="stat">
                            <span className="stat-label">Day index</span>
                            <span className="stat-value">{str(current["day_index"])}</span>
                        </div>
                    </div>
                }}
            </section>
            <section className="card" aria-label="Preview a date">
                <p className="card-eyebrow">Preview a date</p>
                <form className="date-form" onSubmit={handle_submit}>
