{"file_path": "/workspace/logs/store.jac", "content": """"Data types and session parsing for local Claude session transcripts."""

import json;
import os;

"""Summary of one Claude project directory containing JSONL sessions."""
obj ProjectSummary {
    has name: str = "",
        path: str = "",
        decoded_path: str = "",
        session_count: int = 0,
        last_activity: float = 0.0;
}

"""Summary counts for one JSONL session file."""
obj SessionSummary {
    has session_id: str = "",
        file_path: str = "",
        title: str = "",
        first_user_text: str = "",
        message_count: int = 0,
        user_count: int = 0,
        assistant_count: int = 0,
        tool_call_count: int = 0,
        started_at: str = "",
        last_timestamp: str = "",
        git_branch: str = "",
        size_bytes: int = 0;
}

"""A node in a trajectory tree."""
obj TrajectoryNode {
    has id: str = "",
        kind: str = "",
        label: str = "",
        children: list[TrajectoryNode] = [];
}

"""A reference from a trajectory node to a subagent transcript."""
obj SubagentRef {
    has node_id: str = "",
        agent_id: str = "",
        file_path: str = "";
}

"""Sort key: most recent project activity."""
def _activity_key(p: ProjectSummary) -> float {
    return p.last_activity;
}

"""Sort key: latest session timestamp."""
def _session_key(s: SessionSummary) -> str {
    return s.last_timestamp;
}

"""Return the sorted *.jsonl file paths directly inside a directory."""
def _jsonl_files(directory: str) -> list[str] {
    files: list[str] = [];
    if not os.path.isdir(directory) {
        return files;
    }
    for entry in sorted(os.listdir(directory)) {
        full = os.path.join(directory, entry);
        if entry.endswith(".jsonl") and os.path.isfile(full) {
            files.append(full);
        }
    }
    return files;
}

"""Decode a dash-separated project directory name into a filesystem path."""
def _decode_project_name(name: str) -> str {
    return name.replace("-", "/");
}

"""Return the first text of a user message content (string or list of text blocks)."""
def _first_text(content: any) -> str {
    if isinstance(content, str) {
        return content;
    }
    if isinstance(content, list) {
        for block in content {
            if isinstance(block, dict) and block.get("type") == "text" {
                text = block.get("text");
                if isinstance(text, str) {
                    return text;
                }
            }
        }
    }
    return "";
}

"""List project directories under <claude_root>/projects that contain JSONL sessions."""
def:pub list_projects(claude_root: str) -> list[ProjectSummary] {
    projects_dir = os.path.join(claude_root, "projects");
    results: list[ProjectSummary] = [];
    if not os.path.isdir(projects_dir) {
        return results;
    }
    for name in sorted(os.listdir(projects_dir)) {
        full = os.path.join(projects_dir, name);
        if not os.path.isdir(full) {
            continue;
        }
        files = _jsonl_files(full);
        if len(files) == 0 {
            continue;
        }
        last = 0.0;
        for f in files {
            mtime = os.path.getmtime(f);
            if mtime > last {
                last = mtime;
            }
        }
        results.append(
            ProjectSummary(
                name=name,
                path=full,
                decoded_path=_decode_project_name(name),
                session_count=len(files),
                last_activity=last
            )
        );
    }
    results.sort(key=_activity_key, reverse=True);
    return results;
}

"""List the sessions in a project directory, skipping malformed records."""
def:pub list_sessions(project_dir: str) -> list[SessionSummary] {
    sessions: list[SessionSummary] = [];
    for f in _jsonl_files(project_dir) {
        sessions.append(_summarize_session(f));
    }
    sessions.sort(key=_session_key, reverse=True);
    return sessions;
}

"""Summarize one JSONL session file."""
def _summarize_session(file_path: str) -> SessionSummary {
    base = os.path.basename(file_path);
    sid = base[:-6] if base.endswith(".jsonl") else base;
    summary = SessionSummary(session_id=sid, file_path=file_path);
    with open(file_path, encoding="utf-8", errors="replace") as fh {
        for raw in fh {
            line = raw.strip();
            if not line {
                continue;
            }
            rec: any = None;
            try {
                rec = json.loads(line);
            } except Exception {
                continue;
            }
            if not isinstance(rec, dict) {
                continue;
            }
            ts = rec.get("timestamp");
            if isinstance(ts, str) and ts {
                if not summary.started_at {
                    summary.started_at = ts;
                }
                if ts > summary.last_timestamp {
                    summary.last_timestamp = ts;
                }
            }
            branch = rec.get("gitBranch");
            if not summary.git_branch and isinstance(branch, str) and branch {
                summary.git_branch = branch;
            }
            kind = rec.get("type");
            if kind == "ai-title" {
                title = rec.get("aiTitle") or rec.get("title");
                if isinstance(title, str) and title {
                    summary.title = title;
                }
                continue;
            }
            msg = rec.get("message");
            content: any = msg.get("content") if isinstance(msg, dict) else None;
            if kind == "user" {
                summary.user_count += 1;
                summary.message_count += 1;
                if not summary.first_user_text {
                    summary.first_user_text = _first_text(content);
                }
            } elif kind == "assistant" {
                summary.assistant_count += 1;
                summary.message_count += 1;
                if isinstance(content, list) {
                    for block in content {
                        if isinstance(block, dict) and block.get("type") == "tool_use" {
                            summary.tool_call_count += 1;
                        }
                    }
                }
            }
        }
    }
    summary.size_bytes = os.path.getsize(file_path);
    return summary;
}
"}

{"file_path": "/workspace/logs/treeUtils.jac", "content": """"Lookups over a trajectory tree and its subagent references."""

import from logs.store { TrajectoryNode, SubagentRef }

"""Recursively find the node with the given ID under treeRoot, or None if absent."""
def:pub findNode(treeRoot: TrajectoryNode, nodeId: str) -> TrajectoryNode | None {
    if treeRoot.id == nodeId {
        return treeRoot;
    }
    for child in treeRoot.children {
        found = findNode(child, nodeId);
        if found is not None {
            return found;
        }
    }
    return None;
}

"""Return the SubagentRef mapped to nodeId, or None if missing."""
def:pub subagentRefFor(nodeId: str, subagentByNodeId: dict[str, SubagentRef]) -> SubagentRef | None {
    return subagentByNodeId.get(nodeId);
}
"}

{"file_path": "/workspace/tests/test_store.jac", "content": """"Behavior tests for logs/store.jac using temporary JSONL fixtures."""

import json;
import os;
import tempfile;
import from logs.store { list_projects, list_sessions }

"""Write records (dicts or raw strings) as JSONL lines."""
def _write_jsonl(path: str, lines: list) -> None {
    with open(path, "w", encoding="utf-8") as fh {
        for item in lines {
            if isinstance(item, str) {
                fh.write(item + "\n");
            } else {
                fh.write(json.dumps(item) + "\n");
            }
        }
    }
}

"""Build a temporary Claude root with two projects and one empty project dir."""
def _make_root() -> str {
    root = tempfile.mkdtemp();
    projects = os.path.join(root, "projects");
    old_proj = os.path.join(projects, "-home-a-old");
    new_proj = os.path.join(projects, "-home-a-new");
    empty_proj = os.path.join(projects, "-home-a-empty");
    for d in [old_proj, new_proj, empty_proj] {
        os.makedirs(d);
    }
    with open(os.path.join(empty_proj, "notes.txt"), "w") as fh {
        fh.write("not a session");
    }
    old_file = os.path.join(old_proj, "old1.jsonl");
    _write_jsonl(old_file, [{"type": "user", "message": {"content": "hi"}, "timestamp": "2025-01-01T00:00:00Z"}]);
    os.utime(old_file, (1000.0, 1000.0));
    s1 = os.path.join(new_proj, "sess-a.jsonl");
    _write_jsonl(
        s1,
        [
            {"type": "user", "message": {"role": "user", "content": [{"type": "image"}, {"type": "text", "text": "first question"}]}, "timestamp": "2025-02-01T10:00:00Z", "gitBranch": "main"},
            "{not valid json",
            "",
            {"type": "assistant", "message": {"content": [{"type": "text", "text": "ok"}, {"type": "tool_use", "name": "Bash"}, {"type": "tool_use", "name": "Read"}]}, "timestamp": "2025-02-01T10:00:05Z", "gitBranch": "feature"},
            {"type": "user", "message": {"content": "second question"}, "timestamp": "2025-02-01T10:01:00Z"},
            {"type": "ai-title", "aiTitle": "Fix the build"},
            {"type": "assistant", "message": {"content": [{"type": "tool_use", "name": "Edit"}]}, "timestamp": "2025-02-01T10:02:00Z"}
        ]
    );
    s2 = os.path.join(new_proj, "sess-b.jsonl");
    _write_jsonl(s2, [{"type": "user", "message": {"content": "other"}, "timestamp": "2025-01-15T00:00:00Z"}]);
    os.utime(s1, (5000.0, 5000.0));
    os.utime(s2, (3000.0, 3000.0));
    return root;
}

test "list_projects filters, decodes, counts and sorts" {
    root = _make_root();
    projects = list_projects(root);
    assert len(projects) == 2;
    assert projects[0].name == "-home-a-new";
    assert projects[0].decoded_path == "/home/a/new";
    assert projects[0].session_count == 2;
    assert projects[0].last_activity == 5000.0;
    assert projects[1].name == "-home-a-old";
    assert projects[1].session_count == 1;
    assert projects[1].last_activity == 1000.0;
}

test "list_projects on missing root returns empty list" {
    assert len(list_projects(os.path.join(tempfile.mkdtemp(), "nope"))) == 0;
}

test "list_sessions summarizes valid records and skips malformed lines" {
    root = _make_root();
    proj = os.path.join(root, "projects", "-home-a-new");
    sessions = list_sessions(proj);
    assert len(sessions) == 2;
    s = sessions[0];
    assert s.session_id == "sess-a";
    assert s.user_count == 2;
    assert s.assistant_count == 2;
    assert s.message_count == 4;
    assert s.tool_call_count == 3;
    assert s.title == "Fix the build";
    assert s.first_user_text == "first question";
    assert s.started_at == "2025-02-01T10:00:00Z";
    assert s.last_timestamp == "2025-02-01T10:02:00Z";
    assert s.git_branch == "main";
    assert s.size_bytes == os.path.getsize(os.path.join(proj, "sess-a.jsonl"));
    assert s.size_bytes > 0;
    assert sessions[1].session_id == "sess-b";
    assert sessions[1].first_user_text == "other";
    assert sessions[1].tool_call_count == 0;
}
"}

