import from logs.store { TrajectoryNode, SubagentRef }
import from logs.treeUtils { findNode, subagentRefFor }

"""Build a small three-level trajectory tree."""
def _make_tree() -> TrajectoryNode {
    leaf = TrajectoryNode(id="n3", kind="tool", label="Bash", children=[]);
    mid = TrajectoryNode(id="n2", kind="assistant", label="step", children=[leaf]);
    sibling = TrajectoryNode(id="n4", kind="user", label="ask", children=[]);
    return TrajectoryNode(id="n1", kind="session", label="root", children=[sibling, mid]);
}

test "findNode returns the tree root when its id matches" {
    tree = _make_tree();
    found = findNode(tree, "n1");
    assert found is not None;
    assert found.label == "root";
}

test "findNode recursively finds a descendant" {
    tree = _make_tree();
    found = findNode(tree, "n3");
    assert found is not None;
    assert found.id == "n3";
    assert found.label == "Bash";
}

test "findNode returns None for a missing id" {
    assert findNode(_make_tree(), "missing") is None;
}

test "subagentRefFor returns the mapped reference or None" {
    ref = SubagentRef(node_id="n3", agent_id="agent-1", file_path="/tmp/agent-1.jsonl");
    mapping: dict[str, SubagentRef] = {"n3": ref};
    got = subagentRefFor("n3", mapping);
    assert got is not None;
    assert got.agent_id == "agent-1";
    assert subagentRefFor("n9", mapping) is None;
}
"}

