def:pub get_paper_details(id: str) -> Paper | None {
    obj: Any = None;
    try {
        obj = jobj(id);
    } except Exception {
        return None;
    }
    if isinstance(obj, Paper) {
        return obj;
    }
    return None;
}

"""Save a new Paper on root with a generated ID and timestamp, and report its metadata."""
walker:pub save_paper {
    has title: str,
        author: str,
        summary: str,
        tags: list[str],
        source_url: str;

    can run with Root entry {
        paper = Paper(
            title=self.title,
            author=self.author,
            summary=self.summary,
            source_url=self.source_url,
            tags=list(self.tags),
            created_at=datetime.now()
        );
        here ++> paper;
        report {
            "jid": jid(paper),
            "title": paper.title,
            "author": paper.author,
            "summary": paper.summary,
            "tags": paper.tags,
            "source_url": paper.source_url,
            "created_at": paper.created_at.isoformat() if paper.created_at else None
        };
    }
}

"""Report every Paper saved on root."""
walker:pub list_papers {
    can run with Root entry {
        visit [-->(?:Paper)];
    }

    can gather with Paper entry {
        report here;
    }
}

"""Report one dict with the papers whose tags contain the requested tag."""
walker:pub search_papers_by_tag {
    has tag: str;
    has papers: list[Paper] = [];

    can run with Root entry {
        visit [-->(?:Paper)];
    }

    can gather with Paper entry {
        if self.tag in here.tags {
            self.papers.append(here);
        }
    }

    can finish with Root exit {
        report {"papers": self.papers};
    }
}
"}

