{"file_path": "/workspace/styles.css", "content": ":root {
  --bg: #f4f1ea;
  --surface: #ffffff;
  --surface-2: #faf8f3;
  --ink: #1f2a24;
  --muted: #5f6b63;
  --border: #e2ddd1;
  --primary: #3f7d5a;
  --primary-ink: #ffffff;
  --sea: #cfe6ea;
  --sand: #efe3c2;
  --grass: #b9d8a8;
  --danger-bg: #fdecec;
  --danger-ink: #8a1f1f;
  --radius: 14px;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  color: var(--ink);
  background: var(--bg);
}

body {
  margin: 0;
  background: var(--bg);
}

.mc-shell {
  max-width: 1200px;
  margin: 0 auto;
  padding: 24px 16px 48px;
}

.mc-header h1 {
  margin: 0;
  font-size: 1.75rem;
}

.mc-header p {
  margin: 4px 0 20px;
  color: var(--muted);
}

.mc-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 16px;
}

@media (min-width: 900px) {
  .mc-grid {
    grid-template-columns: 2fr 1fr;
  }
}

.mc-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 16px;
}

.mc-card h2 {
  margin: 0 0 12px;
  font-size: 1.1rem;
}

.mc-island {
  position: relative;
  width: 100%;
  aspect-ratio: 16 / 10;
  background: radial-gradient(ellipse at center, var(--grass) 0%, var(--grass) 38%, var(--sand) 48%, var(--sea) 62%);
  border-radius: var(--radius);
  overflow: hidden;
}

.mc-island-empty {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  color: var(--muted);
  padding: 16px;
}

.mc-entity {
  position: absolute;
  transform: translate(-50%, -50%);
  min-width: 64px;
  padding: 8px 10px;
  border-radius: 999px;
  border: 2px solid rgba(0, 0, 0, 0.1);
  color: var(--ink);
  font-size: 0.85rem;
  cursor: pointer;
  text-align: center;
}

.mc-entity.is-selected {
  outline: 3px solid var(--primary);
}

.mc-pending {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.mc-chip {
  border-radius: 999px;
  padding: 6px 12px;
  border: 1px solid var(--border);
  background: var(--surface-2);
  cursor: pointer;
  font-size: 0.85rem;
}

.mc-chip.is-selected {
  border-color: var(--primary);
  background: #e6f1ea;
}

.mc-stack {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.mc-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.mc-label {
  font-size: 0.85rem;
  font-weight: 600;
}

.mc-input,
.mc-textarea {
  width: 100%;
  box-sizing: border-box;
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 10px 12px;
  font: inherit;
  background: var(--surface);
}

.mc-textarea {
  min-height: 80px;
  resize: vertical;
}

.mc-btn {
  border: 1px solid var(--border);
  background: var(--surface-2);
  color: var(--ink);
  border-radius: 10px;
  padding: 8px 14px;
  font: inherit;
  cursor: pointer;
}

.mc-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.mc-btn-primary {
  background: var(--primary);
  border-color: var(--primary);
  color: var(--primary-ink);
  font-weight: 600;
}

.mc-crisis {
  background: var(--danger-bg);
  color: var(--danger-ink);
  border: 1px solid #f3c4c4;
  border-radius: var(--radius);
  padding: 14px 16px;
  margin-bottom: 16px;
}

.mc-error {
  color: var(--danger-ink);
  font-size: 0.9rem;
}

.mc-muted {
  color: var(--muted);
  font-size: 0.9rem;
}

.mc-path {
  margin: 0;
  padding-left: 18px;
}

.mc-path li {
  margin: 4px 0;
}
"}

