{"file_path": "/workspace/services/common.jac", "content": """"Shared helpers and constants for AnchorCare services."""

import uuid;
import from datetime { datetime, timezone }

glob APP_DISCLAIMER: str = "AnchorCare is an AI-powered care coordination platform. It does not replace emergency care or professional diagnosis.";

"""Return a new uuid4 session id string."""
def new_session_id() -> str {
    return str(uuid.uuid4());
}

"""Return the current UTC time as an ISO-8601 string."""
def iso_now() -> str {
    return datetime.now(timezone.utc).isoformat();
}

"""Collapse whitespace and trim text."""
def normalize_text(text: str) -> str {
    if not text {
        return "";
    }
    return " ".join(text.split());
}

"""Return the first non-blank of two strings."""
def first_non_empty(a: str, b: str) -> str {
    if a and a.strip() {
        return a;
    }
    if b and b.strip() {
        return b;
    }
    return "";
}

"""Merge an incoming string into an existing one without duplication."""
def merge_strings(existing: str, incoming: str) -> str {
    old = normalize_text(existing);
    new_text = normalize_text(incoming);
    if not new_text {
        return old;
    }
    if not old {
        return new_text;
    }
    if new_text.lower() in old.lower() {
        return old;
    }
    return old + "; " + new_text;
}

"""Truncate text to max_chars characters."""
def truncate(text: str, max_chars: int) -> str {
    if not text {
        return "";
    }
    if max_chars <= 0 {
        return "";
    }
    if len(text) <= max_chars {
        return text;
    }
    if max_chars <= 3 {
        return text[:max_chars];
    }
    return text[:max_chars - 3] + "...";
}

"""Render the last max_messages messages as 'ROLE: content' lines."""
def transcript_excerpt(messages: list, max_messages: int) -> str {
    if not messages or max_messages <= 0 {
        return "";
    }
    lines: list[str] = [];
    for msg in messages[-max_messages:] {
        role = "";
        content = "";
        if isinstance(msg, dict) {
            role = str(msg.get("role", "") or "");
            content = str(msg.get("content", "") or "");
        } else {
            role = str(getattr(msg, "role", "") or "");
            content = str(getattr(msg, "content", "") or "");
        }
        lines.append(role.upper() + ": " + content);
    }
    return "\n".join(lines);
}
"}

{"file_path": "/workspace/models/session.jac", "content": """"Chat session model for AnchorCare: messages, result objects and the UserSession node."""

import from .codes { DiagnosisCode }
import from .provider { ProviderOption }

glob APP_DISCLAIMER: str = "AnchorCare is an AI-powered care coordination platform. It does not replace emergency care or professional diagnosis.";

obj ChatMessage {
    has role: str;
    has content: str;
    has timestamp: str;
    has agent: str;
}

obj CareSummary {
    has summary_text: str = "";
    has doctor_notes: str = "";
}

obj ConversationStateUpdate {
    has reply: str = "";
    has extracted_symptoms: list[str] = [];
    has symptom_duration: str | None = None;
    has severity: str | None = None;
    has location: str | None = None;
    has insurance: str | None = None;
    has ready_for_diagnosis: bool = False;
}

obj InterventionDecision {
    has intervention_needed: bool = False;
    has risk_flags: list[str] = [];
    has reply: str = "";
}

obj DiagnosisResult {
    has codes: list[DiagnosisCode] = [];
    has rationale: str = "";
}

obj CallingPreparation {
    has providers: list[ProviderOption] = [];
    has call_script: str = "";
}

node UserSession {
    has session_id: str;
    has created_at: str;
    has updated_at: str;
    has phone_number: str = "";
    has active_agent: str = "Conversation Agent";
    has last_user_message: str = "";
    has transcript: list[ChatMessage] = [];
    has extracted_symptoms: list[str] = [];
    has risk_flags: list[str] = [];
    has assigned_codes: list[DiagnosisCode] = [];
    has provider_options: list[ProviderOption] = [];
    has agent_path: list[str] = [];
    has intervention_active: bool = False;
    has intervention_resolved: bool = False;
    has crisis_therapists_shown: bool = False;
    has symptom_duration: str | None = None;
    has severity: str | None = None;
    has location: str | None = None;
    has insurance: str | None = None;
    has summary_text: str | None = None;
    has doctor_notes: str | None = None;
}

"""Append a ChatMessage to the session transcript."""
def append_message(session: UserSession, role: str, content: str, agent: str, ts: str) -> None {
    session.transcript.append(
        ChatMessage(role=role, content=content, timestamp=ts, agent=agent)
    );
}

"""Set only the session's updated_at timestamp."""
def update_session_timestamp(session: UserSession, ts: str) -> None {
    session.updated_at = ts;
}

"""Serialize a session to a plain dict, including the six-agent trace."""
def session_to_dict(session: UserSession) -> dict {
    trace: list[dict] = [
        {"name": "Intervention Agent", "status": "listening"},
        {"name": "Conversation Agent", "status": "idle"},
        {"name": "Calling Agent", "status": "idle"},
        {"name": "Diagnosis Agent", "status": "idle"},
        {"name": "Messaging Agent", "status": "idle"},
        {"name": "Summary Agent", "status": "idle"}
    ];
    for entry in session.agent_path {
        parts = str(entry).split(":");
        if len(parts) >= 2 {
            for item in trace {
                if item["name"] == parts[0] {
                    item["status"] = parts[1];
                }
            }
        }
    }
    transcript: list[dict] = [];
    for m in session.transcript {
        transcript.append(
            {
                "role": m.role,
                "content": m.content,
                "timestamp": m.timestamp,
                "agent": m.agent
            }
        );
    }
    codes: list[dict] = [];
    for c in session.assigned_codes {
        codes.append(
            {
                "code": c.code,
                "description": c.description,
                "category": c.category,
                "confidence": c.confidence,
                "source": c.source
            }
        );
    }
    providers: list[dict] = [];
    for p in session.provider_options {
        providers.append(
            {
                "name": p.name,
                "specialty": p.specialty,
                "address": p.address,
                "phone": p.phone,
                "accepts_insurance": list(p.accepts_insurance),
                "distance_miles": p.distance_miles,
                "rating": p.rating,
                "accepting_new_patients": p.accepting_new_patients,
                "telehealth_available": p.telehealth_available,
                "notes": p.notes
            }
        );
    }
    return {
        "session_id": session.session_id,
        "phone_number": session.phone_number,
        "created_at": session.created_at,
        "updated_at": session.updated_at,
        "active_agent": session.active_agent,
        "transcript": transcript,
        "extracted_symptoms": list(session.extracted_symptoms),
        "risk_flags": list(session.risk_flags),
        "assigned_codes": codes,
        "provider_options": providers,
        "agent_path": list(session.agent_path),
        "agent_trace": trace,
        "intervention_active": session.intervention_active,
        "intervention_resolved": session.intervention_resolved,
        "location": session.location,
        "insurance": session.insurance,
        "summary_text": session.summary_text,
        "doctor_notes": session.doctor_notes,
        "disclaimer": APP_DISCLAIMER
    };
}
"}

{"file_path": "/workspace/services/pdf_exporter.jac", "content": """"PDF export payload builder for AnchorCare sessions."""

import from ..models.session { UserSession }
import from .common { iso_now, APP_DISCLAIMER }

glob _PDF_STYLE: str = "<style>body{font-family:Helvetica,Arial,sans-serif;color:#1f2937;font-size:12px;line-height:1.5;}h2{font-size:15px;color:#0f766e;border-bottom:1px solid #e5e7eb;padding-bottom:4px;margin-top:18px;}.kv-row{margin:2px 0;}.kv-label{font-weight:bold;}.section-intro{font-style:italic;color:#6b7280;}.code-id{font-weight:bold;font-family:monospace;}.provider-name{font-weight:bold;margin:0;}.provider-meta{color:#4b5563;margin:0;}.flag-item{color:#b91c1c;}.msg-block{margin:6px 0;}.msg-header{font-weight:bold;color:#0f766e;margin:0;}.msg-header-patient{font-weight:bold;color:#1d4ed8;margin:0;}.msg-body{margin:2px 0 0 0;}.msg-divider{border-top:1px solid #f3f4f6;}.disclaimer{margin-top:24px;font-size:10px;color:#6b7280;}</style>";

"""Escape & < > \" ' for safe HTML output (ampersand first)."""
def _escape_html(value: str) -> str {
    if value is None {
        return "";
    }
    text = str(value);
    text = text.replace("&", "&amp;");
    text = text.replace("<", "&lt;");
    text = text.replace(">", "&gt;");
    text = text.replace("\"", "&quot;");
    text = text.replace("'", "&#39;");
    return text;
}

"""Return HH:MM, the 5 characters after 'T' in an ISO timestamp."""
def _fmt_time(ts: str) -> str {
    if not ts {
        return "";
    }
    idx = str(ts).find("T");
    if idx < 0 {
        return "";
    }
    return str(ts)[idx + 1:idx + 6];
}

"""Return the date part before 'T' in an ISO timestamp."""
def _fmt_date(ts: str) -> str {
    if not ts {
        return "";
    }
    return str(ts).split("T")[0];
}

"""Read a field from a dict or an object."""
def _field(item: object, key: str) -> object {
    if isinstance(item, dict) {
        return item.get(key, None);
    }
    return getattr(item, key, None);
}

"""Read a field as an escaped string ('' when missing)."""
def _esc_field(item: object, key: str) -> str {
    value = _field(item, key);
    if value is None {
        return "";
    }
    return _escape_html(str(value));
}

"""Render one kv-row paragraph."""
def _kv_row(label: str, value: str) -> str {
    return "<p class=\"kv-row\"><span class=\"kv-label\">" + label + "</span>" + value + "</p>";
}

"""Build the clinical summary section body."""
def _summary_html(session: UserSession) -> str {
    if session.summary_text and session.summary_text.strip() {
        return "<p>" + _escape_html(session.summary_text.strip()) + "</p>";
    }
    parts: list[str] = [];
    symptoms = list(session.extracted_symptoms or []);
    if len(symptoms) > 0 {
        escaped = [_escape_html(s) for s in symptoms[:5]];
        parts.append("The patient reported: " + ", ".join(escaped) + ".");
    }
    codes = list(session.assigned_codes or []);
    if len(codes) > 0 {
        top = codes[0];
        parts.append("Top provisional match: " + _esc_field(top, "code") + " \u2014 " + _esc_field(top, "description") + ".");
    }
    providers = list(session.provider_options or []);
    if len(providers) > 0 {
        parts.append(str(len(providers)) + " provider recommendation(s) available.");
    }
    flags = list(session.risk_flags or []);
    if len(flags) > 0 {
        parts.append("Safety review flagged: " + ", ".join([_escape_html(f) for f in flags]) + ".");
    } else {
        parts.append("No active safety flags recorded.");
    }
    return "<p>" + " ".join(parts) + "</p>";
}

"""Build the session details rows."""
def _meta_html(session: UserSession, generated_at: str) -> str {
    created = str(session.created_at or "");
    return _kv_row("Session ID: ", _escape_html(session.session_id))
        + _kv_row("Date: ", _escape_html(_fmt_date(created)) + " at " + _escape_html(_fmt_time(created)) + " UTC")
        + _kv_row("Exported: ", _escape_html(_fmt_date(generated_at)) + " at " + _escape_html(_fmt_time(generated_at)) + " UTC");
}

"""Build the patient information rows."""
def _patient_html(session: UserSession) -> str {
    rows = "";
    pairs = [
        ("Location: ", session.location),
        ("Insurance: ", session.insurance),
        ("Duration: ", session.symptom_duration),
        ("Severity: ", session.severity)
    ];
    for (label, value) in pairs {
        if value and str(value).strip() {
            rows += _kv_row(label, _escape_html(str(value)));
        }
    }
    if not rows {
        return "<p>No patient information recorded.</p>";
    }
    return rows;
}

"""Build the reported symptoms list."""
def _symptoms_html(session: UserSession) -> str {
    symptoms = list(session.extracted_symptoms or []);
    if len(symptoms) == 0 {
        return "<p>No patient-reported symptoms captured.</p>";
    }
    items = "";
    for s in symptoms {
        items += "<li>" + _escape_html(s) + "</li>";
    }
    return "<ul>" + items + "</ul>";
}

"""Build the matched conditions list."""
def _conditions_html(session: UserSession) -> str {
    codes = list(session.assigned_codes or []);
    if len(codes) == 0 {
        return "<p>No provisional diagnosis outputs recorded.</p>";
    }
    items = "";
    for c in codes {
        item = "<li><span class=\"code-id\">" + _esc_field(c, "code") + "</span> \u2014 " + _esc_field(c, "description");
        conf = _field(c, "confidence");
        if conf {
            item += " <span>(" + _escape_html(str(conf)) + ")</span>";
        }
        items += item + "</li>";
    }
    return "<ul>" + items + "</ul>";
}

"""Build the provider recommendations list."""
def _providers_html(session: UserSession) -> str {
    providers = list(session.provider_options or []);
    if len(providers) == 0 {
        return "<p>No provider recommendations available yet.</p>";
    }
    items = "";
    for p in providers {
        meta = _esc_field(p, "specialty");
        phone = _esc_field(p, "phone");
        if phone {
            meta += " \u00b7 " + phone;
        }
        item = "<li><p class=\"provider-name\">" + _esc_field(p, "name") + "</p><p class=\"provider-meta\">" + meta + "</p>";
        extras: list[str] = [];
        address = _esc_field(p, "address");
        if address {
            extras.append(address);
        }
        notes = _esc_field(p, "notes");
        if notes {
            extras.append(notes);
        }
        if len(extras) > 0 {
            item += "<p class=\"provider-meta\">" + " \u00b7 ".join(extras) + "</p>";
        }
        items += item + "</li>";
    }
    return "<ul>" + items + "</ul>";
}

"""Build the risk and safety flags list."""
def _risks_html(session: UserSession) -> str {
    flags = list(session.risk_flags or []);
    if len(flags) == 0 {
        return "<p>No active risk flags recorded for this session.</p>";
    }
    items = "";
    for f in flags {
        items += "<li class=\"flag-item\">" + _escape_html(f) + "</li>";
    }
    return "<ul>" + items + "</ul>";
}

"""Build the conversation transcript blocks."""
def _transcript_html(session: UserSession) -> str {
    messages = list(session.transcript or []);
    if len(messages) == 0 {
        return "<p>No conversation transcript available.</p>";
    }
    out = "";
    for m in messages {
        role = str(_field(m, "role") or "");
        cls = "msg-header";
        speaker = "";
        if role == "user" {
            cls = "msg-header-patient";
            speaker = "Patient";
        } else {
            agent = str(_field(m, "agent") or "");
            speaker = agent if agent else "Care Anchor";
        }
        ts = str(_field(m, "timestamp") or "");
        header = _escape_html(speaker) + " \u00b7 " + _escape_html(_fmt_time(ts));
        out += "<div class=\"msg-block\"><p class=\"" + cls + "\">" + header + "</p><p class=\"msg-body\">" + _esc_field(m, "content") + "</p></div><div class=\"msg-divider\"></div>";
    }
    return out;
}

"""Build the PDF export payload with HTML content for a session."""
def build_session_pdf_payload(session: UserSession) -> dict {
    generated_at = iso_now();
    html_content = _PDF_STYLE
        + "<h2>Clinical Summary</h2>" + _summary_html(session)
        + "<h2>Session Details</h2>" + _meta_html(session, generated_at)
        + "<h2>Patient Information</h2>" + _patient_html(session)
        + "<h2>Reported Symptoms</h2>" + _symptoms_html(session)
        + "<h2>Matched Conditions</h2><p class=\"section-intro\">For informational purposes only \u2014 not a medical diagnosis.</p>" + _conditions_html(session)
        + "<h2>Provider Recommendations</h2>" + _providers_html(session)
        + "<h2>Risk &amp; Safety Flags</h2>" + _risks_html(session)
        + "<h2>Conversation Transcript</h2>" + _transcript_html(session)
        + "<p class=\"disclaimer\">" + _escape_html(APP_DISCLAIMER) + "</p>";
    return {
        "file_name": "anchorcare_session_" + str(session.session_id) + ".pdf",
        "mime_type": "application/pdf",
        "generated_at": generated_at,
        "session_id": session.session_id,
        "disclaimer": APP_DISCLAIMER,
        "html_content": html_content
    };
}
"}

{"file_path": "/workspace/tests/test_session.jac", "content": """"Behavior tests for session helpers and session_to_dict."""

import from models.session {
    UserSession,
    ChatMessage,
    append_message,
    update_session_timestamp,
    session_to_dict,
    APP_DISCLAIMER
}
import from models.codes { DiagnosisCode }
import from models.provider { ProviderOption }

def _make_session() -> UserSession {
    return UserSession(
        session_id="s1",
        created_at="2026-01-01T10:00:00+00:00",
        updated_at="2026-01-01T10:00:00+00:00"
    );
}

test "append_message adds ChatMessage entries" {
    s = _make_session();
    append_message(s, "user", "I have a headache", "", "2026-01-01T10:01:00+00:00");
    append_message(s, "assistant", "How long?", "Conversation Agent", "2026-01-01T10:02:00+00:00");
    assert len(s.transcript) == 2;
    assert isinstance(s.transcript[0], ChatMessage);
    assert s.transcript[0].role == "user";
    assert s.transcript[0].content == "I have a headache";
    assert s.transcript[1].agent == "Conversation Agent";
    assert s.transcript[1].timestamp == "2026-01-01T10:02:00+00:00";
}

test "sessions do not share default lists" {
    a = _make_session();
    b = _make_session();
    append_message(a, "user", "hi", "", "2026-01-01T10:01:00+00:00");
    assert len(a.transcript) == 1;
    assert len(b.transcript) == 0;
}

test "update_session_timestamp changes only updated_at" {
    s = _make_session();
    before = session_to_dict(s);
    update_session_timestamp(s, "2026-02-02T12:00:00+00:00");
    after = session_to_dict(s);
    assert after["updated_at"] == "2026-02-02T12:00:00+00:00";
    assert after["created_at"] == "2026-01-01T10:00:00+00:00";
    for key in before {
        if key != "updated_at" {
            assert before[key] == after[key];
        }
    }
}

test "session_to_dict serializes codes providers transcript" {
    s = _make_session();
    append_message(s, "user", "cough", "", "2026-01-01T10:01:00+00:00");
    s.assigned_codes.append(DiagnosisCode(code="R05", description="Cough", category="Respiratory", confidence=0.8));
    s.provider_options.append(ProviderOption(name="Dr. A", specialty="GP", address="1 Main St", phone="555", accepts_insurance=["Aetna"]));
    d = session_to_dict(s);
    expected_keys = ["session_id", "phone_number", "created_at", "updated_at", "active_agent", "transcript", "extracted_symptoms", "risk_flags", "assigned_codes", "provider_options", "agent_path", "agent_trace", "intervention_active", "intervention_resolved", "location", "insurance", "summary_text", "doctor_notes", "disclaimer"];
    assert sorted(list(d.keys())) == sorted(expected_keys);
    assert d["transcript"] == [{"role": "user", "content": "cough", "timestamp": "2026-01-01T10:01:00+00:00", "agent": ""}];
    assert d["assigned_codes"] == [{"code": "R05", "description": "Cough", "category": "Respiratory", "confidence": 0.8, "source": "symptom_mapper"}];
    p = d["provider_options"][0];
    assert isinstance(p, dict);
    assert p["name"] == "Dr. A";
    assert p["accepts_insurance"] == ["Aetna"];
    assert p["accepting_new_patients"] == True;
    assert p["telehealth_available"] == False;
    assert d["disclaimer"] == APP_DISCLAIMER;
    assert d["active_agent"] == "Conversation Agent";
}

test "agent_trace defaults and agent_path statuses" {
    s = _make_session();
    d0 = session_to_dict(s);
    names = [t["name"] for t in d0["agent_trace"]];
    assert names == ["Intervention Agent", "Conversation Agent", "Calling Agent", "Diagnosis Agent", "Messaging Agent", "Summary Agent"];
    assert d0["agent_trace"][0]["status"] == "listening";
    assert d0["agent_trace"][1]["status"] == "idle";
    s.agent_path = ["Conversation Agent:active", "Diagnosis Agent:done", "Summary Agent"];
    d = session_to_dict(s);
    statuses = {t["name"]: t["status"] for t in d["agent_trace"]};
    assert statuses["Conversation Agent"] == "active";
    assert statuses["Diagnosis Agent"] == "done";
    assert statuses["Summary Agent"] == "idle";
    assert statuses["Intervention Agent"] == "listening";
    assert statuses["Calling Agent"] == "idle";
    assert len(d["agent_trace"]) == 6;
}
"}

{"file_path": "/workspace/tests/test_pdf_exporter.jac", "content": """"Behavior tests for build_session_pdf_payload."""

import from models.session { UserSession, append_message }
import from models.codes { DiagnosisCode }
import from models.provider { ProviderOption }
import from services.common { APP_DISCLAIMER }
import from services.pdf_exporter { build_session_pdf_payload }

def _make_session() -> UserSession {
