}

test "empty sections show placeholder text" {
    s = _make_session();
    html = build_session_pdf_payload(s)["html_content"];
    assert "<h2>Clinical Summary</h2><p>No active safety flags recorded.</p>" in html;
    assert "<p>No patient information recorded.</p>" in html;
    assert "<p>No patient-reported symptoms captured.</p>" in html;
    assert "<p>No provisional diagnosis outputs recorded.</p>" in html;
    assert "<p>No provider recommendations available yet.</p>" in html;
    assert "<p>No active risk flags recorded for this session.</p>" in html;
    assert "<p>No conversation transcript available.</p>" in html;
    assert "<p class=\"kv-row\"><span class=\"kv-label\">Session ID: </span>abc123</p>" in html;
    assert "<p class=\"kv-row\"><span class=\"kv-label\">Date: </span>2026-01-01 at 10:00 UTC</p>" in html;
    assert "<h2>Risk &amp; Safety Flags</h2>" in html;
}

test "filled sections follow templates with escaping" {
    s = _make_session();
    s.extracted_symptoms = ["<b>headache</b>", "Tom's fever"];
    s.risk_flags = ["self-harm"];
    s.location = "Ann Arbor";
    s.severity = "moderate";
    s.assigned_codes.append(DiagnosisCode(code="R51", description="Headache", category="Neuro", confidence=0.7));
    s.provider_options.append(ProviderOption(name="Dr. A & B", specialty="GP", address="1 Main St", phone="555-0100", accepts_insurance=["Aetna"]));
    append_message(s, "user", "I feel <bad>", "", "2026-01-01T10:01:00+00:00");
    append_message(s, "assistant", "Noted", "Conversation Agent", "2026-01-01T10:02:00+00:00");
    append_message(s, "assistant", "Hello", "", "2026-01-01T10:03:00+00:00");
    html = build_session_pdf_payload(s)["html_content"];
    assert "<ul><li>&lt;b&gt;headache&lt;/b&gt;</li><li>Tom&#39;s fever</li></ul>" in html;
    assert "The patient reported: &lt;b&gt;headache&lt;/b&gt;, Tom&#39;s fever." in html;
    assert "Top provisional match: R51 \u2014 Headache." in html;
    assert "1 provider recommendation(s) available." in html;
    assert "Safety review flagged: self-harm." in html;
    assert "<li><span class=\"code-id\">R51</span> \u2014 Headache <span>(0.7)</span></li>" in html;
