{"file_path": "/workspace/walkers/impact.jac", "content": """"ImpactWalker: dashboard totals gathered from every person on root."""

import from graph.nodes { PersonNode, NeedNode, ApplicationNode }
import from graph.edges { applied_to, has_need }

walker ImpactWalker {
    has summary: dict = {};

    can run with Root entry {
        people = [root --> [?:PersonNode]];
        lang_counts: dict = {};
        cat_counts: dict = {};
        status_counts: dict = {
            "pending": 0,
            "applied": 0,
            "approved": 0,
            "denied": 0,
            "withdrawn": 0
        };
        res_counts: dict = {};
        total_apps: int = 0;
        for p in people {
            lang = p.language or "en";
            lang_counts[lang] = lang_counts.get(lang, 0) + 1;
            for n in [p ->:has_need:-> [?:NeedNode]] {
                cat_counts[n.category] = cat_counts.get(n.category, 0) + 1;
            }
            for a in [p ->:applied_to:-> [?:ApplicationNode]] {
                if a.status == "archived" {
                    continue;
                }
                total_apps += 1;
                status_counts[a.status] = status_counts.get(a.status, 0) + 1;
                if a.resource_name {
                    res_counts[a.resource_name] = res_counts.get(a.resource_name, 0) + 1;
                }
            }
        }
        approved = status_counts["approved"];
        applied = status_counts["applied"];
        denied = status_counts["denied"];
        decided = approved + denied + applied;
        rate = int((approved + applied) * 100 / decided) if decided > 0 else 0;
        languages = [{"lang": k, "count": lang_counts[k]} for k in lang_counts];
        categories = [{"category": k, "count": cat_counts[k]} for k in cat_counts];
        ranked = sorted([(0 - res_counts[k], k) for k in res_counts]);
        top = [{"name": r[1], "count": 0 - r[0]} for r in ranked[:5]];
        self.summary = {
            "total_users": len(people),
            "total_applications": total_apps,
            "languages": languages,
            "need_categories": categories,
            "app_status_counts": status_counts,
            "approval_rate": rate,
            "top_resources": top
        };
        report self.summary;
    }
}

sem ImpactWalker = "Walks every person on root and reports dashboard totals for CivicMesh.";
sem ImpactWalker.summary = "The last dashboard report produced by this walker.";
"}

