{"file_path": "/workspace/walkers/pathfinder.jac", "content": """"PathfinderWalker: bounded BFS over leads_to edges that reports two-hop escape paths."""

import from graph.nodes { ResourceNode, EligibilityRuleNode }
import from graph.edges { leads_to }

def _sum_days(hops: list) -> int {
    total: int = 0;
    for h in hops {
        total += int(h["days"]);
    }
    return total;
}

walker PathfinderWalker {
    has start_category: str = "";
    has max_hops: int = 3;
    has max_paths: int = 3;
    has seed_resource_names: list[str] = [];
    has summary: dict = {};

    can search with Root entry {
        seeds: list = [];
        seen: list[str] = [];
        for r in [root --> [?:ResourceNode]] {
            if r.agency_name in self.seed_resource_names or r.category == self.start_category {
                if r.agency_name not in seen {
                    seen.append(r.agency_name);
                    seeds.append(r);
                }
            }
        }
        paths: list = [];
        for seed in seeds {
            if len(paths) >= self.max_paths {
                break;
            }
            queue: list = [(seed, [], [seed.agency_name])];
            while len(queue) > 0 and len(paths) < self.max_paths {
                item = queue.pop(0);
                cur = item[0];
                hops: list = item[1];
                visited: list = item[2];
                if len(hops) >= 2 {
                    paths.append({
                        "start": seed.agency_name,
                        "end": cur.agency_name,
                        "hops": hops,
                        "hop_count": len(hops),
                        "total_days": _sum_days(hops)
                    });
                    continue;
                }
                if len(hops) >= self.max_hops {
                    continue;
                }
                nexts = [cur ->:leads_to:-> [?:ResourceNode]];
                links = [edge cur ->:leads_to:->];
                for (i, nxt) in enumerate(nexts) {
                    if nxt.agency_name in visited {
                        continue;
                    }
                    e = links[i];
                    hop = {
                        "from": cur.agency_name,
                        "to": nxt.agency_name,
                        "reason": e.transition_reason,
                        "days": e.typical_days,
                        "difficulty": e.difficulty
                    };
                    queue.append((nxt, hops + [hop], visited + [nxt.agency_name]));
                }
            }
        }
        ordered = sorted(paths, key=lambda p: dict: (p["total_days"], p["hop_count"]));
        self.summary = {
            "ok": True,
            "start_category": self.start_category,
            "max_hops": self.max_hops,
            "path_count": len(ordered),
            "paths": ordered
        };
        report self.summary;
    }
}

sem _sum_days = "Total the typical days across a list of hop dicts.";
sem PathfinderWalker = "Finds two-hop progression paths from the resources of a start category.";
sem PathfinderWalker.start_category = "Need category whose resources seed the search.";
sem PathfinderWalker.max_hops = "Maximum BFS depth over leads_to edges.";
sem PathfinderWalker.max_paths = "Maximum number of paths to report.";
sem PathfinderWalker.seed_resource_names = "Extra resource agency names to use as seeds.";
sem PathfinderWalker.summary = "The last path report produced by this walker.";
"}

