{"file_path": "/workspace/services/graph/localdb.jac", "content": """"Rentora local SQLite log store: SMS, walker runs, notifications and generic docs."""

import os;
import sqlite3;
import json;
import from datetime { datetime }

glob _db_path: str = os.path.join(os.getcwd(), ".jac", "data", "app.db");
glob _tables_ready: bool = False;

def _ensure_tables() -> None {
    global _tables_ready;
    if _tables_ready {
        return;
    }
    os.makedirs(os.path.dirname(_db_path), exist_ok=True);
    conn = sqlite3.connect(_db_path);
    conn.execute(
        "CREATE TABLE IF NOT EXISTS sms_messages (id INTEGER PRIMARY KEY AUTOINCREMENT, from_number TEXT, to_number TEXT, body TEXT, direction TEXT, sid TEXT, unit_id TEXT, tenant_name TEXT, created_at TEXT)"
    );
    conn.execute(
        "CREATE TABLE IF NOT EXISTS walker_logs (id INTEGER PRIMARY KEY AUTOINCREMENT, walker_name TEXT, unit_id TEXT, input_data TEXT, output_data TEXT, duration_ms INTEGER, created_at TEXT)"
    );
    conn.execute(
        "CREATE TABLE IF NOT EXISTS notifications (id INTEGER PRIMARY KEY AUTOINCREMENT, notification_type TEXT, payload TEXT, ticket_id TEXT, is_read INTEGER DEFAULT 0, created_at TEXT)"
    );
    conn.execute(
        "CREATE TABLE IF NOT EXISTS documents (id INTEGER PRIMARY KEY AUTOINCREMENT, collection TEXT, doc TEXT, created_at TEXT)"
    );
    conn.commit();
    conn.close();
    _tables_ready = True;
}

def _rows(cur: any) -> list {
    cols = [d[0] for d in cur.description];
    return [dict(zip(cols, r)) for r in cur.fetchall()];
}

def:pub log_sms(
    from_number: str,
    to_number: str,
    body: str,
    direction: str,
    sid: str = "",
    unit_id: str = "",
    tenant_name: str = ""
) -> dict {
    try {
        _ensure_tables();
        conn = sqlite3.connect(_db_path);
        cur = conn.execute(
            "INSERT INTO sms_messages (from_number, to_number, body, direction, sid, unit_id, tenant_name, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
            (from_number, to_number, body, direction, sid, unit_id, tenant_name, datetime.now().isoformat())
        );
        conn.commit();
        new_id = cur.lastrowid;
        conn.close();
        return {"ok": True, "id": new_id};
    } except Exception as e {
        return {"ok": False, "error": str(e)};
    }
}

def:pub get_sms_history(phone: str = "", limit_count: int = 50) -> list {
    try {
        _ensure_tables();
        conn = sqlite3.connect(_db_path);
        if phone {
            cur = conn.execute(
                "SELECT * FROM sms_messages WHERE from_number = ? OR to_number = ? ORDER BY id DESC LIMIT ?",
                (phone, phone, limit_count)
            );
        } else {
            cur = conn.execute(
                "SELECT * FROM sms_messages ORDER BY id DESC LIMIT ?", (limit_count, )
            );
        }
        result = _rows(cur);
        conn.close();
        return result;
    } except Exception {
        return [];
    }
}

def:pub log_walker_run(
    walker_name: str,
    unit_id: str,
    input_data: dict,
    output_data: dict,
    duration_ms: int = 0
) -> dict {
    try {
        _ensure_tables();
        conn = sqlite3.connect(_db_path);
        cur = conn.execute(
            "INSERT INTO walker_logs (walker_name, unit_id, input_data, output_data, duration_ms, created_at) VALUES (?, ?, ?, ?, ?, ?)",
            (walker_name, unit_id, json.dumps(input_data, default=str), json.dumps(output_data, default=str), duration_ms, datetime.now().isoformat())
        );
        conn.commit();
        new_id = cur.lastrowid;
        conn.close();
        return {"ok": True, "id": new_id};
    } except Exception as e {
        return {"ok": False, "error": str(e)};
    }
}

def:pub create_notification(
    notification_type: str, payload: dict, ticket_id: str = ""
) -> dict {
    try {
        _ensure_tables();
        conn = sqlite3.connect(_db_path);
        cur = conn.execute(
            "INSERT INTO notifications (notification_type, payload, ticket_id, is_read, created_at) VALUES (?, ?, ?, 0, ?)",
            (notification_type, json.dumps(payload, default=str), ticket_id, datetime.now().isoformat())
        );
        conn.commit();
        new_id = cur.lastrowid;
        conn.close();
        return {"ok": True, "id": new_id};
    } except Exception as e {
        return {"ok": False, "error": str(e)};
    }
}

def:pub get_notifications(unread_only: bool = True, limit_count: int = 20) -> list {
    try {
        _ensure_tables();
        conn = sqlite3.connect(_db_path);
        if unread_only {
            cur = conn.execute(
                "SELECT * FROM notifications WHERE is_read = 0 ORDER BY id DESC LIMIT ?",
                (limit_count, )
            );
        } else {
            cur = conn.execute(
                "SELECT * FROM notifications ORDER BY id DESC LIMIT ?", (limit_count, )
            );
        }
        result = _rows(cur);
        conn.close();
        for row in result {
            row["payload"] = json.loads(row["payload"] or "{}");
        }
        return result;
    } except Exception {
        return [];
    }
}

def:pub db_insert(collection: str, doc: dict) -> dict {
    try {
        _ensure_tables();
        conn = sqlite3.connect(_db_path);
        cur = conn.execute(
            "INSERT INTO documents (collection, doc, created_at) VALUES (?, ?, ?)",
            (collection, json.dumps(doc, default=str), datetime.now().isoformat())
        );
        conn.commit();
        new_id = cur.lastrowid;
        conn.close();
        return {"ok": True, "id": new_id};
    } except Exception as e {
        return {"ok": False, "error": str(e)};
    }
}

def:pub db_find(collection: str, query: dict = {}, limit_count: int = 50) -> list {
    try {
        _ensure_tables();
        conn = sqlite3.connect(_db_path);
        cur = conn.execute(
            "SELECT doc FROM documents WHERE collection = ? ORDER BY id DESC", (collection, )
        );
        raw = cur.fetchall();
        conn.close();
        found: list = [];
        for r in raw {
            doc = json.loads(r[0]);
            if all(doc.get(k) == v for (k, v) in query.items()) {
                found.append(doc);
