{"file_path": "/workspace/services/graph/localdb.jac", "content": """"Rentora local SQLite log store: SMS, walker runs, notifications and generic docs."""

import os;
import sqlite3;
import json;
import from datetime { datetime }

glob _db_path: str = os.path.join(os.getcwd(), ".jac", "data", "app.db");
glob _tables_ready: dict = {"ready": False};

def _to_str(v: any) -> str {
    return str(v);
}

def _dump(v: any) -> str {
    return json.dumps(v, default=_to_str);
}

def _ensure_tables() -> None {
    if _tables_ready["ready"] {
        return;
    }
    os.makedirs(os.path.dirname(_db_path), exist_ok=True);
    conn = sqlite3.connect(_db_path);
    conn.execute(
        "CREATE TABLE IF NOT EXISTS sms_messages (id INTEGER PRIMARY KEY AUTOINCREMENT, from_number TEXT, to_number TEXT, body TEXT, direction TEXT, sid TEXT, unit_id TEXT, tenant_name TEXT, created_at TEXT)"
    );
    conn.execute(
        "CREATE TABLE IF NOT EXISTS walker_logs (id INTEGER PRIMARY KEY AUTOINCREMENT, walker_name TEXT, unit_id TEXT, input_data TEXT, output_data TEXT, duration_ms INTEGER, created_at TEXT)"
    );
    conn.execute(
        "CREATE TABLE IF NOT EXISTS notifications (id INTEGER PRIMARY KEY AUTOINCREMENT, notification_type TEXT, payload TEXT, ticket_id TEXT, is_read INTEGER DEFAULT 0, created_at TEXT)"
    );
    conn.execute(
        "CREATE TABLE IF NOT EXISTS documents (id INTEGER PRIMARY KEY AUTOINCREMENT, collection TEXT, doc TEXT, created_at TEXT)"
    );
    conn.commit();
    conn.close();
    _tables_ready["ready"] = True;
}

def _rows(cur: any) -> list {
    cols = [d[0] for d in cur.description];
    return [dict(zip(cols, r)) for r in cur.fetchall()];
}

def:pub log_sms(
    from_number: str,
    to_number: str,
    body: str,
    direction: str,
    sid: str = "",
    unit_id: str = "",
