import from services.graph.models {
    Property,
    Unit,
    Lease,
    Tenant,
    Ticket,
    Vendor,
    HasUnit,
    HasLease,
    HasTenant,
    HasTicket,
    Services
}
import from services.graph.localdb { check_db_health }

walker list_properties {
    can list_all with Root entry {
        result: list = [];
        for p in [here -->](?:Property) {
            units = [p ->:HasUnit:->](?:Unit);
            result.append(
                {
                    "id": jid(p),
                    "name": p.name,
                    "address": p.address,
                    "city": p.city,
                    "state": p.state,
                    "unit_count": len(units)
                }
            );
        }
        report result;
    }
}

walker list_units {
    can start with Root entry {
        visit [here -->](?:Property);
    }

    can gather with Property entry {
        for u in [here ->:HasUnit:->](?:Unit) {
            tenant_name = "";
            tenant_phone = "";
            payment_status = "";
            rent = 0.0;
            lease_end = "";
            leases = [u ->:HasLease:->](?:Lease);
            if len(leases) > 0 {
                lease = leases[0];
                rent = lease.rent_amount;
                lease_end = lease.end_date;
                tenants = [lease ->:HasTenant:->](?:Tenant);
                if len(tenants) > 0 {
                    tenant_name = tenants[0].name;
                    tenant_phone = tenants[0].phone;
                    payment_status = tenants[0].payment_status;
                }
            }
            tickets = [u ->:HasTicket:->](?:Ticket);
            open_count = 0;
            for t in tickets {
                if t.status != "resolved" {
                    open_count += 1;
                }
            }
            report {
                "id": jid(u),
                "unit": u.number,
                "bedrooms": u.bedrooms,
                "bathrooms": u.bathrooms,
                "sq_ft": u.sq_ft,
                "status": u.status,
                "property": here.name,
                "tenant": tenant_name,
                "tenant_phone": tenant_phone,
                "payment_status": payment_status,
                "rent": rent,
                "lease_end": lease_end,
                "open_tickets": open_count,
                "total_tickets": len(tickets)
            };
        }
    }
}

walker list_tickets {
    can start with Root entry {
        visit [here -->](?:Property);
    }

    can at_property with Property entry {
        visit [here ->:HasUnit:->](?:Unit);
    }

    can at_unit with Unit entry {
        for t in [here ->:HasTicket:->](?:Ticket) {
            report {
                "id": jid(t),
                "ticket_id": t.ticket_id,
                "unit": here.number,
                "category": t.category,
                "description": t.description,
                "urgency": t.urgency,
                "status": t.status,
                "ai_summary": t.ai_summary,
                "recommended_action": t.recommended_action,
                "vendor_name": t.vendor_name,
                "estimated_cost": t.estimated_cost,
                "tenant_reply": t.tenant_reply,
                "owner_alert": t.owner_alert,
                "created_at": t.created_at,
                "resolved_at": t.resolved_at
            };
        }
    }
}

walker list_vendors {
    can start with Root entry {
        visit [here -->](?:Property);
    }

    can at_property with Property entry {
        for v in [here ->:Services:->](?:Vendor) {
            report {
                "id": jid(v),
                "name": v.name,
                "category": v.category,
                "phone": v.phone,
                "email": v.email,
                "rating": v.rating,
                "avg_cost": v.avg_cost,
                "available": v.available,
                "property": here.name
            };
        }
    }
}

walker register_tenant {
    has tenant_name: str = "";
    has tenant_phone: str = "";
    has tenant_email: str = "";
    has unit_number: str = "";
    has rent_amount: float = 0.0;
    has lease_start: str = "";
    has lease_end: str = "";
    has property_name: str = "";

    can start with Root entry {
        visit [here -->](?:Property);
    }

    can find_unit with Property entry {
        if self.property_name and here.name != self.property_name {
            return;
        }
        target: Unit | None = None;
        for u in [here ->:HasUnit:->](?:Unit) {
            if u.number.lower() == self.unit_number.lower() {
                target = u;
                break;
            }
        }
        if target is None {
            target = Unit(number=self.unit_number.upper());
            here +>:HasUnit:+> target;
        }
        for existing_lease in [target ->:HasLease:->](?:Lease) {
            for existing in [existing_lease ->:HasTenant:->](?:Tenant) {
                if existing.phone == self.tenant_phone {
                    report {
                        "status": "already_registered",
                        "tenant": existing.name,
                        "phone": existing.phone,
                        "unit": target.number,
                        "property": here.name,
                        "id": jid(existing)
                    };
                    disengage;
                }
            }
        }
        lease = Lease(
            start_date=self.lease_start,
            end_date=self.lease_end,
            rent_amount=self.rent_amount,
            deposit=self.rent_amount
        );
        target +>:HasLease:+> lease;
        tenant = Tenant(
            name=self.tenant_name,
            phone=self.tenant_phone,
            email=self.tenant_email,
            move_in_date=self.lease_start
        );
        lease +>:HasTenant:+> tenant;
        report {
            "status": "registered",
            "tenant": tenant.name,
            "phone": tenant.phone,
            "unit": target.number,
            "property": here.name,
            "id": jid(tenant)
        };
        disengage;
    }
}

walker db_health {
    can check with Root entry {
        report {"database": check_db_health(), "graph_store": "ok"};
    }
}

walker list_tenants {
    can list_all with Root entry {
        result: list = [];
        for p in [here -->](?:Property) {
            for u in [p ->:HasUnit:->](?:Unit) {
                for lease in [u ->:HasLease:->](?:Lease) {
                    for t in [lease ->:HasTenant:->](?:Tenant) {
                        result.append(
                            {
                                "id": jid(t),
                                "full_name": t.name,
                                "phone_number": t.phone,
                                "unit_number": u.number,
                                "property_id": jid(p),
                                "property_name": p.name,
                                "rent": lease.rent_amount,
                                "lease_end": lease.end_date
                            }
                        );
                    }
                }
            }
        }
        report result;
    }
}

walker add_property_node {
    has name: str = "";
    has address: str = "";
    has unit_numbers: list = [];

    can create with Root entry {
        prop = Property(name=self.name, address=self.address);
        here ++> prop;
        for n in self.unit_numbers {
            unit = Unit(number=str(n));
            prop +>:HasUnit:+> unit;
        }
        report {
            "status": "created",
            "id": jid(prop),
            "property": self.name,
            "units": len(self.unit_numbers)
        };
    }
}

walker delete_tenant_node {
    has tenant_id: str = "";
    has deleted: bool = False;

    can start with Root entry {
        visit [here -->](?:Property);
    }

    can at_property with Property entry {
        for u in [here ->:HasUnit:->](?:Unit) {
            for lease in [u ->:HasLease:->](?:Lease) {
                for t in [lease ->:HasTenant:->](?:Tenant) {
                    if jid(t) == self.tenant_id {
                        del t;
                        self.deleted = True;
                        report {"status": "deleted"};
                        disengage;
                    }
                }
            }
        }
    }

    can not_found with Root exit {
        if not self.deleted {
            report {"status": "not_found", "tenant_id": self.tenant_id};
        }
    }
}

walker delete_property_node {
    has property_id: str = "";

    can start with Root entry {
        for p in [here -->](?:Property) {
            if jid(p) == self.property_id {
                del p;
                report {"status": "deleted"};
                return;
            }
        }
        report {"status": "not_found"};
    }
}

walker match_tenant {
    has phone: str = "";
    has matched: bool = False;

    can start with Root entry {
        visit [here -->](?:Property);
    }

    can at_property with Property entry {
        for u in [here ->:HasUnit:->](?:Unit) {
            for lease in [u ->:HasLease:->](?:Lease) {
                for t in [lease ->:HasTenant:->](?:Tenant) {
                    if t.phone == self.phone {
                        self.matched = True;
                        report {
                            "matched": True,
                            "tenant_name": t.name,
                            "property_name": here.name,
                            "unit": u.number
                        };
                        disengage;
                    }
                }
            }
        }
    }

    can not_found with Root exit {
        if not self.matched {
            report {"matched": False};
        }
    }
}
"}

