    }

    can at_property with Property entry {
        for u in [here ->:HasUnit:->][?:Unit] {
            for lease in [u ->:HasLease:->][?:Lease] {
                for t in [lease ->:HasTenant:->][?:Tenant] {
                    if jid(t) == self.tenant_id {
                        del t;
                        self.deleted = True;
                        report {"status": "deleted"};
                        disengage;
                    }
                }
            }
        }
    }

    can not_found with Root exit {
        if not self.deleted {
            report {"status": "not_found", "tenant_id": self.tenant_id};
        }
    }
}

walker delete_property_node {
    has property_id: str = "";

    can start with Root entry {
        for p in [here -->][?:Property] {
            if jid(p) == self.property_id {
                del p;
                report {"status": "deleted"};
                return;
            }
        }
        report {"status": "not_found"};
    }
}

walker match_tenant {
    has phone: str = "";
    has matched: bool = False;

    can start with Root entry {
        visit [here -->][?:Property];
    }

    can at_property with Property entry {
        for u in [here ->:HasUnit:->][?:Unit] {
            for lease in [u ->:HasLease:->][?:Lease] {
                for t in [lease ->:HasTenant:->][?:Tenant] {
                    if t.phone == self.phone {
                        self.matched = True;
                        report {
                            "matched": True,
                            "tenant_name": t.name,
                            "property_name": here.name,
                            "unit": u.number
                        };
                        disengage;
                    }
                }
            }
        }
    }

    can not_found with Root exit {
        if not self.matched {
            report {"matched": False};
        }
    }
}
"}

{"file_path": "/workspace/services/graph/actions.jac", "content": """"Rentora ticket action walkers: dispatch approval and resolution."""

import from datetime { datetime }
import from services.graph.models { Property, Unit, Ticket, HasUnit, HasTicket }

walker approve_dispatch {
    has ticket_id: str = "";

    can start with Root entry {
        visit [here -->][?:Property];
    }

    can at_property with Property entry {
        visit [here ->:HasUnit:->][?:Unit];
    }

    can at_unit with Unit entry {
        for t in [here ->:HasTicket:->][?:Ticket] {
            if t.ticket_id == self.ticket_id {
                t.status = "dispatched";
                report {
                    "ticket_id": t.ticket_id,
                    "status": "dispatched",
                    "vendor_name": t.vendor_name,
                    "unit": here.number,
                    "tenant_reply": t.tenant_reply,
                    "owner_alert": t.owner_alert,
                    "estimated_cost": t.estimated_cost
                };
                disengage;
            }
        }
    }
}

walker resolve_ticket {
    has ticket_id: str = "";

    can start with Root entry {
        visit [here -->][?:Property];
    }

    can at_property with Property entry {
        visit [here ->:HasUnit:->][?:Unit];
    }

    can at_unit with Unit entry {
        for t in [here ->:HasTicket:->][?:Ticket] {
            if t.ticket_id == self.ticket_id {
                t.status = "resolved";
                t.resolved_at = datetime.now().strftime("%Y-%m-%d %H:%M:%S");
                report {
                    "ticket_id": t.ticket_id,
                    "status": "resolved",
                    "resolved_at": t.resolved_at
                };
                disengage;
            }
        }
    }
}
"}

