{"file_path": "/workspace/app/services/memory_store.jac", "content": """"In-memory RepoGhost store: session run history and per-repository project memory."""

import from datetime { datetime }
import from app.models.workflow { WorkflowRequest }
import from app.models.outputs { WorkflowResultBundle }

glob SESSION_RUNS: list[dict] = [];
glob PROJECT_MEMORY: dict[str, dict] = {};

"""Record a workflow request with the bundle's action-plan headline."""
def:pub remember_session(request: WorkflowRequest, bundle: WorkflowResultBundle) -> dict {
    record: dict = {
        "repo_path": request.repo_path,
        "mode": request.mode,
        "prompt": request.prompt,
        "saved_at": str(datetime.now()),
        "headline": bundle.action_plan.headline
    };
    SESSION_RUNS.append(record);
    return record;
}

"""Return every remembered session run, oldest first."""
def:pub recent_session_runs() -> list[dict] {
    return SESSION_RUNS;
}

"""Keep the decision, blocker and ticket titles from a bundle for a repository."""
def:pub update_project_memory(repo_path: str, bundle: WorkflowResultBundle) -> dict {
    key: str = repo_path or "default";
    memory: dict = {
        "decisions": [d.title for d in bundle.decisions],
        "blockers": [b.title for b in bundle.blockers],
        "tickets": [t.title for t in bundle.tickets],
        "updated_at": str(datetime.now())
    };
    PROJECT_MEMORY[key] = memory;
    return memory;
}

"""Return stored memory for a repository, or an empty default."""
def:pub get_project_memory(repo_path: str) -> dict {
    key: str = repo_path or "default";
    if key in PROJECT_MEMORY {
        return PROJECT_MEMORY[key];
    }
    return {"decisions": [], "blockers": [], "tickets": [], "updated_at": ""};
}
"}

{"file_path": "/workspace/tests/test_memory_store.jac", "content": """"Behavior tests for the RepoGhost in-memory store. Repository paths are unique per test because module state persists."""

import from app.models.core { DecisionItem, BlockerItem }
import from app.models.workflow { WorkflowRequest }
import from app.models.outputs { ActionPlan, GeneratedTicket, WorkflowResultBundle }
import from app.services.memory_store {
    remember_session,
    recent_session_runs,
    update_project_memory,
    get_project_memory
}

test "remember_session records request fields and headline" {
    req = WorkflowRequest(repo_path="/repos/session-a", prompt="Plan auth", mode="feature_plan");
    bundle = WorkflowResultBundle(action_plan=ActionPlan(headline="Ship auth first"));
    rec = remember_session(req, bundle);
    assert rec["repo_path"] == "/repos/session-a";
    assert rec["mode"] == "feature_plan";
    assert rec["prompt"] == "Plan auth";
    assert rec["saved_at"] != "";
    assert rec["headline"] == "Ship auth first";
}

test "recent_session_runs grows and includes the new record" {
    before = len(recent_session_runs());
    req = WorkflowRequest(repo_path="/repos/session-b", prompt="Review", mode="review");
    rec = remember_session(req, WorkflowResultBundle());
    runs = recent_session_runs();
    assert len(runs) == before + 1;
    assert rec in runs;
}

test "update_project_memory keeps titles and get_project_memory returns them" {
    bundle = WorkflowResultBundle(
        decisions=[DecisionItem(title="Use Postgres")],
        blockers=[BlockerItem(title="Missing API key")],
        tickets=[GeneratedTicket(title="Add login"), GeneratedTicket(title="Add logout")]
    );
    mem = update_project_memory("/repos/memory-a", bundle);
    assert mem["decisions"] == ["Use Postgres"];
    assert mem["blockers"] == ["Missing API key"];
    assert mem["tickets"] == ["Add login", "Add logout"];
    assert mem["updated_at"] != "";
    assert get_project_memory("/repos/memory-a") == mem;
}

test "unknown repo returns empty default and empty path uses default key" {
    empty = get_project_memory("/repos/never-seen");
    assert empty["decisions"] == [];
    assert empty["blockers"] == [];
    assert empty["tickets"] == [];
    assert empty["updated_at"] == "";
    mem = update_project_memory("", WorkflowResultBundle(decisions=[DecisionItem(title="Default decision")]));
    assert get_project_memory("default") == mem;
    assert get_project_memory("")["decisions"] == ["Default decision"];
}
"}

