{"file_path": "/workspace/graph/activity.jac", "content": """"Trace activity helpers: ISO time, plain status wording, agent activity log."""

import from datetime { datetime, timezone }
import from graph.nodes { ActivityEntry }

glob PLAIN_STATUS: dict[str, str] = {
    "MISSING": "reported missing",
    "FOUND_SAFE": "reported safe",
    "INJURED": "reported injured",
    "DECEASED": "reported deceased",
    "SEEN_AT_LOCATION": "seen at a location"
};

"""Current UTC time as an ISO string with seconds precision."""
def now_iso() -> str {
    return datetime.now(timezone.utc).replace(microsecond=0).isoformat();
}

"""Turn a claim code such as FOUND_SAFE into plain words."""
def plain_status(claim_type: str) -> str {
    code = claim_type.strip().upper();
    if code in PLAIN_STATUS {
        return PLAIN_STATUS[code];
    }
    return claim_type.strip().lower().replace("_", " ");
}

"""Connect a new ActivityEntry for an agent action to root."""
def log_activity(walker_name: str, message: str, incident_id: str = "") -> None {
    entry = ActivityEntry(
        walker_name=walker_name,
        message=message,
        created_at=now_iso(),
        incident_id=incident_id
    );
    root ++> entry;
}
"}

{"file_path": "/workspace/services/timeline.jac", "content": """"Trace person timeline: a read-only cited history for one person in one incident."""

import json;
import from datetime { datetime, timezone }
import from graph.nodes { Incident, Person, Claim, Alert, InvestigationRun }
import from graph.edges {
    Involves,
    About,
    Asserts,
    HasSubscription,
    Receives,
    HasInvestigation
}

glob TIMELINE_LIMIT: int = 50;

"""One cited row in a person's timeline (kind: claim, alert or investigation)."""
obj TimelineEntry {
    has id: str,
        kind: str,
        person_id: str,
        claim_id: str = "",
        source_name: str = "",
        source_ids: list[str] = [],
        claim_type: str = "",
        reported_at: str = "",
        ingested_at: str = "",
        source_reference: str = "",
        recorded_at: str = "",
        text: str = "",
        status: str = "",
        mode: str = "",
        subscriber_names: list[str] = [],
        status_changed: bool = False,
        previous_claim_id: str = "",
        previous_claim_type: str = "",
        total_entries: int = 0;
}

"""Parse an ISO timestamp into epoch seconds; unparseable values sort first."""
def _parse_ts(value: str) -> float {
    text = value.strip();
    if not text {
        return 0.0;
    }
    if text.endswith("Z") {
        text = text[:-1] + "+00:00";
    }
    try {
        parsed = datetime.fromisoformat(text);
        if parsed.tzinfo is None {
            parsed = parsed.replace(tzinfo=timezone.utc);
        }
        return parsed.timestamp();
    } except Exception {
        return 0.0;
    }
}

"""Rank used to break ties between rows recorded at the same moment."""
def _kind_rank(kind: str) -> int {
    if kind == "claim" {
        return 0;
    }
    if kind == "alert" {
        return 1;
    }
    return 2;
}

"""Sort key for claim rows: reported time, ingested time, source, kind."""
def _claim_key(row: TimelineEntry) -> tuple {
    return (
        _parse_ts(row.reported_at),
        _parse_ts(row.ingested_at),
        row.source_name,
        _kind_rank(row.kind)
    );
}

"""Sort key for all rows: event time (reported or recorded), then kind."""
def _row_key(row: TimelineEntry) -> tuple {
    moment = row.reported_at if row.kind == "claim" else row.recorded_at;
    return (
        _parse_ts(moment),
        _kind_rank(row.kind),
        _parse_ts(row.ingested_at),
        row.source_name
    );
}

"""Cited history for one person in one incident: claims, alerts and investigation runs."""
def:pub person_timeline(incident_id: str, person_id: str) -> list[TimelineEntry] {
    incident: Incident | None = None;
    for node_ in [root -->] {
        if isinstance(node_, Incident) and jid(node_) == incident_id {
            incident = node_;
            break;
        }
    }
    if incident is None {
        return [];
    }
    person: Person | None = None;
    for candidate in [incident ->:Involves:->] {
        if isinstance(candidate, Person) and jid(candidate) == person_id {
            person = candidate;
            break;
        }
    }
    if person is None {
        return [];
    }

    claim_rows: list[TimelineEntry] = [];
    claim_by_id: dict[str, TimelineEntry] = {};
    for claim in [person <-:About:<-] {
        if not isinstance(claim, Claim) {
            continue;
        }
        if claim.incident_id and claim.incident_id != incident_id {
            continue;
        }
        cid = jid(claim);
        if cid in claim_by_id {
            continue;
        }
        names: list[str] = [];
        ids: list[str] = [];
        for src in [claim <-:Asserts:<-] {
            names.append(src.name);
            ids.append(jid(src));
        }
        row = TimelineEntry(
            id=cid,
            kind="claim",
            person_id=person_id,
            claim_id=cid,
            source_name="; ".join(names),
            source_ids=ids,
            claim_type=claim.claim_type,
            reported_at=claim.timestamp,
            ingested_at=claim.ingested_at,
            source_reference=claim.source_reference,
            recorded_at=claim.ingested_at,
            text=claim.value or claim.notes or claim.original_content
        );
        claim_rows.append(row);
        claim_by_id[cid] = row;
    }
    claim_rows = sorted(claim_rows, key=_claim_key);
    previous: TimelineEntry | None = None;
    for row in claim_rows {
        if previous is not None {
            row.previous_claim_id = previous.claim_id;
            row.previous_claim_type = previous.claim_type;
            row.status_changed = previous.claim_type != row.claim_type;
        }
        previous = row;
    }

    rows: list[TimelineEntry] = list(claim_rows);

    alert_rows: dict[str, TimelineEntry] = {};
    for sub in [person ->:HasSubscription:->] {
        for alert in [sub ->:Receives:->] {
            if not isinstance(alert, Alert) {
                continue;
            }
            aid = jid(alert);
            if aid in alert_rows {
                if sub.subscriber_name not in alert_rows[aid].subscriber_names {
                    alert_rows[aid].subscriber_names.append(sub.subscriber_name);
                }
                continue;
            }
            linked = claim_by_id.get(alert.claim_id) if alert.claim_id else None;
            arow = TimelineEntry(
                id=aid,
                kind="alert",
                person_id=person_id,
                claim_id=linked.claim_id if linked is not None else "",
                source_name=linked.source_name if linked is not None else "",
                source_ids=list(linked.source_ids) if linked is not None else [],
                claim_type=linked.claim_type if linked is not None else "",
                source_reference=linked.source_reference if linked is not None else "",
                recorded_at=alert.created_at,
                text=alert.message,
                status=alert.severity,
                subscriber_names=[sub.subscriber_name]
            );
            alert_rows[aid] = arow;
            rows.append(arow);
        }
    }

    for run in [incident ->:HasInvestigation:->] {
        if not isinstance(run, InvestigationRun) or run.person_id != person_id {
            continue;
        }
        data: dict = {};
        try {
            parsed = json.loads(run.result_json) if run.result_json else {};
            if isinstance(parsed, dict) {
                data = parsed;
            }
        } except Exception {
            data = {};
        }
        cited_id = "";
        citations = data.get("citations", []);
        if isinstance(citations, list) and len(citations) > 0 and isinstance(citations[0], dict) {
            cited_id = str(citations[0].get("claim_id", ""));
        }
        linked = claim_by_id.get(cited_id) if cited_id else None;
        rrow = TimelineEntry(
            id=jid(run),
            kind="investigation",
            person_id=person_id,
            claim_id=linked.claim_id if linked is not None else "",
            source_name=linked.source_name if linked is not None else "",
            source_ids=list(linked.source_ids) if linked is not None else [],
            claim_type=linked.claim_type if linked is not None else "",
            source_reference=linked.source_reference if linked is not None else "",
            recorded_at=str(data.get("run_at", "") or run.created_at),
            text=str(data.get("message", "")),
            status=str(data.get("status", "")),
            mode=str(data.get("mode", "") or run.mode)
        );
        rows.append(rrow);
    }

    rows = sorted(rows, key=_row_key);
    total = len(rows);
    if total > TIMELINE_LIMIT {
        rows = rows[total - TIMELINE_LIMIT:];
    }
    for row in rows {
        row.total_entries = total;
    }
    return rows;
}
"}

