{"file_path": "/workspace/abilities/llm_abilities.jac", "content": """"LLM abilities for document intake: classification and plain-English translation."""

import from os { environ }
import from jaclang.byllm.lib { Model }

glob llm = Model(
    model_name="openrouter/anthropic/claude-4.6-sonnet",
    api_key=environ.get("OPENROUTER_API_KEY", "")
);

def classify_document(raw_text: str, source_metadata: dict) -> str by llm(model=llm);
sem classify_document = "Classify an incoming eldercare document. Return ONLY one category name from: EOB, MSN_PART_A, MSN_PART_B, MEDICAL_BILL, CMS1500_CLAIM, UB04_CLAIM, INSURANCE_NOTICE, POLICY_CHANGE, HIPAA_AUTH, POWER_OF_ATTORNEY, WILL, TRUST, BENEFICIARY_FORM, LEGAL_NOTICE, FINANCIAL_STATEMENT, APPOINTMENT_CONFIRMATION, PRESCRIPTION_NOTICE, SCAM_COMMUNICATION, UNKNOWN.";
sem classify_document.raw_text = "The raw text content of the document to classify.";
sem classify_document.source_metadata = "Metadata about where the document came from: source, filename and mime_type.";

def translate_to_plain_english(
    technical_content: str, content_type: str, reading_level: int = 6
) -> str by llm(model=llm);
sem translate_to_plain_english = "Rewrite technical medical billing or legal content in plain English at about the given school-grade reading level for a 75-year-old reader. End with a one-sentence 'Bottom line:' summary.";
sem translate_to_plain_english.technical_content = "The technical document text to rewrite.";
sem translate_to_plain_english.content_type = "The document category, such as EOB or MEDICAL_BILL.";
sem translate_to_plain_english.reading_level = "Target school-grade reading level, about 6.";
"}

{"file_path": "/workspace/graph/walkers/intake/document_classify.jac", "content": """"DocumentClassify walker: classifies a Patient's UNKNOWN documents."""

import from graph.nodes.patient { Patient }
import from graph.nodes.document { Document }
import from abilities.llm_abilities { classify_document }

walker DocumentClassify {
    """Visit the Patient's documents in connection order."""
    can start with Patient entry {
        visit [-->];
    }

    """Classify an UNKNOWN document, or stop the whole walk at the first one already classified."""
    can classify with Document entry {
        if here.classification != "UNKNOWN" {
            disengage;
        }
        source_meta = {
            "source": here.source,
            "filename": here.original_filename,
            "mime_type": here.mime_type
        };
        category = classify_document(
            raw_text=here.raw_content, source_metadata=source_meta
        );
        here.classification = category;
        print(f"[DocumentClassify] Document {here.doc_id} classified as: {category}");
    }
}
"}

{"file_path": "/workspace/graph/walkers/intake/plain_english_translator.jac", "content": """"PlainEnglishTranslator walker: writes plain-English summaries for a Patient's documents."""

import from graph.nodes.patient { Patient }
import from graph.nodes.document { Document }
import from abilities.llm_abilities { translate_to_plain_english }

walker PlainEnglishTranslator {
    """Visit the Patient's documents in connection order."""
    can start with Patient entry {
        visit [-->];
    }

    """Summarise a document that has content and no summary, or stop the whole walk at the first one to skip."""
    can translate with Document entry {
        if here.plain_english_summary != "" or here.raw_content == "" {
            disengage;
        }
        summary = translate_to_plain_english(
            technical_content=here.raw_content[:4000],
            content_type=here.classification,
            reading_level=6
        );
        here.plain_english_summary = summary;
        print(f"[PlainEnglishTranslator] Translated doc {here.doc_id} ({here.classification})");
    }
}
"}

{"file_path": "/workspace/tests/test_intake.jac", "content": """"Tests for the intake walkers, with the model swapped for MockLLM."""

import from jaclang.byllm.lib { MockLLM }
import abilities.llm_abilities as m;
import from graph.nodes.patient { Patient }
import from graph.nodes.document { Document }
import from graph.walkers.intake.document_classify { DocumentClassify }
import from graph.walkers.intake.plain_english_translator { PlainEnglishTranslator }

test "classify sets UNKNOWN documents in connection order" {
    m.llm = MockLLM(model_name="mockllm", config={"outputs": ["EOB", "WILL"]});
    p = Patient(name="Ann");
    root ++> p;
    d1 = Document(doc_id="d1", raw_content="Explanation of benefits for claim 123");
    d2 = Document(doc_id="d2", raw_content="Last will and testament");
    p ++> d1;
    p ++> d2;
    p spawn DocumentClassify();
    assert d1.classification == "EOB";
    assert d2.classification == "WILL";
}

test "classify stops the whole walk at first non-UNKNOWN document" {
    m.llm = MockLLM(model_name="mockllm", config={"outputs": ["EOB"]});
    p = Patient(name="Bob");
    root ++> p;
    d1 = Document(doc_id="d1", raw_content="Trust deed", classification="TRUST");
    d2 = Document(doc_id="d2", raw_content="Medical bill");
    p ++> d1;
    p ++> d2;
    p spawn DocumentClassify();
    assert d1.classification == "TRUST";
    assert d2.classification == "UNKNOWN";
    assert m.classify_document(raw_text="x", source_metadata={}) == "EOB";
}

test "translator stores summary for document with content and no summary" {
    m.llm = MockLLM(model_name="mockllm", config={"outputs": ["You owe nothing. Bottom line: no payment needed."]});
    p = Patient(name="Cara");
    root ++> p;
    d1 = Document(doc_id="d1", raw_content="EOB: patient responsibility $0.00", classification="EOB");
    p ++> d1;
    p spawn PlainEnglishTranslator();
    assert d1.plain_english_summary == "You owe nothing. Bottom line: no payment needed.";
    assert d1.classification == "EOB";
}

test "translator stops the whole walk at first document to skip" {
    m.llm = MockLLM(model_name="mockllm", config={"outputs": ["SHOULD NOT BE USED"]});
    p = Patient(name="Dan");
    root ++> p;
    d1 = Document(doc_id="d1", raw_content="");
    d2 = Document(doc_id="d2", raw_content="Medical bill text");
    p ++> d1;
    p ++> d2;
    p spawn PlainEnglishTranslator();
    assert d1.plain_english_summary == "";
    assert d2.plain_english_summary == "";

    p2 = Patient(name="Eve");
    root ++> p2;
    e1 = Document(doc_id="e1", raw_content="Bill", plain_english_summary="Existing");
    e2 = Document(doc_id="e2", raw_content="Another bill");
    p2 ++> e1;
    p2 ++> e2;
    p2 spawn PlainEnglishTranslator();
    assert e1.plain_english_summary == "Existing";
    assert e2.plain_english_summary == "";
}

test "classify then translate fills both fields from consecutive outputs" {
    m.llm = MockLLM(model_name="mockllm", config={"outputs": ["MEDICAL_BILL", "This is a bill. Bottom line: pay $20."]});
    p = Patient(name="Fay");
    root ++> p;
    d1 = Document(doc_id="d1", raw_content="Statement: amount due $20.00");
    p ++> d1;
    p spawn DocumentClassify();
    p spawn PlainEnglishTranslator();
    assert d1.classification == "MEDICAL_BILL";
    assert d1.plain_english_summary == "This is a bill. Bottom line: pay $20.";
}
"}

