{"file_path": "/workspace/server/timeutil.jac", "content": """"Time helpers: times are minutes from midnight, days are 0=Mon..6=Sun."""

import from datetime { date, timedelta }

glob DAY_SHORT: list[str] = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"],
     DAY_LONG: list[str] = [
         "Monday",
         "Tuesday",
         "Wednesday",
         "Thursday",
         "Friday",
         "Saturday",
         "Sunday"
     ];

"""Zero-padded HH:MM for minutes from midnight."""
def hm(minutes: int) -> str {
    hh: int = minutes // 60;
    mm: int = minutes % 60;
    return f"{hh:02d}:{mm:02d}";
}

"""Minutes from midnight for an H:MM string; a missing minute part counts as 0."""
def parse_hm(text: str) -> int {
    parts: list[str] = text.strip().split(":");
    hh: int = int(parts[0]);
    mm: int = 0;
    if len(parts) > 1 and parts[1].strip() {
        mm = int(parts[1].strip());
    }
    return hh * 60 + mm;
}

"""Label such as Mon 09:00-12:00 (en dash)."""
def slot_label(day: int, start: int, end: int) -> str {
    return f"{DAY_SHORT[day]} {hm(start)}\u2013{hm(end)}";
}

"""Length of an interval in hours."""
def hours(start: int, end: int) -> float {
    return (end - start) / 60;
}

"""True when two half-open intervals overlap; touching intervals do not."""
def overlaps(a_start: int, a_end: int, b_start: int, b_end: int) -> bool {
    return a_start < b_end and b_start < a_end;
}

"""Monday of the week containing d."""
def monday_of(d: date) -> date {
    return d - timedelta(days=d.weekday());
}

"""ISO Monday key for date text d, or dflt when d is empty."""
def week_key(d: str, dflt: date) -> str {
    if not d {
        return dflt.isoformat();
    }
    return monday_of(date.fromisoformat(d)).isoformat();
}

"""Integer text when h is whole, otherwise one decimal."""
def fmt_hours(h: float) -> str {
    if h == int(h) {
        return str(int(h));
    }
    return f"{h:.1f}";
}

"""Compact general-format number text."""
def g(v: float) -> str {
    return f"{v:g}";
}

"""Singular or plural word for n."""
def plural(n: int | float, word: str, many: str = "") -> str {
    if n == 1 {
        return word;
    }
    return many or (word + "s");
}
"}

{"file_path": "/workspace/server/models.jac", "content": """"Graph nodes for CampusSync; records reference each other by jid strings."""

import from server.config {
    INTERNATIONAL_WEEKLY_CAP,
    MAX_DAILY_HOURS,
    MAX_DAILY_HOURS_WORKER
}

"""A department or business that schedules shifts."""
node Employer {
    has name: str = "",
        type: str = "department",
        kind: str = "business",
        university: str = "",
        join_code: str = "",
        timezone: str = "America/New_York",
        default_pay_rate: float = 15.0,
        default_weekly_hours: int = 20,
        state_tax_pct: float = 4.25,
        description: str = "",
        created: str = "",
        auto_generate: bool = True,
        auto_recruit: bool = True,
        auto_approve_swaps: bool = False;
}

"""A student or worker who can hold shifts."""
node Employee {
    has name: str = "",
        email: str = "",
        student_number: str = "",
        kind: str = "student",
        school: str = "",
        status: str = "domestic",
        weekly_limit: int = 20,
        desired_hours: int = 12,
        preferences: list[str] = [],
        open_swap_days: list[int] = [],
        autopilot: bool = True,
        note: str = "",
        calendar_source: str = "",
        calendar_url: str = "",
        google_refresh_token: str = "",
        google_email: str = "",
        google_calendar_id: str = "",
        shifts_signature: str = "",
        calendar_synced_at: str = "",
        calendar_error: str = "",
        demo_events: list[dict[str, any]] = [],
        created: str = "";

    """First space-separated word of the name."""
    def first_name() -> str {
        parts: list[str] = self.name.split();
        if parts {
            return parts[0];
        }
        return "";
    }

    """True for international students only."""
    def is_international() -> bool {
        return self.kind == "student" and self.status == "international";
    }

    """Weekly hour cap."""
    def cap() -> int {
        if self.is_international() {
            return min(
                self.weekly_limit or INTERNATIONAL_WEEKLY_CAP, INTERNATIONAL_WEEKLY_CAP
            );
        }
        return self.weekly_limit;
    }

    """Daily hour maximum."""
    def daily_max() -> int {
        if self.kind == "student" {
            return MAX_DAILY_HOURS;
        }
        return MAX_DAILY_HOURS_WORKER;
    }
}

"""Weekly unavailability; week \"\" means every week."""
node BusyBlock {
    has day: int = 0,
        start: int = 0,
        end: int = 0,
        title: str = "Busy",
        source: str = "calendar",
        week: str = "";
}

"""Membership of an employee on an employer's team."""
node Employment {
    has student: str = "",
        employer: str = "",
        hours: int = 10,
        state: str = "invited",
        positions: list[str] = [],
        pay_rate: float = 15.0,
        created: str = "";
}

"""A scheduled shift for one employer in one week."""
node Shift {
    has employer: str = "",
        week: str = "",
        day: int = 0,
        start: int = 0,
        end: int = 0,
        student: str = "",
        state: str = "assigned",
        status: str = "published",
        draft: str = "",
        reason: str = "",
        source: str = "generated",
        position: str = "",
        created: str = "";

    """Shift length in hours."""
    def hours() -> float {
        return (self.end - self.start) / 60;
    }
}

"""Employer node for an id, or None."""
def employer_of(id: str) -> Employer | None {
    if not id {
        return None;
    }
    n = jobj(id);
    if isinstance(n, Employer) {
        return n;
    }
    return None;
}

"""Employee node for an id, or None."""
def employee_of(id: str) -> Employee | None {
    if not id {
        return None;
    }
    n = jobj(id);
    if isinstance(n, Employee) {
        return n;
    }
    return None;
}

"""Shift nodes linked from employee s for week wk with status want."""
def held_shifts(s: Employee, wk: str, want: str = "published") -> list[Shift] {
    out: list[Shift] = [];
    for n in [s -->] {
        if isinstance(n, Shift) and n.week == wk and n.status == want {
            out.append(n);
        }
    }
    return out;
}
"}

{"file_path": "/workspace/server/rules.jac", "content": """"Conflict agent and compliance checker for one week; deterministic."""

import from server.config { MIN_REST_MINUTES }
import from server.timeutil { overlaps }
import from server.models { Employee, BusyBlock, Employment, Shift, employee_of }

glob CONFLICT: str = "schedule_conflict",
     HOUR_LIMIT: str = "hour_limit",
     NOT_ON_TEAM: str = "not_on_team",
     NOT_QUALIFIED: str = "not_qualified",
     _TIMING: list[str] = ["overlap", "rest", "daily_max"],
     _HOURS: list[str] = ["weekly_cap", "dept_hours"],
     _EPS: float = 1e-9;

"""An in-memory held shift."""
obj Held {
    has shift_id: str,
        department_id: str,
        day: int,
        start: int,
        end: int;

    """Shift length in hours."""
    def hours() -> float {
        return (self.end - self.start) / 60;
    }
}

"""An in-memory busy block."""
obj Block {
    has day: int,
        start: int,
        end: int,
        title: str = "Busy";
}

"""Answer to whether an employee may take a proposed shift."""
obj Verdict {
    has ok: bool,
        code: str = "",
        hours_left: float = 0.0,
        cross_department: bool = False;

    """Public reason for the internal code."""
    def public_reason() -> str {
        if self.ok {
            return "";
        }
        if self.code in _TIMING {
            return CONFLICT;
        }
        if self.code in _HOURS {
            return HOUR_LIMIT;
        }
        return self.code;
    }

    """True for timing codes."""
    def is_timing() -> bool {
        return self.code in _TIMING;
    }

    """True for hour-limit codes."""
    def is_hours() -> bool {
        return self.code in _HOURS;
    }
}

"""In-memory schedule ledger for one week."""
obj Ledger {
    has week: str,
        _students: dict[str, Employee] = {},
        _busy: dict[str, list[Block]] = {},
        _held: dict[str, list[Held]] = {},
        _allot: dict[str, int] = {},
        _has_allot: dict[str, bool] = {},
        _roles: dict[str, list[str]] = {};

    def student(sid: str) -> Employee {
        if sid not in self._students {
            st = employee_of(sid);
            if st is None {
                raise ValueError(f"Unknown employee {sid}");
            }
            self._students[sid] = st;
        }
        return self._students[sid];
    }

    def busy(sid: str) -> list[Block] {
        if sid not in self._busy {
            st = self.student(sid);
            out: list[Block] = [];
            for n in [st -->] {
                if isinstance(n, BusyBlock) and (n.week == "" or n.week == self.week) {
                    out.append(Block(day=n.day, start=n.start, end=n.end, title=n.title));
                }
            }
            self._busy[sid] = out;
        }
        return self._busy[sid];
    }

    def held(sid: str) -> list[Held] {
        if sid not in self._held {
            st = self.student(sid);
            out: list[Held] = [];
            for n in [st -->] {
                if isinstance(n, Shift)
                and n.week == self.week
                and n.status == "published"
                and n.student == sid {
                    out.append(
                        Held(
                            shift_id=jid(n),
                            department_id=n.employer,
                            day=n.day,
                            start=n.start,
                            end=n.end
                        )
                    );
                }
            }
            self._held[sid] = out;
        }
        return self._held[sid];
    }

    def _key(sid: str, did: str) -> str {
        return sid + "|" + did;
    }

    def allotment(sid: str, did: str) -> int | None {
        k = self._key(sid, did);
        if k not in self._has_allot {
            st = self.student(sid);
            self._has_allot[k] = True;
            self._roles[k] = [];
            for n in [st -->] {
                if isinstance(n, Employment) and n.employer == did and n.state == "active" {
                    self._allot[k] = n.hours;
                    self._roles[k] = [str(p) for p in n.positions];
                    break;
                }
            }
        }
        if k in self._allot {
            return self._allot[k];
        }
        return None;
    }

    def set_allotment(sid: str, did: str, hours: int | None, roles: list[str]) -> None {
        k = self._key(sid, did);
        self._has_allot[k] = True;
        self._roles[k] = list(roles);
        if hours is None {
            if k in self._allot {
                del self._allot[k];
            }
        } else {
            self._allot[k] = hours;
        }
    }

    def roles(sid: str, did: str) -> list[str] {
        self.allotment(sid, did);
        k = self._key(sid, did);
        if k in self._roles {
            return self._roles[k];
        }
        return [];
    }

    def qualified(sid: str, did: str, pid: str) -> bool {
        return not pid or pid in self.roles(sid, did);
    }

    def clone() -> Ledger {
        led = Ledger(week=self.week);
        led._students = self._students;
        led._busy = self._busy;
        led._allot = dict(self._allot);
        led._has_allot = dict(self._has_allot);
        led._roles = dict(self._roles);
        copied: dict[str, list[Held]] = {};
        for (sid, hs) in self._held.items() {
            copied[sid] = [
                Held(
                    shift_id=h.shift_id,
                    department_id=h.department_id,
                    day=h.day,
                    start=h.start,
                    end=h.end
                )
                for h in hs
            ];
        }
        led._held = copied;
        return led;
    }

    def add(sid: str, h: Held) -> None {
        self.held(sid).append(h);
    }

    def remove(sid: str, shift_id: str) -> None {
        self._held[sid] = [h for h in self.held(sid) if h.shift_id != shift_id];
    }

    def total_hours(sid: str) -> float {
        total: float = 0.0;
        for h in self.held(sid) {
            total += h.hours();
        }
        return total;
    }

    def dept_hours(sid: str, did: str) -> float {
        total: float = 0.0;
        for h in self.held(sid) {
            if h.department_id == did {
                total += h.hours();
            }
        }
        return total;
    }

    def day_hours(sid: str, day: int) -> float {
        total: float = 0.0;
        for h in self.held(sid) {
            if h.day == day {
                total += h.hours();
            }
        }
        return total;
    }

    def cap(sid: str) -> int {
        return self.student(sid).cap();
    }

    def cap_left(sid: str) -> float {
        return max(0.0, self.cap(sid) - self.total_hours(sid));
    }

    def hours_left(sid: str, did: str) -> float {
        allot = self.allotment(sid, did);
        if allot is None {
            return 0.0;
        }
        return max(
            0.0,
            min(
                self.cap(sid) - self.total_hours(sid), allot - self.dept_hours(sid, did)
            )
        );
    }

    def conflict(sid: str, day: int, start: int, end: int, ignore: list[str], did: str) -> Verdict {
        for b in self.busy(sid) {
            if b.day == day and overlaps(start, end, b.start, b.end) {
                return Verdict(ok=False, code="overlap", cross_department=False);
            }
        }
        for h in self.held(sid) {
            if h.shift_id in ignore {
                continue;
            }
            if h.day == day and overlaps(start, end, h.start, h.end) {
                return Verdict(
                    ok=False, code="overlap", cross_department=h.department_id != did
                );
            }
        }
        return Verdict(ok=True);
    }

    def compliance(sid: str, did: str, day: int, start: int, end: int, ignore: list[str]) -> Verdict {
        add: float = (end - start) / 60;
        rest: list[Held] = [h for h in self.held(sid) if h.shift_id not in ignore];
        allot = self.allotment(sid, did);
        if allot is None {
            return Verdict(ok=False, code=NOT_ON_TEAM);
        }
        total: float = 0.0;
        dept: float = 0.0;
        for h in rest {
            total += h.hours();
            if h.department_id == did {
                dept += h.hours();
            }
        }
        cap = self.cap(sid);
        left: float = max(0.0, min(cap - total, allot - dept));
        if total + add > cap + _EPS {
            return Verdict(
                ok=False,
                code="weekly_cap",
                hours_left=left,
                cross_department=total - dept > _EPS
            );
        }
        if dept + add > allot + _EPS {
            return Verdict(ok=False, code="dept_hours", hours_left=left);
        }
        same: list[Held] = [h for h in rest if h.day == day];
        day_total: float = 0.0;
        other: bool = False;
        for h in same {
            day_total += h.hours();
            if h.department_id != did {
                other = True;
            }
        }
        if day_total + add > self.student(sid).daily_max() + _EPS {
            return Verdict(
                ok=False, code="daily_max", hours_left=left, cross_department=other
            );
        }
        for h in same {
            gap: int = (start - h.end) if start >= h.end else (h.start - end);
            if 0 <= gap and gap < MIN_REST_MINUTES {
                return Verdict(
                    ok=False,
                    code="rest",
                    hours_left=left,
                    cross_department=h.department_id != did
                );
            }
        }
        return Verdict(ok=True, hours_left=left);
    }

    def check(
        sid: str,
        did: str,
        day: int,
        start: int,
        end: int,
        ignore: list[str] | None = None,
        pid: str = ""
    ) -> Verdict {
        skip: list[str] = ignore if ignore is not None else [];
        if self.allotment(sid, did) is None {
            return Verdict(ok=False, code=NOT_ON_TEAM);
        }
        if not self.qualified(sid, did, pid) {
            return Verdict(ok=False, code=NOT_QUALIFIED);
        }
        v = self.conflict(sid, day, start, end, skip, did);
        if not v.ok {
            v.hours_left = self.hours_left(sid, did);
            return v;
        }
        return self.compliance(sid, did, day, start, end, skip);
    }

    def violations(sid: str) -> list[str] {
        out: list[str] = [];
        hs = self.held(sid);
        n = len(hs);
        for i in range(n) {
            h = hs[i];
            for b in self.busy(sid) {
                if b.day == h.day and overlaps(h.start, h.end, b.start, b.end) {
                    out.append("overlap");
                }
            }
            for j in range(i + 1, n) {
                o = hs[j];
                if o.day != h.day {
                    continue;
                }
                if overlaps(h.start, h.end, o.start, o.end) {
                    out.append("overlap");
                } else {
                    gap: int = (o.start - h.end) if o.start >= h.end else (h.start - o.end);
                    if gap < MIN_REST_MINUTES {
                        out.append("rest");
                    }
                }
            }
        }
        if self.total_hours(sid) > self.cap(sid) + _EPS {
            out.append("weekly_cap");
        }
        for did in sorted(set([h.department_id for h in hs])) {
            allot = self.allotment(sid, did);
            if allot is None or self.dept_hours(sid, did) > allot + _EPS {
                out.append("dept_hours");
            }
        }
        dmax = self.student(sid).daily_max();
        for d in sorted(set([h.day for h in hs])) {
            if self.day_hours(sid, d) > dmax + _EPS {
                out.append("daily_max");
            }
        }
        return out;
    }
}
"}

{"file_path": "/workspace/tests/test_rules.jac", "content": """"Behavior tests for CampusSync models and the Ledger."""

import from server.models { Employee, Employment, Shift, BusyBlock, employee_of, held_shifts }
import from server.rules { Ledger, Held, CONFLICT, HOUR_LIMIT, NOT_ON_TEAM, NOT_QUALIFIED }

glob WK: str = "2026-11-02";

"""Create an international student on d1 with one d2 shift (Mon 09:00-12:00) and a busy block (Mon 13:00-14:00)."""
def setup(allot: int) -> str {
    e = Employee(name="Ana Lopez", status="international", weekly_limit=20);
    root ++> e;
    sid: str = jid(e);
    e ++> Employment(student=sid, employer="d1", hours=allot, state="active", positions=["cashier"]);
    e ++> Employment(student=sid, employer="d3", hours=5, state="invited");
    e ++> Shift(employer="d2", week=WK, day=0, start=540, end=720, student=sid);
    e ++> Shift(employer="d2", week=WK, day=3, start=540, end=720, student=sid, status="draft");
    e ++> BusyBlock(day=0, start=780, end=840);
    return sid;
}

test "employee caps and lookups" {
    e = Employee(name="Ana Lopez", status="international", weekly_limit=30);
    root ++> e;
    assert e.first_name() == "Ana";
    assert e.is_international();
    assert e.cap() == 20;
    assert e.daily_max() == 8;
    w = Employee(name="Bo", kind="worker", status="international", weekly_limit=40);
    assert not w.is_international();
    assert w.cap() == 40;
    assert w.daily_max() == 12;
    found = employee_of(jid(e));
    assert found is not None;
    assert found.name == "Ana Lopez";
    assert employee_of("") is None;
}

test "held_shifts filters week and status" {
    sid = setup(10);
    e = employee_of(sid);
    assert len(held_shifts(e, WK, "published")) == 1;
    assert len(held_shifts(e, WK, "draft")) == 1;
    assert len(held_shifts(e, "2026-11-09", "published")) == 0;
}

test "check codes" {
    sid = setup(10);
    led = Ledger(week=WK);
    assert led.check(sid, "d9", 1, 900, 960).code == NOT_ON_TEAM;
    assert led.check(sid, "d3", 1, 900, 960).code == NOT_ON_TEAM;
    assert led.check(sid, "d1", 1, 540, 600, pid="manager").code == NOT_QUALIFIED;
    v = led.check(sid, "d1", 1, 540, 600, pid="cashier");
    assert v.ok;
    assert v.public_reason() == "";
    assert abs(v.hours_left - 10.0) < 1e-6;
    b = led.check(sid, "d1", 0, 800, 860);
    assert b.code == "overlap";
    assert b.public_reason() == CONFLICT;
    assert not b.cross_department;
    h = led.check(sid, "d1", 0, 600, 700);
    assert h.code == "overlap";
    assert h.public_reason() == CONFLICT;
    assert h.cross_department;
}

test "compliance rules" {
    sid = setup(20);
    led = Ledger(week=WK);
    led.add(sid, Held(shift_id="x1", department_id="d1", day=2, start=480, end=960));
    led.add(sid, Held(shift_id="x2", department_id="d1", day=3, start=480, end=960));
    wc = led.check(sid, "d1", 4, 480, 600);
    assert wc.code == "weekly_cap";
    assert wc.public_reason() == HOUR_LIMIT;
    assert wc.cross_department;
    assert abs(wc.hours_left - 1.0) < 1e-6;
    led.remove(sid, "x1");
    led.remove(sid, "x2");
    assert led.check(sid, "d1", 4, 480, 600).ok;
    led.add(sid, Held(shift_id="y1", department_id="d1", day=1, start=480, end=900));
    dm = led.check(sid, "d1", 1, 960, 1080);
    assert dm.code == "daily_max";
    assert dm.public_reason() == CONFLICT;
    led.add(sid, Held(shift_id="z1", department_id="d1", day=5, start=480, end=600));
    rs = led.check(sid, "d1", 5, 610, 700);
    assert rs.code == "rest";
    assert rs.public_reason() == CONFLICT;
    assert not rs.cross_department;
    assert led.check(sid, "d1", 5, 630, 700).ok;
}

test "clone isolation" {
    sid = setup(10);
    led = Ledger(week=WK);
    assert len(led.held(sid)) == 1;
    c = led.clone();
    c.add(sid, Held(shift_id="n1", department_id="d1", day=4, start=480, end=600));
    assert len(c.held(sid)) == 2;
    assert len(led.held(sid)) == 1;
    c.remove(sid, led.held(sid)[0].shift_id);
    assert len(c.held(sid)) == 1;
    assert len(led.held(sid)) == 1;
    assert abs(led.total_hours(sid) - 3.0) < 1e-6;
    assert abs(c.total_hours(sid) - 2.0) < 1e-6;
}

test "violations order" {
    sid = setup(10);
    led = Ledger(week=WK);
    assert led.violations(sid) == ["dept_hours"];
    led.add(sid, Held(shift_id="a", department_id="d1", day=0, start=800, end=900));
    led.add(sid, Held(shift_id="b", department_id="d1", day=0, start=910, end=1000));
    led.add(sid, Held(shift_id="c", department_id="d1", day=2, start=0, end=1200));
    assert led.violations(sid) == ["overlap", "rest", "weekly_cap", "dept_hours", "dept_hours", "daily_max"];
}
"}

