        weaknesses=["The LLM rubric evaluation was unavailable, so deterministic crawler signals were used."],
        retention_risks=["Retention risks are estimated from deterministic signals only and may miss loop-level issues."],
        highest_leverage_improvements=["Address the deterministic findings first, then rerun the rubric evaluation for deeper loop analysis."],
        dark_pattern_risk_score=0,
        dark_pattern_risk_reasons=[],
        findings=findings
    );
}

def llm_json_payload(text: str) -> str {
    fence: str = chr(96) * 3;
    cleaned: str = text.strip();
    if cleaned.startswith(fence + "json") {
        cleaned = cleaned[7:];
    } elif cleaned.startswith(fence) {
        cleaned = cleaned[3:];
    }
    if cleaned.endswith(fence) {
        cleaned = cleaned[:-3];
    }
    cleaned = cleaned.strip();
    start: int = cleaned.find("{");
    end: int = cleaned.rfind("}");
    if start >= 0 and end >= start {
        return cleaned[start:end + 1];
    }
    return cleaned;
}

def json_str(data: any, key: str, fallback_value: str) -> str {
    try {
        value: str = str(data[key]);
        if value == "None" {
            return fallback_value;
        }
        return value;
    } except Exception {
        return fallback_value;
    }
}

def json_int(data: any, key: str, fallback_value: int) -> int {
    try {
        return int(data[key]);
    } except Exception {
        return fallback_value;
    }
}

def json_float(data: any, key: str, fallback_value: float) -> float {
    try {
        return float(data[key]);
    } except Exception {
        return fallback_value;
    }
}

def json_bool(data: any, key: str, fallback_value: bool) -> bool {
    try {
        return bool(data[key]);
    } except Exception {
        return fallback_value;
    }
}

def json_string_list(data: any, key: str) -> list[str] {
    items: list[str] = [];
    try {
        for item in data[key] {
            items.append(str(item));
        }
    } except Exception {
        return items;
    }
    return items;
}

def bounded_confidence(value: float) -> float {
    return max(0.0, min(1.0, value));
}

def parse_llm_findings(data: any) -> list[LlmFindingDraft] {
    findings: list[LlmFindingDraft] = [];
    try {
        for item in data["findings"] {
            findings.append(
                LlmFindingDraft(
                    category=json_str(item, "category", "retention loop"),
                    lane_retention_or_conversion="retention",
                    severity=json_str(item, "severity", "medium"),
                    confidence=bounded_confidence(json_float(item, "confidence", 0.7)),
                    page_url=json_str(item, "page_url", ""),
                    issue_location=json_str(item, "issue_location", ""),
                    evidence_ref=json_str(item, "evidence_ref", ""),
                    evidence=json_str(item, "evidence", ""),
                    proof=json_str(item, "proof", ""),
                    why_it_matters=json_str(item, "why_it_matters", ""),
                    research_basis=json_str(item, "research_basis", ""),
                    recommendation=json_str(item, "recommendation", ""),
                    fix_guidance=json_str(item, "fix_guidance", ""),
                    exact_ui_or_copy_tip=json_str(item, "exact_ui_or_copy_tip", ""),
                    primary_metric=json_str(item, "primary_metric", "repeat sessions"),
                    guardrail_metric=json_str(item, "guardrail_metric", "complaints and opt-outs"),
                    estimated_effort=json_str(item, "estimated_effort", "medium"),
                    expected_impact=json_str(item, "expected_impact", "medium"),
                    legal_safe=json_bool(item, "legal_safe", True)
                )
            );
        }
    } except Exception {
        return findings;
    }
    return findings;
}

def parse_llm_bundle(result: str, signals: list[DeterministicSignal], score: int) -> LlmAuditBundle {
    data = json.loads(llm_json_payload(result));
    findings = parse_llm_findings(data);
    if len(findings) == 0 {
        return fallback_bundle("retention", signals, score);
    }
    return LlmAuditBundle(
        score=bounded_score(json_int(data, "score", score)),
        onboarding_activation=bounded_ten(json_int(data, "onboarding_activation", 5)),
        habit_loop_strength=bounded_ten(json_int(data, "habit_loop_strength", 5)),
        reward_design_feedback=bounded_ten(json_int(data, "reward_design_feedback", 5)),
        social_retention_mechanics=bounded_ten(json_int(data, "social_retention_mechanics", 5)),
        attention_capture_session_depth=bounded_ten(json_int(data, "attention_capture_session_depth", 5)),
        personalization_adaptation=bounded_ten(json_int(data, "personalization_adaptation", 5)),
        friction_reduction=bounded_ten(json_int(data, "friction_reduction", 5)),
        progression_investment=bounded_ten(json_int(data, "progression_investment", 5)),
        reentry_notification_systems=bounded_ten(json_int(data, "reentry_notification_systems", 5)),
        trust_emotional_safety=bounded_ten(json_int(data, "trust_emotional_safety", 5)),
        strengths=json_string_list(data, "strengths"),
        weaknesses=json_string_list(data, "weaknesses"),
        retention_risks=json_string_list(data, "retention_risks"),
        highest_leverage_improvements=json_string_list(data, "highest_leverage_improvements"),
        dark_pattern_risk_score=bounded_ten(json_int(data, "dark_pattern_risk_score", 0)),
        dark_pattern_risk_reasons=json_string_list(data, "dark_pattern_risk_reasons"),
        findings=findings
    );
}

def safe_retention_bundle(target_url: str, evidence_pack: str, signals: list[DeterministicSignal], score: int) -> LlmAuditBundle {
    print("[LLM RUBRIC] Evaluating retention rubric for " + target_url);
    print("[LLM RUBRIC] Deterministic signals: " + str(len(signals)));
    try {
        result = evaluate_retention_recommendations(target_url, evidence_pack, signals);
        print("[LLM RUBRIC] Parsing rubric response");
        return parse_llm_bundle(result, signals, score);
    } except Exception as e {
        print("[LLM RUBRIC] Evaluation failed, using deterministic fallback: " + str(e));
        traceback.print_exc();
        return fallback_bundle("retention", signals, score);
    }
}
"}

{"file_path": "/workspace/tests/test_audits.jac", "content": """"Behavior tests for the Flair retention scoring core. The model is always MockLLM."""

import services.llm as m;
import from jaclang.byllm.lib { MockLLM }
import from services.models { DeterministicSignal, LlmFindingDraft, LlmAuditBundle }
import from services.audits {
    safe_retention_bundle,
    parse_llm_bundle,
    fallback_bundle,
    draft_from_signal,
    llm_json_payload,
    rubric_overall,
    blended_score,
    bounded_score,
    bounded_ten
}

def retention_signals() -> list[DeterministicSignal] {
    return [
        DeterministicSignal(lane_retention_or_conversion="retention", category="streak loop", severity="high", confidence=0.9, page_url="https://app.example/home", primary_metric="repeat sessions"),
        DeterministicSignal(lane_retention_or_conversion="conversion", category="pricing clarity"),
        DeterministicSignal(lane_retention_or_conversion="retention", category="empty state", estimated_effort="low")
    ];
}

test "bounded helpers clamp" {
    assert bounded_score(-5) == 0;
    assert bounded_score(150) == 100;
    assert bounded_score(42) == 42;
    assert bounded_ten(-1) == 0;
    assert bounded_ten(11) == 10;
    assert bounded_ten(6) == 6;
}

test "blended score averages clamped scores" {
    assert blended_score(80, 60) == 70;
    assert blended_score(200, 0) == 50;
    assert blended_score(-10, 41) == 20;
}

test "rubric overall uses weights" {
    assert rubric_overall(LlmAuditBundle()) == 50;
    full = LlmAuditBundle(onboarding_activation=10, habit_loop_strength=10, reward_design_feedback=10, social_retention_mechanics=10, attention_capture_session_depth=10, personalization_adaptation=10, friction_reduction=10, progression_investment=10, reentry_notification_systems=10, trust_emotional_safety=10);
    assert rubric_overall(full) == 100;
    over = LlmAuditBundle(onboarding_activation=50, habit_loop_strength=50, reward_design_feedback=50, social_retention_mechanics=50, attention_capture_session_depth=50, personalization_adaptation=50, friction_reduction=50, progression_investment=50, reentry_notification_systems=50, trust_emotional_safety=50);
    assert rubric_overall(over) == 100;
    assert rubric_overall(LlmAuditBundle(onboarding_activation=0, habit_loop_strength=0, reward_design_feedback=0, social_retention_mechanics=0, attention_capture_session_depth=0, personalization_adaptation=0, friction_reduction=0, progression_investment=0, reentry_notification_systems=0, trust_emotional_safety=0)) == 0;
}

test "json payload strips fences and prose" {
    fence = chr(96) * 3;
    assert llm_json_payload(fence + "json\n{\"a\": 1}\n" + fence) == "{\"a\": 1}";
    assert llm_json_payload(fence + "\n{\"a\": 2}\n" + fence) == "{\"a\": 2}";
    assert llm_json_payload("Here is the verdict: {\"a\": {\"b\": 3}} thanks") == "{\"a\": {\"b\": 3}}";
    assert llm_json_payload("  no json here  ") == "no json here";
}

test "draft from signal copies fields" {
    d = draft_from_signal(retention_signals()[0]);
    assert d.category == "streak loop";
    assert d.severity == "high";
    assert d.confidence == 0.9;
    assert d.page_url == "https://app.example/home";
    assert d.lane_retention_or_conversion == "retention";
    assert d.legal_safe == True;
}

test "safe bundle parses fenced model output with clamping" {
    fence = chr(96) * 3;
    payload = fence + "json\n{\"score\": 140, \"onboarding_activation\": 12, \"habit_loop_strength\": -3, \"reward_design_feedback\": 8, \"strengths\": [\"clear CTA\"], \"dark_pattern_risk_score\": 15, \"findings\": [{\"category\": \"habit\", \"lane_retention_or_conversion\": \"conversion\", \"confidence\": 1.7, \"issue_location\": \"Home hero\"}, {\"confidence\": -0.4, \"legal_safe\": false}]}\n" + fence;
    m.llm = MockLLM(model_name="mockllm", config={"outputs": [payload]});
    b = safe_retention_bundle("https://app.example", "evidence", retention_signals(), 55);
    assert b.score == 100;
    assert b.onboarding_activation == 10;
    assert b.habit_loop_strength == 0;
    assert b.reward_design_feedback == 8;
    assert b.trust_emotional_safety == 5;
    assert b.dark_pattern_risk_score == 10;
    assert b.strengths == ["clear CTA"];
    assert b.weaknesses == [];
    assert len(b.findings) == 2;
    f0 = b.findings[0];
    assert f0.lane_retention_or_conversion == "retention";
    assert f0.category == "habit";
    assert f0.confidence == 1.0;
    assert f0.issue_location == "Home hero";
    f1 = b.findings[1];
    assert f1.lane_retention_or_conversion == "retention";
    assert f1.category == "retention loop";
    assert f1.severity == "medium";
    assert f1.confidence == 0.0;
    assert f1.primary_metric == "repeat sessions";
    assert f1.guardrail_metric == "complaints and opt-outs";
    assert f1.estimated_effort == "medium";
    assert f1.expected_impact == "medium";
    assert f1.legal_safe == False;
    assert f1.page_url == "";
}

test "safe bundle parses prose-wrapped output" {
    m.llm = MockLLM(model_name="mockllm", config={"outputs": ["Sure! {\"score\": 64, \"findings\": [{\"category\": \"reentry\"}]} Hope this helps."]});
    b = safe_retention_bundle("https://app.example", "evidence", [], 30);
    assert b.score == 64;
    assert b.findings[0].category == "reentry";
    assert b.onboarding_activation == 5;
}

test "empty findings fall back to retention signals" {
    m.llm = MockLLM(model_name="mockllm", config={"outputs": ["{\"score\": 90, \"findings\": []}"]});
    b = safe_retention_bundle("https://app.example", "evidence", retention_signals(), 80);
    assert b.score == 80;
    assert len(b.findings) == 2;
    assert b.findings[0].category == "streak loop";
    assert b.findings[1].category == "empty state";
    assert b.onboarding_activation == 7;
    assert b.trust_emotional_safety == 7;
    assert b.strengths == [];
    assert len(b.weaknesses) == 1;
    assert "unavailable" in b.weaknesses[0];
    assert b.dark_pattern_risk_score == 0;
}

test "unparsable output falls back" {
    m.llm = MockLLM(model_name="mockllm", config={"outputs": ["not json at all"]});
    b = safe_retention_bundle("https://app.example", "evidence", retention_signals(), 20);
    assert b.score == 20;
    assert b.habit_loop_strength == 3;
    assert len(b.findings) == 2;
}

test "fallback baseline finding when no lane signals" {
    b = fallback_bundle("retention", [DeterministicSignal(lane_retention_or_conversion="conversion")], 50);
    assert b.score == 50;
    assert b.friction_reduction == 5;
    assert len(b.findings) == 1;
    f = b.findings[0];
    assert f.category == "baseline opportunity";
    assert f.lane_retention_or_conversion == "retention";
    assert f.confidence == 0.55;
    assert f.estimated_effort == "low";
    assert f.primary_metric == "retention score";
    assert f.guardrail_metric == "support tickets and complaint rate";
    assert f.legal_safe == True;
    assert fallback_bundle("retention", [], 40).onboarding_activation == 5;
    assert fallback_bundle("retention", [], 75).onboarding_activation == 5;
    assert fallback_bundle("retention", [], 39).onboarding_activation == 3;
    assert fallback_bundle("retention", [], 76).onboarding_activation == 7;
}

test "parse llm bundle propagates json errors" {
    raised = False;
    try {
        parse_llm_bundle("garbage", [], 50);
    } except Exception {
        raised = True;
    }
    assert raised;
}
"}

