    assert llm_json_payload("  no json here  ") == "no json here";
}

test "draft from signal copies fields" {
    d = draft_from_signal(retention_signals()[0]);
    assert d.category == "streak loop";
    assert d.severity == "high";
    assert d.confidence == 0.9;
    assert d.page_url == "https://app.example/home";
    assert d.lane_retention_or_conversion == "retention";
    assert d.legal_safe;
}

test "safe bundle parses fenced model output with clamping" {
    fence = chr(96) * 3;
    payload = fence + "json\n{\"score\": 140, \"onboarding_activation\": 12, \"habit_loop_strength\": -3, \"reward_design_feedback\": 8, \"strengths\": [\"clear CTA\"], \"dark_pattern_risk_score\": 15, \"findings\": [{\"category\": \"habit\", \"lane_retention_or_conversion\": \"conversion\", \"confidence\": 1.7, \"issue_location\": \"Home hero\"}, {\"confidence\": -0.4, \"legal_safe\": false}]}\n" + fence;
    use_mock([payload]);
    b = safe_retention_bundle("https://app.example", "evidence", retention_signals(), 55);
    assert b.score == 100;
    assert b.onboarding_activation == 10;
    assert b.habit_loop_strength == 0;
    assert b.reward_design_feedback == 8;
    assert b.trust_emotional_safety == 5;
    assert b.dark_pattern_risk_score == 10;
    assert b.strengths == ["clear CTA"];
    assert b.weaknesses == [];
    assert len(b.findings) == 2;
    f0 = b.findings[0];
    assert f0.lane_retention_or_conversion == "retention";
    assert f0.category == "habit";
    assert f0.confidence == 1.0;
    assert f0.issue_location == "Home hero";
    f1 = b.findings[1];
    assert f1.lane_retention_or_conversion == "retention";
    assert f1.category == "retention loop";
    assert f1.severity == "medium";
    assert f1.confidence == 0.0;
    assert f1.primary_metric == "repeat sessions";
    assert f1.guardrail_metric == "complaints and opt-outs";
    assert f1.estimated_effort == "medium";
    assert f1.expected_impact == "medium";
    assert not f1.legal_safe;
    assert f1.page_url == "";
}

test "safe bundle parses prose-wrapped output" {
    use_mock(["Sure! {\"score\": 64, \"findings\": [{\"category\": \"reentry\"}]} Hope this helps."]);
    b = safe_retention_bundle("https://app.example", "evidence", [], 30);
    assert b.score == 64;
    assert b.findings[0].category == "reentry";
    assert b.onboarding_activation == 5;
}

test "empty findings fall back to retention signals" {
    use_mock(["{\"score\": 90, \"findings\": []}"]);
    b = safe_retention_bundle("https://app.example", "evidence", retention_signals(), 80);
    assert b.score == 80;
    assert len(b.findings) == 2;
    assert b.findings[0].category == "streak loop";
    assert b.findings[1].category == "empty state";
    assert b.onboarding_activation == 7;
    assert b.trust_emotional_safety == 7;
    assert b.strengths == [];
    assert len(b.weaknesses) == 1;
    assert "unavailable" in b.weaknesses[0];
    assert b.dark_pattern_risk_score == 0;
}

test "unparsable output falls back" {
    use_mock(["not json at all"]);
    b = safe_retention_bundle("https://app.example", "evidence", retention_signals(), 20);
    assert b.score == 20;
    assert b.habit_loop_strength == 3;
    assert len(b.findings) == 2;
}

test "fallback baseline finding when no lane signals" {
    b = fallback_bundle("retention", [DeterministicSignal(lane_retention_or_conversion="conversion")], 50);
    assert b.score == 50;
    assert b.friction_reduction == 5;
    assert len(b.findings) == 1;
    f = b.findings[0];
    assert f.category == "baseline opportunity";
    assert f.lane_retention_or_conversion == "retention";
    assert f.confidence == 0.55;
    assert f.estimated_effort == "low";
    assert f.primary_metric == "retention score";
    assert f.guardrail_metric == "support tickets and complaint rate";
    assert f.legal_safe;
    assert fallback_bundle("retention", [], 40).onboarding_activation == 5;
    assert fallback_bundle("retention", [], 75).onboarding_activation == 5;
    assert fallback_bundle("retention", [], 39).onboarding_activation == 3;
    assert fallback_bundle("retention", [], 76).onboarding_activation == 7;
}

test "parse llm bundle propagates json errors" {
    raised = False;
    try {
        parse_llm_bundle("garbage", [], 50);
    } except Exception {
        raised = True;
    }
    assert raised;
}
"}

