"""Build the fenced-block regex for a bracket pair without backslash or backtick literals in source."""
def _fence_pattern(opener: str, closer: str) -> str {
    bs = chr(92);
    fence = chr(96) * 3;
    return fence + "(?:json)?" + bs + "s*(" + bs + opener + ".*?" + bs + closer + ")" + bs + "s*" + fence;
}

"""Return the substring from the first opener to its matching closer, or empty if absent or unbalanced."""
def _balanced_span(s: str, opener: str, closer: str) -> str {
    start = s.find(opener);
    if start < 0 {
        return "";
    }
    depth = 0;
    for i in range(start, len(s)) {
        ch = s[i];
        if ch == opener {
            depth += 1;
        } elif ch == closer {
            depth -= 1;
            if depth == 0 {
                return s[start:i + 1];
            }
        }
    }
    return "";
}

"""Locate the JSON text for the given bracket pair: fenced block first, then balanced span."""
def _json_candidate(s: str, opener: str, closer: str) -> str {
    if not s {
        return "";
    }
    text = s.strip();
    m = re.search(_fence_pattern(opener, closer), text, re.DOTALL);
    if m {
        return str(m.group(1));
    }
    return _balanced_span(text, opener, closer);
}

"""Parse the first JSON object in s, tolerating fences and prose."""
def _parse_json_obj(s: str) -> dict[str, any] {
    cand = _json_candidate(s, "{", "}");
    if not cand {
        return {};
    }
    try {
        val = json.loads(cand);
    } except Exception {
        return {};
    }
    if isinstance(val, dict) {
        return val;
    }
    return {};
}

"""Parse the first JSON array in s, tolerating fences and prose."""
def _parse_json_list(s: str) -> list[any] {
    cand = _json_candidate(s, "[", "]");
    if not cand {
        return [];
    }
    try {
        val = json.loads(cand);
    } except Exception {
        return [];
    }
    if isinstance(val, list) {
        return val;
    }
    return [];
}

"""Classify the insurance denial. Answer with exactly one label: NOT_MEDICALLY_NECESSARY, OUT_OF_NETWORK, PRIOR_AUTH_MISSING, EXPERIMENTAL_OR_INVESTIGATIONAL, CODING_ERROR, BENEFIT_EXCLUSION or OTHER."""
def extract_denial_reason_raw(denial_text: str) -> str by llm();

"""Classify the denial text into a DenialReason, falling back to OTHER."""
def extract_denial_reason(denial_text: str) -> DenialReason {
    raw = str(extract_denial_reason_raw(denial_text)).strip().upper();
    if "NOT_MEDICALLY_NECESSARY" in raw {
        return DenialReason.NOT_MEDICALLY_NECESSARY;
    }
    if "OUT_OF_NETWORK" in raw {
        return DenialReason.OUT_OF_NETWORK;
    }
    if "PRIOR_AUTH" in raw {
        return DenialReason.PRIOR_AUTH_MISSING;
    }
    if "EXPERIMENTAL" in raw or "INVESTIGATIONAL" in raw {
        return DenialReason.EXPERIMENTAL_OR_INVESTIGATIONAL;
    }
    if "CODING" in raw {
        return DenialReason.CODING_ERROR;
    }
    if "BENEFIT_EXCLUSION" in raw or "EXCLUSION" in raw {
        return DenialReason.BENEFIT_EXCLUSION;
    }
    return DenialReason.OTHER;
}

"""From the policy text, extract the clauses relevant to this denial reason. Answer with a JSON array of objects with keys section, title, text, relevance_note."""
def extract_relevant_clauses_raw(policy_text: str, denial_reason: DenialReason) -> str by llm();

"""Extract the policy clauses relevant to the denial reason."""
def extract_relevant_clauses(policy_text: str, denial_reason: DenialReason) -> list[PolicyClause] {
    items = _parse_json_list(str(extract_relevant_clauses_raw(policy_text, denial_reason)));
    out: list[PolicyClause] = [];
    for d in items {
        if not isinstance(d, dict) {
            continue;
        }
        out.append(
            PolicyClause(
                section=str(d.get("section", "")),
                title=str(d.get("title", "")),
                text=str(d.get("text", "")),
                relevance_note=str(d.get("relevance_note", ""))
            )
        );
    }
    return out;
}

"""Find contradictions between the denial, the clinical record and the policy clauses. Answer with a JSON array of objects with keys denial_quote, policy_quote, clause_section, explanation."""
def find_contradictions_raw(denial_text: str, clinical_record: str, clauses: list[PolicyClause]) -> str by llm();

"""Find contradictions between the denial and the policy clauses."""
def find_contradictions(denial_text: str, clinical_record: str, clauses: list[PolicyClause]) -> list[Contradiction] {
    items = _parse_json_list(str(find_contradictions_raw(denial_text, clinical_record, clauses)));
    out: list[Contradiction] = [];
    for d in items {
        if not isinstance(d, dict) {
            continue;
        }
        out.append(
            Contradiction(
                denial_quote=str(d.get("denial_quote", "")),
                policy_quote=str(d.get("policy_quote", "")),
                clause_section=str(d.get("clause_section", "")),
                explanation=str(d.get("explanation", ""))
            )
        );
    }
    return out;
}

"""Assess how strong an appeal is given these contradictions. Answer with exactly one of WEAK, MODERATE, STRONG, VERY_STRONG."""
def assess_appeal_strength_raw(contradictions: list[Contradiction]) -> str by llm();

"""Assess appeal strength, falling back to MODERATE."""
def assess_appeal_strength(contradictions: list[Contradiction]) -> AppealStrength {
    raw = str(assess_appeal_strength_raw(contradictions)).strip().upper();
    if "VERY_STRONG" in raw or "VERY STRONG" in raw {
        return AppealStrength.VERY_STRONG;
    }
    if "STRONG" in raw {
        return AppealStrength.STRONG;
    }
    if "WEAK" in raw {
        return AppealStrength.WEAK;
    }
    return AppealStrength.MODERATE;
}

"""Draft a formal health-insurance appeal letter. Answer with a JSON object with keys subject, salutation, body, citations (array of strings), closing."""
def draft_appeal_letter_raw(
    patient_name: str,
    member_id: str,
    claim_number: str,
    date_of_service: str,
    cpt_code: str,
    billed_amount: float,
    plan_name: str,
    denial_reason: DenialReason,
    contradictions: list[Contradiction],
    clinical_record: str
) -> str by llm();

"""Draft the appeal letter and parse it into an AppealLetter."""
def draft_appeal_letter(
    patient_name: str,
    member_id: str,
    claim_number: str,
    date_of_service: str,
    cpt_code: str,
    billed_amount: float,
    plan_name: str,
    denial_reason: DenialReason,
    contradictions: list[Contradiction],
    clinical_record: str
) -> AppealLetter {
    raw = draft_appeal_letter_raw(
        patient_name,
        member_id,
        claim_number,
        date_of_service,
        cpt_code,
        billed_amount,
        plan_name,
        denial_reason,
        contradictions,
        clinical_record
    );
    d = _parse_json_obj(str(raw));
    cites = d.get("citations") or [];
    if not isinstance(cites, list) {
        cites = [str(cites)];
    }
    return AppealLetter(
        subject=str(d.get("subject", "")),
        salutation=str(d.get("salutation", "")),
        body=str(d.get("body", "")),
        citations=[str(c) for c in cites],
        closing=str(d.get("closing", ""))
    );
}
"}

{"file_path": "/workspace/walkers.jac", "content": """"Public walkers for the appeal agent: submit a claim and list stored appeals."""

import json;
import uuid;
import datetime;
import from models {
    Claim,
    Policy,
    Appeal,
    DenialReason,
    AppealStrength,
    Contradiction
}
import from tools {
    extract_denial_reason,
    extract_relevant_clauses,
    find_contradictions,
    assess_appeal_strength,
    draft_appeal_letter
}

"""Store a denied claim and its policy, run the five tools, store an Appeal and report the letter."""
walker:pub submit_claim {
    has patient_name: str;
    has member_id: str;
    has claim_number: str;
    has date_of_service: str;
    has cpt_code: str;
    has billed_amount: float;
    has plan_name: str;
    has denial_text: str;
    has policy_text: str;
    has clinical_record: str = "";

    can run with Root entry {
        claim = Claim(
            claim_id=self.claim_number,
            patient_name=self.patient_name,
            member_id=self.member_id,
            cpt_code=self.cpt_code,
            date_of_service=self.date_of_service,
            billed_amount=self.billed_amount,
            denial_text=self.denial_text,
            clinical_record=self.clinical_record
        );
        policy = Policy(
            policy_id=f"POL-{self.member_id}",
            plan_name=self.plan_name,
            full_text=self.policy_text
        );
        here ++> claim;
        here ++> policy;

        reason: DenialReason = extract_denial_reason(self.denial_text);
        clauses = extract_relevant_clauses(self.policy_text, reason);
        contradictions: list[Contradiction] = find_contradictions(
            self.denial_text, self.clinical_record, clauses
        );
        strength: AppealStrength = assess_appeal_strength(contradictions);
        letter = draft_appeal_letter(
            self.patient_name,
            self.member_id,
            self.claim_number,
            self.date_of_service,
            self.cpt_code,
            self.billed_amount,
            self.plan_name,
            reason,
            contradictions,
            self.clinical_record
        );

        contra_rows = [
            {
                "denial_quote": c.denial_quote,
                "policy_quote": c.policy_quote,
                "clause_section": c.clause_section,
                "explanation": c.explanation
            }
            for c in contradictions
        ];
        letter_text = letter.salutation + "\n\n" + letter.body + "\n\n" + letter.closing;
        appeal = Appeal(
            appeal_id="APL-" + uuid.uuid4().hex[:8],
            claim_id=claim.claim_id,
            policy_id=policy.policy_id,
            denial_reason=reason,
            strength=strength,
            contradictions_json=json.dumps(contra_rows),
            letter_subject=letter.subject,
            letter_body=letter_text,
            citations_json=json.dumps(letter.citations),
            created_at=datetime.datetime.utcnow().isoformat()
        );
        here ++> appeal;

        report {
            "appeal_id": appeal.appeal_id,
            "claim_id": appeal.claim_id,
            "subject": letter.subject,
            "letter": appeal.letter_body,
            "citations": letter.citations
        };
    }
}

"""Report one summary row per stored appeal."""
walker:pub list_appeals {
    can run with Root entry {
        rows: list[dict[str, str]] = [];
        for a in [-->[?:Appeal]] {
            rows.append(
                {
                    "appeal_id": a.appeal_id,
                    "claim_id": a.claim_id,
                    "subject": a.letter_subject,
                    "created_at": a.created_at
                }
            );
        }
        report rows;
    }
}
"}

messages.content:
Tests are first-class language blocks written alongside the code they test - `jac run` ignores them; `jac test` runs them. All checks are plain `assert` statements, with an optional message: `assert user.is_valid(), f"bad user: {user.name}";`.

```jac
obj User {
    has name: str, email: str;

    def is_valid() -> bool { return "@" in self.email; }
}

test "user is valid" {
    user = User(name="Alice", email="alice@example.com");
    assert user.is_valid();
}
```

## Running tests

```
jac test main.jac                 # all tests in a file
jac test                          # all tests in current directory
jac test -d tests/                # all tests in a directory
jac test main.jac -t "my test"    # one test by name (quote multi-word names)
jac test -d tests/ -f "user*"     # filter test FILES by Unix pattern
jac test main.jac -x              # stop on first failure
jac test main.jac -m 3            # stop after 3 failures
jac test main.jac -v              # verbose (one line per test)
```

A `test "some name"` block becomes unittest case `test_some_name` (spaces -> underscores). Defaults live in the `[test]` section of jac.toml (`directory`, `filter`, `verbose`, `fail_fast`, `max_failures`).

## File naming - two traps

- **Never name files `test_*.jac`** (e.g. `test_utils.jac`) - the `test_` prefix collides with Python's test-module import machinery. Use `utils_tests.jac`, or the annex form below.
- **Calling a `def:priv` endpoint from a `.test.jac` annex draws `W2037`** ("private to module") - the annex counts as a separate module for access modifiers even though it sees the declarations. Warning-only; tests still run. For a clean `jac check`, put those tests in the main file or use in-file `test` blocks.
- **`<mod>.test.jac` is an ANNEX, not a standalone file.** Like `.impl.jac`, it attaches to a same-basename module: `people.test.jac` pairs with `people.jac`, and you run `jac test people.jac`. A `.test.jac` with no base module fails with `No module named '<mod>'`. The annex sees the module's declarations without imports - ideal for keeping tests out of the main file.

## Graph state: parallel workers + a persisted root

Verified behavior: `jac test` runs test blocks **in parallel across isolated workers**, so tests in one file do NOT share in-memory graph state and do NOT run in declaration order (no CLI flag forces serial; set `JAC_TEST_JOBS=0` in the environment or `test_jobs = "0"` under `[dev]` in `jac.toml` when you need it). Anything hung off `root` still **persists to `.jac/data` between runs**. Two consequences:

- Never rely on one test seeing nodes another test created in the same run - each test builds and asserts on its own data.
- A green suite can go red on re-run because last run's persisted nodes are still there - or crash with `NodeAnchor <id> is not a valid reference` when stale persisted anchors meet recompiled code.

Fix the persistence half with `jac clean --all --force` (or `jac clean --data`) before the run. Write graph assertions defensively - count nodes you just created (or filter by a unique field) rather than asserting totals on `root`.

## Testing walkers: spawn + `.reports`

```jac
node Person { has name: str; has age: int; }

walker FindAdults {
    can check with Root entry {
        for p in [-->][?:Person] {
            if p.age >= 18 { report p; }
        }
    }
}

test "finds adults only" {
    root ++> Person(name="Alice", age=30);
    root ++> Person(name="Bob", age=15);
    result = root spawn FindAdults();
    assert len(result.reports) == 1;
    assert result.reports[0].name == "Alice";
}
```

The spawn expression returns the walker instance; every `report` it made is in `result.reports` (a list, in report order). Assert graph shape directly too: `assert len([root-->]) == 2;`, `assert alice in [root ->:Friend:->];`.

## Expecting an exception

No `pytest.raises` - use try/except with a guard assert:

```jac
test "divide by zero raises" {
    try {
        divide(10, 0);
        assert False, "should have raised";
    } except ZeroDivisionError {
        assert True;
    }
}
```

## Parameterized tests

`parametrize()` registers one test per input, in a `with entry` block:

```jac
import from jaclang.runtimelib.test { parametrize }

def _test_square(pair: tuple) {
    assert pair[0] ** 2 == pair[1];
}

with entry {
    parametrize("square", [(2, 4), (3, 9), (0, 0)], _test_square);
}
```

Each case runs and reports independently (`square_0`, `square_1`, ...); pass `id_fn=` to name cases from their parameter.

## In-process endpoint tests: JacTestClient

For testing served endpoints (`walker:pub` / `def:pub`) without starting a real server, use the Python-side client from pytest:

```python
from jaclang.runtimelib.testing import JacTestClient

def test_task_crud(tmp_path):
    client = JacTestClient.from_file("app.jac", base_path=str(tmp_path))
    client.register_user("testuser", "password123")            # auth in one line
    resp = client.post("/walker/CreateTask", json={"title": "My Task"})
    assert resp.ok and resp.status_code == 200
    assert len(client.post("/walker/GetTasks").json()["reports"]) == 1
    client.close()
```

`base_path=tmp_path` keeps each test's persisted graph isolated. Also available: `get/put/request`, `login`, `set_auth_token`, `resp.data` (unwrapped envelope), `client.reload()` (HMR).

## Pitfalls

- **`-f` filters test FILES (Unix glob on filenames), `-t` selects one test by name.** They are not interchangeable. `-t` without a filepath/directory is an error.
- **LLM-powered functions**: don't hit a real model in tests - use `MockLLM` with canned outputs (see `jac-by-llm`).

## See also

- `jac-debugging` - the check/fix loop, stale-cache triage (`jac clean` vs `jac purge`)
- `jac-config` - `[test]` defaults, `[scripts]` (`test = "jac test -v"`)
- `jac-walker-patterns` - report/reports semantics being asserted here

Deep dive bundled with the CLI: `jac guide reference/testing` (full test-runner reference).

