}

import tools as t;
import from models { DenialReason, AppealStrength }
import from jaclang.byllm.lib { MockLLM }

def mock(outputs: list[str]) {
    t.llm = MockLLM(model_name="mockllm", config={"outputs": outputs});
}

test "denial reason maps free text case-insensitively" {
    mock([
        "The reason is not_medically_necessary.",
        "out_of_network",
        "Prior_Auth was missing",
        "This is INVESTIGATIONAL therapy",
        "coding issue",
        "benefit exclusion applies",
        "no idea"
    ]);
    assert t.extract_denial_reason("a") == DenialReason.NOT_MEDICALLY_NECESSARY;
    assert t.extract_denial_reason("b") == DenialReason.OUT_OF_NETWORK;
    assert t.extract_denial_reason("c") == DenialReason.PRIOR_AUTH_MISSING;
    assert t.extract_denial_reason("d") == DenialReason.EXPERIMENTAL_OR_INVESTIGATIONAL;
    assert t.extract_denial_reason("e") == DenialReason.CODING_ERROR;
    assert t.extract_denial_reason("f") == DenialReason.BENEFIT_EXCLUSION;
    assert t.extract_denial_reason("g") == DenialReason.OTHER;
}

test "appeal strength maps free text with MODERATE fallback" {
    mock(["Very strong case", "VERY_STRONG", "strong", "rather weak", "unclear"]);
    assert t.assess_appeal_strength([]) == AppealStrength.VERY_STRONG;
    assert t.assess_appeal_strength([]) == AppealStrength.VERY_STRONG;
    assert t.assess_appeal_strength([]) == AppealStrength.STRONG;
    assert t.assess_appeal_strength([]) == AppealStrength.WEAK;
    assert t.assess_appeal_strength([]) == AppealStrength.MODERATE;
}

test "clauses parse fenced array, skip non-objects, default fields" {
    fence = chr(96) * 3;
    nl = chr(10);
    answer = "Here you go:" + nl + fence + "json" + nl + "[{\"section\": \"4.2\", \"title\": \"Necessity\"}, 7, \"x\"]" + nl + fence + nl + "Done.";
    mock([answer, "no array here"]);
    clauses = t.extract_relevant_clauses("policy", DenialReason.OTHER);
    assert len(clauses) == 1;
    assert clauses[0].section == "4.2";
    assert clauses[0].title == "Necessity";
    assert clauses[0].text == "";
    assert clauses[0].relevance_note == "";
    assert t.extract_relevant_clauses("policy", DenialReason.OTHER) == [];
}

test "contradictions parse array embedded in prose" {
    answer = "Found these: [{\"denial_quote\": \"not needed\", \"explanation\": \"record shows need\"}, null] end";
    mock([answer, ""]);
    cs = t.find_contradictions("denial", "record", []);
    assert len(cs) == 1;
    assert cs[0].denial_quote == "not needed";
    assert cs[0].policy_quote == "";
    assert cs[0].clause_section == "";
    assert cs[0].explanation == "record shows need";
    assert t.find_contradictions("denial", "record", []) == [];
}

test "appeal letter parses object in prose and wraps scalar citations" {
    answer = "Sure! {\"subject\": \"Appeal\", \"salutation\": \"Dear Reviewer,\", \"body\": \"Please {reconsider}.\", \"citations\": \"Sec 4.2\", \"closing\": \"Sincerely\"} Thanks.";
    mock([answer, "nothing useful"]);
    letter = t.draft_appeal_letter("Pat", "M1", "C1", "2024-01-01", "99213", 100.0, "Plan", DenialReason.OTHER, [], "rec");
    assert letter.subject == "Appeal";
    assert letter.salutation == "Dear Reviewer,";
    assert letter.body == "Please {reconsider}.";
    assert letter.citations == ["Sec 4.2"];
    assert letter.closing == "Sincerely";
    empty = t.draft_appeal_letter("Pat", "M1", "C1", "2024-01-01", "99213", 100.0, "Plan", DenialReason.OTHER, [], "rec");
    assert empty.subject == "";
    assert empty.body == "";
    assert empty.citations == [];
    assert empty.closing == "";
}
"}

{"file_path": "/workspace/walkers_tests.jac", "content": """"MockLLM tests for the submit_claim and list_appeals walkers."""

import os;

with entry {
    os.environ.setdefault("OPENAI_API_KEY", "test-placeholder");
}

import tools as t;
import from models { Claim, Policy, Appeal, DenialReason, AppealStrength }
import from walkers { submit_claim, list_appeals }
import from jaclang.byllm.lib { MockLLM }

def mock(outputs: list[str]) {
    mocked: any = MockLLM(model_name="mockllm", config={"outputs": outputs});
    t.llm = mocked;
}

def submit(claim_number: str, member_id: str) -> any {
    return root spawn submit_claim(
        patient_name="Pat Doe",
        member_id=member_id,
        claim_number=claim_number,
        date_of_service="2024-03-01",
        cpt_code="99213",
        billed_amount=250.0,
        plan_name="Gold Plan",
        denial_text="Denied as not medically necessary.",
        policy_text="Section 4.2 covers medically necessary visits.",
        clinical_record="Patient has documented chronic pain."
    );
}

test "submit_claim stores nodes, reports letter, and list_appeals lists it" {
    mock([
        "NOT_MEDICALLY_NECESSARY",
        "[{\"section\": \"4.2\", \"title\": \"Necessity\", \"text\": \"covers visits\"}]",
        "[{\"denial_quote\": \"not necessary\", \"policy_quote\": \"covers visits\", \"clause_section\": \"4.2\", \"explanation\": \"record shows need\"}]",
        "STRONG",
        "{\"subject\": \"Appeal of CLM-W1\", \"salutation\": \"Dear Reviewer,\", \"body\": \"Please reconsider.\", \"citations\": [\"Sec 4.2\"], \"closing\": \"Sincerely, Pat\"}"
    ]);
    res = submit("CLM-W1", "M42");
    assert len(res.reports) == 1;
    r = res.reports[0];
    nl = chr(10);
    aid = r["appeal_id"];
    assert aid.startswith("APL-") and len(aid) == 12;
    assert all([ch in "0123456789abcdef" for ch in aid[4:]]);
    assert r["claim_id"] == "CLM-W1";
    assert r["subject"] == "Appeal of CLM-W1";
    assert r["letter"] == "Dear Reviewer," + nl + nl + "Please reconsider." + nl + nl + "Sincerely, Pat";
    assert r["citations"] == ["Sec 4.2"];

    appeals = [a for a in [root-->[?:Appeal]] if a.appeal_id == aid];
    assert len(appeals) == 1;
    ap = appeals[0];
    assert ap.policy_id == "POL-M42";
    assert ap.denial_reason == DenialReason.NOT_MEDICALLY_NECESSARY;
    assert ap.strength == AppealStrength.STRONG;
    assert ap.letter_body == r["letter"];
    assert "record shows need" in ap.contradictions_json;
    assert len([c for c in [root-->[?:Claim]] if c.claim_id == "CLM-W1"]) >= 1;
    assert len([p for p in [root-->[?:Policy]] if p.policy_id == "POL-M42"]) >= 1;

    lr = root spawn list_appeals();
    assert len(lr.reports) == 1;
    rows = [row for row in lr.reports[0] if row["appeal_id"] == aid];
    assert len(rows) == 1;
    assert rows[0]["claim_id"] == "CLM-W1";
    assert rows[0]["subject"] == "Appeal of CLM-W1";
    assert rows[0]["created_at"] == ap.created_at;
}

test "submit_claim joins empty letter parts exactly" {
    mock(["unknown", "none", "none", "unsure", "I cannot draft this."]);
    res = submit("CLM-W2", "M7");
    r = res.reports[0];
    assert r["subject"] == "";
    assert r["letter"] == chr(10) * 4;
    assert r["citations"] == [];
    appeals = [a for a in [root-->[?:Appeal]] if a.appeal_id == r["appeal_id"]];
    assert len(appeals) == 1;
    assert appeals[0].denial_reason == DenialReason.OTHER;
    assert appeals[0].strength == AppealStrength.MODERATE;
    assert appeals[0].letter_body == chr(10) * 4;
}
"}

{"file_path": "/workspace/services/nourish_model.jac", "content": """"Nourish graph data model: hub anchor, domain nodes and typed edges."""

"""Central anchor of the Nourish dispatch graph."""
node HubNode {
