{"file_path": "/workspace/services/supply_agent.jac", "content": """"Supply agent: turns a business's food upload into a pending donation."""

import from datetime { datetime }
import from services.nourish_model { BusinessNode, DonationNode, Offers }

"""Spawned on a BusinessNode; rejects expired food or creates a pending DonationNode."""
walker supply_manager {
    has food_type: str;
    has quantity: int;
    has expiry_time: str;
    has created_donation: DonationNode | None = None;
    has error_message: str = "";

    can process_business with BusinessNode entry {
        business_name: str = here.name;
        now_str: str = datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%S");
        if self.expiry_time <= now_str {
            self.error_message = f"REJECTED: Food '{self.food_type}' from '{business_name}' is already expired (expiry={self.expiry_time}).";
            print("[SupplyAgent] " + self.error_message);
            report {"status": "error", "message": self.error_message};
            disengage;
        }
        donation = DonationNode(
            food_type=self.food_type,
            quantity=self.quantity,
            expiry_time=self.expiry_time,
            status="pending",
            dispatched=False
        );
        here +>:Offers():+> donation;
        root ++> donation;
        self.created_donation = donation;
        print(f"[SupplyAgent] Created donation of {self.quantity} x '{self.food_type}' from '{business_name}' (expiry={self.expiry_time}).");
        report {
            "status": "created",
            "business": business_name,
            "food_type": self.food_type,
            "quantity": self.quantity,
            "expiry_time": self.expiry_time
        };
        disengage;
    }
}
"}

{"file_path": "/workspace/tests/test_nourish.jac", "content": """"Behavior tests for the Nourish model and the supply_manager walker."""

import from services.nourish_model {
    HubNode,
    BusinessNode,
    DonationNode,
    VolunteerNode,
    ShelterNode,
    Offers
}
import from services.supply_agent { supply_manager }

def make_business(name: str) -> BusinessNode {
    biz = BusinessNode(
        name=name, location="Main St", business_type="bakery", contact="555-0100"
    );
    root ++> biz;
    return biz;
}

test "valid upload reports created summary and pending donation" {
    biz = make_business("Sunrise Bakery");
    w = biz spawn supply_manager(
        food_type="bread", quantity=12, expiry_time="2999-12-31T18:00:00"
    );
    assert len(w.reports) == 1;
    assert w.reports[0] == {
        "status": "created",
        "business": "Sunrise Bakery",
        "food_type": "bread",
        "quantity": 12,
        "expiry_time": "2999-12-31T18:00:00"
    };
    assert list(w.reports[0].keys()) == ["status", "business", "food_type", "quantity", "expiry_time"];
    d = w.created_donation;
    assert d is not None;
    assert d.status == "pending";
    assert d.dispatched == False;
    assert d.food_type == "bread";
    assert d.quantity == 12;
    assert w.error_message == "";
}

test "donation is wired from business via Offers and from root" {
    biz = make_business("Edge Cafe");
    w = biz spawn supply_manager(
        food_type="soup", quantity=5, expiry_time="2999-01-01T00:00:00"
    );
    d = w.created_donation;
    offered = [biz ->:Offers:->];
    assert len(offered) == 1;
    assert offered[0] == d;
    assert d in [root -->];
}

test "expired food is rejected with exact message" {
    biz = make_business("Old Deli");
    w = biz spawn supply_manager(
        food_type="milk", quantity=3, expiry_time="2000-01-01T00:00:00"
    );
    expected = "REJECTED: Food 'milk' from 'Old Deli' is already expired (expiry=2000-01-01T00:00:00).";
    assert len(w.reports) == 1;
    assert w.reports[0] == {"status": "error", "message": expected};
    assert w.error_message == expected;
    assert w.created_donation is None;
    assert len([biz ->:Offers:->]) == 0;
}

test "model nodes keep declared defaults" {
    assert HubNode().name == "Nourish Hub";
    d = DonationNode(food_type="rice", quantity=1, expiry_time="2999-01-01T00:00:00");
    assert d.status == "pending";
    assert d.dispatched == False;
    v = VolunteerNode(name="Ana", vehicle_type="van", location="North", contact="555");
    assert v.is_available == True;
    s = ShelterNode(
        name="Haven", location="East", current_capacity=10, max_capacity=50, needed_items=["bread"]
    );
    assert s.max_capacity == 50;
}
"}

