import os;
import from jaclang.byllm.lib { Model }

"""True exactly when UARRIVED_AI_OFF is set to "1" for the whole process."""
def ai_switched_off() -> bool {
    return os.environ.get("UARRIVED_AI_OFF", "") == "1";
}

"""False for None, True for any test double, and for a real Model only when AI is on and ANTHROPIC_API_KEY is non-blank."""
def model_ready(model: any) -> bool {
    if model is None {
        return False;
    }
    if not isinstance(model, Model) {
        return True;
    }
    if ai_switched_off() {
        return False;
    }
    return bool(os.environ.get("ANTHROPIC_API_KEY", "").strip());
}
"}

