def clear_env() -> None {
    os.environ.pop("UARRIVED_AI_OFF", None);
    os.environ.pop("ANTHROPIC_API_KEY", None);
}

test "ai_switched_off follows UARRIVED_AI_OFF" {
    clear_env();
    assert not mm.ai_switched_off();
    os.environ["UARRIVED_AI_OFF"] = "0";
    assert not mm.ai_switched_off();
    os.environ["UARRIVED_AI_OFF"] = "1";
    assert mm.ai_switched_off();
    clear_env();
}

test "model_ready for None and test doubles" {
    clear_env();
    assert not mm.model_ready(None);
    os.environ["UARRIVED_AI_OFF"] = "1";
    assert mm.model_ready(MockLLM(model_name="mockllm", config={"outputs": []}));
    clear_env();
    assert mm.model_ready(MockLLM(model_name="mockllm", config={"outputs": []}));
}

test "model_ready for a real Model needs key and AI on" {
    clear_env();
    m = real_model();
    assert not mm.model_ready(m);
    os.environ["ANTHROPIC_API_KEY"] = "   ";
    assert not mm.model_ready(m);
    os.environ["ANTHROPIC_API_KEY"] = "sk-test";
    assert mm.model_ready(m);
    os.environ["UARRIVED_AI_OFF"] = "1";
    assert not mm.model_ready(m);
    clear_env();
}

test "guide_ready and translator_ready follow the globs" {
    clear_env();
    g.guide = MockLLM(model_name="mockllm", config={"outputs": []});
    t.translator = MockLLM(model_name="mockllm", config={"outputs": []});
    assert g.guide_ready();
    assert t.translator_ready();
    g.guide = None;
    t.translator = None;
    assert not g.guide_ready();
    assert not t.translator_ready();
}

test "answer_task_question returns the mocked GuideAnswer" {
    expected = g.GuideAnswer(text="Bring your passport and I-20 to the International Center.");
    g.guide = MockLLM(model_name="mockllm", config={"outputs": [expected]});
    result = g.answer_task_question(
        "Check-in at the International Center, 1500 Student Activities Building.",
        "",
        "What should I bring?",
        "en"
    );
    assert isinstance(result, g.GuideAnswer);
    assert result.text == "Bring your passport and I-20 to the International Center.";
    g.guide = None;
}

test "translate helpers return mocked results in call order" {
    tr = t.Translation(text="Desk for sale, $25");
    pt = t.PostTranslations(
        items=[
            t.PostText(language="en", title="Desk", description="Desk for $25"),
            t.PostText(language="zh", title="书桌", description="书桌 $25")
        ]
    );
    tl = t.TextList(texts=["Hello", "See you at 3 PM"]);
    t.translator = MockLLM(model_name="mockllm", config={"outputs": [tr, pt, tl]});
    r1 = t.translate("책상 팝니다, $25", "ko", "en");
    r2 = t.translate_post("책상", "책상 $25", "ko", ["en", "zh"]);
    r3 = t.translate_batch(["안녕하세요", "오후 3시에 봐요"], "ko", "en");
    assert isinstance(r1, t.Translation);
    assert r1.text == "Desk for sale, $25";
    assert isinstance(r2, t.PostTranslations);
    assert len(r2.items) == 2;
    assert r2.items[0].language == "en";
    assert r2.items[1].title == "书桌";
    assert isinstance(r3, t.TextList);
    assert r3.texts == ["Hello", "See you at 3 PM"];
    t.translator = None;
}
"}

