{"file_path": "/workspace/app_platform.jac", "content": "import os;
import from config { seed_demo_config }
import from nodes.IntegrationConfig { IntegrationConfig }
import from nodes.Platform { Platform }

"""Reuse the single Platform on root (refreshed from env) or create it."""
def get_platform_node() -> Platform {
    platforms = [root-->][?:Platform];
    if platforms {
        platform = platforms[0];
        platform.name = os.getenv("PLATFORM_NAME") or platform.name or "FILL_ME_PLATFORM_NAME";
        platform.environment = os.getenv("APP_ENV") or platform.environment or "dev";
        platform.default_chain = os.getenv("DEFAULT_CHAIN") or platform.default_chain or "base";
        platform.default_asset = os.getenv("DEFAULT_ASSET") or platform.default_asset or "USDC";
        return platform;
    }
    new_platform = Platform();
    root ++> new_platform;
    return new_platform;
}

"""Refresh the platform, seed the configs and report a summary with env-variable names."""
def:pub bootstrap_platform() -> dict {
    platform = get_platform_node();
    configs = seed_demo_config();
    return {
        "platform_id": jid(platform),
        "name": platform.name,
        "environment": platform.environment,
        "default_chain": platform.default_chain,
        "default_asset": platform.default_asset,
        "config_count": len(configs),
        "env_keys": {
            "platform_name": "PLATFORM_NAME",
            "app_env": "APP_ENV",
            "app_mode": "APP_MODE",
            "default_chain": "DEFAULT_CHAIN",
            "default_asset": "DEFAULT_ASSET",
            "stripe_publishable_key": "STRIPE_PUBLISHABLE_KEY",
            "stripe_secret_key": "STRIPE_SECRET_KEY",
            "stripe_webhook_secret": "STRIPE_WEBHOOK_SECRET",
            "wallet_provider_name": "WALLET_PROVIDER_NAME",
            "wallet_provider_api_key": "WALLET_PROVIDER_API_KEY",
            "wallet_provider_secret": "WALLET_PROVIDER_SECRET",
            "treasury_wallet": "TREASURY_WALLET",
            "rpc_url": "RPC_URL",
            "usdc_contract": "USDC_CONTRACT",
            "chain_id": "CHAIN_ID"
        }
    };
}

"""Report the platform summary plus the number of nodes directly under root."""
def:pub get_platform_overview() -> dict {
    platform = get_platform_node();
    return {
        "platform_id": jid(platform),
        "name": platform.name,
        "environment": platform.environment,
        "default_chain": platform.default_chain,
        "default_asset": platform.default_asset,
        "merchant_count": len([root-->])
    };
}
"}

{"file_path": "/workspace/test_unibank.jac", "content": "import os;
import from config { env_or, ensure_config, seed_demo_config, list_configs }
import from app_platform { get_platform_node, bootstrap_platform, get_platform_overview }
import from nodes.IntegrationConfig { IntegrationConfig }
import from nodes.Platform { Platform }

test "env_or returns env value or fallback" {
    os.environ["UNIBANK_TEST_VAR"] = "hello";
    assert env_or("UNIBANK_TEST_VAR", "fb") == "hello";
    os.environ["UNIBANK_TEST_VAR"] = "";
    assert env_or("UNIBANK_TEST_VAR", "fb") == "fb";
    os.environ.pop("UNIBANK_TEST_VAR", None);
    assert env_or("UNIBANK_TEST_VAR", "fb") == "fb";
}

test "ensure_config keeps one config per provider and overwrites in place" {
    first = ensure_config("acme_unique_test", "Acme", api_key="k1", secret_key="s1");
    assert first.config_id == "acme_unique_test_config";
    assert first.provider == "acme_unique_test";
    assert first.api_key == "k1";
    assert first.chain_id == "8453";
    assert first.updated_at != "";
    second = ensure_config("acme_unique_test", "Acme 2", api_key="k2");
    assert jid(second) == jid(first);
    assert second.label == "Acme 2";
    assert second.api_key == "k2";
    assert second.secret_key == "";
    matches = [c for c in list_configs() if c.provider == "acme_unique_test"];
    assert len(matches) == 1;
}

test "seed_demo_config seeds three configs from env without duplicates" {
    os.environ["STRIPE_SECRET_KEY"] = "sk_test_from_env";
    os.environ["CHAIN_ID"] = "84532";
    os.environ.pop("STRIPE_PUBLISHABLE_KEY", None);
    os.environ.pop("DEFAULT_CHAIN", None);
    os.environ.pop("APP_MODE", None);
    configs = seed_demo_config();
    assert [c.provider for c in configs] == ["stripe", "wallet_provider", "rpc"];
    assert configs[0].label == "Stripe Checkout";
    assert configs[0].secret_key == "sk_test_from_env";
    assert configs[0].api_key == "pk_test_FILL_ME_STRIPE_PUBLISHABLE_KEY";
    assert configs[1].treasury_wallet != "";
    assert configs[2].label == "Base RPC";
    assert configs[2].chain_id == "84532";
    assert configs[2].mode == "test";
    seed_demo_config();
    for p in ["stripe", "wallet_provider", "rpc"] {
        assert len([c for c in list_configs() if c.provider == p]) == 1;
    }
    os.environ.pop("STRIPE_SECRET_KEY", None);
    os.environ.pop("CHAIN_ID", None);
}

test "bootstrap_platform reuses one Platform and reports summary" {
    os.environ["PLATFORM_NAME"] = "UniBankTestPlatform";
    os.environ["APP_ENV"] = "staging_test";
    summary = bootstrap_platform();
    again = bootstrap_platform();
    assert summary["platform_id"] == again["platform_id"];
    assert summary["name"] == "UniBankTestPlatform";
    assert summary["environment"] == "staging_test";
    assert summary["config_count"] == 3;
    assert len(summary["env_keys"]) == 15;
    assert summary["env_keys"]["chain_id"] == "CHAIN_ID";
    assert summary["env_keys"]["platform_name"] == "PLATFORM_NAME";
    assert len([root-->][?:Platform]) == 1;
    overview = get_platform_overview();
    assert overview["platform_id"] == summary["platform_id"];
    assert overview["name"] == "UniBankTestPlatform";
    assert "config_count" not in overview;
    assert overview["merchant_count"] == len([root-->]);
    assert overview["merchant_count"] >= 4;
    os.environ.pop("PLATFORM_NAME", None);
    os.environ.pop("APP_ENV", None);
}
"}

