87: def _ordinal(n: int) -> str {
88:     if 11 <= n % 100 <= 13 {
89:         return f"{n}th";
90:     }
91:     return f"{n}" + {1: "st", 2: "nd", 3: "rd"}.get(n % 10, "th");
92: }
93: 
94: """Spoken date: "Tuesday, September 29th" (year only when it is not this year)."""
95: def _spoken_date(y: int, m: int, d: int, today: date) -> str {
96:     try {
97:         dt = date(y, m, d);
98:     } except ValueError {
99:         return f"{MONTH_NAMES[m - 1]} {_ordinal(d)}";
100:     }
101:     out = f"{WEEKDAYS[dt.weekday()]}, {MONTH_NAMES[m - 1]} {_ordinal(d)}";
102:     if y != today.year {
103:         out += f", {y}";
104:     }
105:     return out;
106: }
107: 
108: """Year for a month/day with no year: the one closest to today."""
109: def _nearest_year(m: int, d: int, today: date) -> int {
110:     best = today.year;
111:     best_gap = 9999;
112:     for y in [today.year - 1, today.year, today.year + 1] {
113:         try {
114:             gap = abs((date(y, m, d) - today).days);
115:         } except ValueError {
116:             continue;
117:         }
118:         if gap < best_gap {
119:             best = y;
120:             best_gap = gap;
121:         }
122:     }
123:     return best;
124: }
125: 
126: """Is the word right before position `end` a street name (so St/Dr mean Street/Drive)?"""
127: def _street_before(text: str, end: int) -> bool {
128:     m = re.search(r"(\S+)\s+$", text[:end]);
129:     if m is None {
130:         return False;
131:     }
132:     prev = m.group(1);
133:     if re.search(r"[,.;:!?)\]]$", prev) {
134:         return False;
135:     }
136:     if re.fullmatch(r"\d+(st|nd|rd|th)?", prev) {
137:         return True;
138:     }
139:     return bool(re.fullmatch(r"[A-Z][\w'’.-]*", prev)) and prev.lower() not in NOT_STREET;
140: }
141: 
142: """Keep an abbreviation's period only when it also ends the sentence."""
143: def _tail_dot(dot: str, after: str) -> str {
144:     if not dot {
145:         return "";
146:     }
147:     if after.strip() == "" or re.match(r"\s+[A-Z]", after) {
148:         return ".";
149:     }
150:     return "";
151: }
152: 
153: def _road_sub(m: re.Match[str]) -> str {
154:     word = m.group(1);
155:     dot = m.group(2);
156:     text = m.string;
157:     after = text[m.end():];
158:     street = _street_before(text, m.start());
159:     next_cap = re.match(r"\s+[A-Z]", after) is not None;
160:     full = "";
161:     if word == "St" {
162:         full = "Street" if street or not next_cap else "Saint";
163:     } elif word == "Dr" {
164:         full = "Drive" if street or not next_cap else "Doctor";
165:     } elif word in ROAD_ALWAYS {
166:         full = ROAD_ALWAYS[word];
167:     } elif street {
168:         full = ROAD_AFTER_NAME[word];
169:     } else {
170:         return m.group(0);
171:     }
172:     if full == "Saint" or full == "Doctor" {
173:         return full;
174:     }
175:     return full + _tail_dot(dot, after);
176: }
177: 
178: def _day_sub(m: re.Match[str]) -> str {
179:     return DAY_ABBR[m.group(1)] + _tail_dot(m.group(2), m.string[m.end():]);
180: }
181: 
182: def _dir_sub(m: re.Match[str]) -> str {
183:     return DIRECTIONS[m.group(1)];
184: }
185: 
186: def _time_sub(m: re.Match[str]) -> str {
187:     h = int(m.group(1));
188:     mm = m.group(2) or "00";
189:     ap = m.group(3).lower();
190:     if h > 12 or int(mm) > 59 {
191:         return m.group(0);
192:     }
193:     if h == 12 and mm == "00" {
194:         return "noon" if ap == "p" else "midnight";
195:     }
196:     clock = str(h) if mm == "00" else f"{h}:{mm}";
197:     return clock + (" p.m." if ap == "p" else " a.m.");
198: }
199: 
200: """Spoken form of a 24-hour clock time: 22:00 -> "10 p.m.", 19:30 -> "7:30 p.m.",
201: 09:05 -> "9:05 a.m.", 12:00 -> "noon", 00:00 -> "midnight"."""
202: def _spoken_24h(h: int, mm: str) -> str {
203:     if mm == "00" and h == 12 {
204:         return "noon";
205:     }
206:     if mm == "00" and h == 0 {
207:         return "midnight";
208:     }
209:     h12 = h % 12 or 12;
210:     clock = str(h12) if mm == "00" else f"{h12}:{mm}";
211:     return clock + (" p.m." if h >= 12 else " a.m.");
212: }
213: 
214: """24-hour times that can't be 12-hour ones: hour 13-23 or 0, a leading zero
215: ("09:00") or seconds ("20:00:00"). Bare "10:30" stays as written."""
216: def _clock24_sub(m: re.Match[str]) -> str {
217:     hh = m.group(1);
218:     h = int(hh);
219:     mm = m.group(2);
220:     if h > 23 or int(mm) > 59 {
221:         return m.group(0);
222:     }
223:     if h >= 13 or h == 0 or (len(hh) == 2 and hh.startswith("0")) or m.group(3) {
224:         return _spoken_24h(h, mm);
225:     }
226:     return m.group(0);
227: }
228: 
229: def _money_sub(m: re.Match[str]) -> str {
230:     dollars = int(m.group(1).replace(",", ""));
231:     cents = int(m.group(2)) if m.group(2) else 0;
232:     out = f"{dollars} dollar" + ("" if dollars == 1 else "s");
233:     if cents > 0 {
234:         out += f" and {cents} cent" + ("" if cents == 1 else "s");
235:     }
236:     return out;
237: }
238: 
239: def _distance_sub(m: re.Match[str]) -> str {
240:     num: str = m.group(1);
241:     if num.endswith(".0") {
242:         num = num[:-2];
243:     }
244:     unit: str = {"mi": "mile", "min": "minute", "mins": "minute", "hr": "hour", "hrs": "hour", "ft": "foot"}[m.group(2)];
245:     if num != "1" {
246:         unit = "feet" if unit == "foot" else unit + "s";
247:     }
248:     return num + " " + unit;
249: }
250: 
251: """Line-by-line markdown flattening: drop headings, bullets and list numbers;
252: end each line with punctuation so flattened lines stay separate sentences."""
253: def _flatten_lines(text: str) -> str {
254:     out: list[str] = [];
255:     for raw in text.splitlines() {
256:         line: str = raw.strip();
257:         line = re.sub(r"^#{1,6}\s*", "", line);
258:         line = re.sub(r"^>\s?", "", line);
259:         line = re.sub(r"^[-*•+]\s+", "", line);
260:         line = re.sub(r"^\d{1,2}[.)]\s+", "", line);
261:         line = line.strip();
262:         if line {
263:             out.append(line);
264:         }
265:     }
266:     for i in range(len(out) - 1) {
267:         if not re.search(r"[.!?:;,]$", out[i]) {
268:             out[i] = out[i] + ".";
269:         }
270:     }
271:     return " ".join(out);
272: }
