import os;
import tempfile;
import from jaclang.runtimelib.testing { JacTestClient }

"""Absolute path to the app entry point, independent of the working directory."""
def app_entry() -> str {
    here = os.path.dirname(os.path.abspath(__file__));
    return os.path.join(os.path.dirname(here), "main.jac");
}

"""Pull the reports list out of a walker response envelope."""
def reports_of(body: dict) -> list {
    if "reports" in body {
        return list(body["reports"]);
    }
    if "data" in body and isinstance(body["data"], dict) and "reports" in body["data"] {
        return list(body["data"]["reports"]);
    }
    return [];
}

test "preview_week endpoint returns the saturday acceptance label" {
    client = JacTestClient.from_file(app_entry(), base_path=tempfile.mkdtemp());
    resp = client.post("/walker/preview_week", json={"date_str": "2026-09-26"});
    assert resp.status_code == 200, f"status {resp.status_code}: {resp.text}";
    reports = reports_of(dict(resp.json()));
    assert len(reports) == 1, f"unexpected body: {resp.text}";
    r: dict = dict(reports[0]);
    assert r["label"] == "Monday, September 28, 2026", r["label"];
    assert r["monday"] == "2026-09-28";
    assert r["day_index"] == -2;
    assert r["is_weekend"] == True;
    client.close();
}

test "preview_week endpoint keeps weekdays on their current monday" {
    client = JacTestClient.from_file(app_entry(), base_path=tempfile.mkdtemp());
    resp = client.post("/walker/preview_week", json={"date_str": "2026-09-24"});
