    assert r["day_index"] == 3;
    assert r["label"] == "Monday, September 21, 2026";
    assert r["is_weekend"] == False;
    client.close();
}

test "home route serves the app page" {
    client = JacTestClient.from_file(app_entry(), base_path=tempfile.mkdtemp());
    resp = client.get("/");
