1: """Mindcraft island service: graph model, deterministic check-in, crisis guard, public walkers.
2: 
3: Graph shape: root -> MindIsland -> EmotionalEntity -> InteractionEvent
4:                                    EmotionalEntity -> ValueAction
5: """
6: 
7: node MindIsland {
8:     has name: str = "Mind Island";
9: }
10: 
11: node EmotionalEntity {
12:     has label: str = "";
13:     has emotion: str = "";
14:     has intensity: int = 1;
15:     has shape: str = "stone";
16:     has color: str = "#9ca3af";
17:     has placed: bool = False;
18:     has x: int = 0;
19:     has y: int = 0;
20:     has note: str = "";
21: }
22: 
23: node InteractionEvent {
24:     has kind: str = "";
25:     has result: str = "";
26: }
27: 
28: node ValueAction {
29:     has value: str = "";
30:     has action: str = "";
31: }
32: 
33: glob INTERACTIONS: list[str] = ["breathe", "name", "soften", "listen"];
34: 
35: glob CRISIS_TERMS: list[str] = [
36:     "suicide", "suicidal", "kill myself", "end my life", "want to die",
37:     "hurt myself", "self harm", "self-harm", "no reason to live", "better off dead"
38: ];
39: 
40: glob CRISIS_MESSAGE: str = "It sounds like you may be in danger right now. Please reach out for support immediately: call or text 988 (Suicide and Crisis Lifeline, US), call your local emergency number, or contact someone you trust and tell them how you feel. You do not have to go through this alone.";
41: 
42: glob EMOTION_TABLE: list[dict] = [
43:     {"emotion": "anxiety", "label": "Anxious cloud", "shape": "cloud", "color": "#c7d2fe", "keywords": ["anxious", "anxiety", "worried", "worry", "nervous", "stressed", "stress", "overwhelmed"]},
44:     {"emotion": "sadness", "label": "Heavy stone", "shape": "stone", "color": "#93c5fd", "keywords": ["sad", "down", "lonely", "alone", "empty", "grief", "cry", "hopeless"]},
45:     {"emotion": "anger", "label": "Hot ember", "shape": "ember", "color": "#fca5a5", "keywords": ["angry", "anger", "mad", "furious", "annoyed", "frustrated", "irritated"]},
46:     {"emotion": "fear", "label": "Shadow", "shape": "shadow", "color": "#d4d4d8", "keywords": ["afraid", "scared", "fear", "terrified", "panic"]},
47:     {"emotion": "tiredness", "label": "Drifting log", "shape": "log", "color": "#d6c4a8", "keywords": ["tired", "exhausted", "drained", "burnt out", "burned out", "sleepy"]},
48:     {"emotion": "joy", "label": "Bright flower", "shape": "flower", "color": "#fde68a", "keywords": ["happy", "glad", "joy", "excited", "grateful", "calm", "hopeful"]}
49: ];
50: 
51: glob INTERACTION_RESULTS: dict = {
52:     "breathe": "You took three slow breaths with this feeling beside you.",
53:     "name": "You named the feeling out loud. Naming it gives it a shape you can hold.",
54:     "soften": "You let your shoulders drop. The feeling grew a little lighter.",
55:     "listen": "You asked the feeling what it needs and listened without judging."
56: };
57: 
58: """True when the text contains urgent / crisis language."""
59: def is_crisis(text: str) -> bool {
60:     t = text.lower();
61:     for term in CRISIS_TERMS {
62:         if term in t {
63:             return True;
64:         }
65:     }
66:     return False;
67: }
68: 
69: """Deterministic keyword mapping from free text to feeling specs."""
70: def detect_emotions(text: str) -> list[dict] {
71:     t = text.lower();
72:     intensity = 1;
73:     for amp in ["very", "so ", "really", "extremely", "too "] {
74:         if amp in t {
75:             intensity = intensity + 1;
76:         }
77:     }
78:     if intensity > 3 {
79:         intensity = 3;
80:     }
81:     found: list[dict] = [];
82:     for spec in EMOTION_TABLE {
83:         kws: list[str] = spec["keywords"] as list[str];
84:         for kw in kws {
85:             if kw in t {
86:                 found.append({
87:                     "emotion": spec["emotion"],
88:                     "label": spec["label"],
89:                     "shape": spec["shape"],
90:                     "color": spec["color"],
91:                     "intensity": intensity
92:                 });
93:                 break;
94:             }
95:         }
96:     }
97:     if len(found) == 0 {
98:         found.append({
99:             "emotion": "unnamed",
100:             "label": "Unnamed pebble",
101:             "shape": "pebble",
102:             "color": "#cbd5e1",
103:             "intensity": intensity
104:         });
105:     }
106:     return found;
107: }
108: 
109: """Plain dict projection of an entity for the client."""
110: def entity_view(e: EmotionalEntity) -> dict {
111:     return {
112:         "id": jid(e),
113:         "label": e.label,
114:         "emotion": e.emotion,
115:         "intensity": e.intensity,
116:         "shape": e.shape,
117:         "color": e.color,
118:         "placed": e.placed,
119:         "x": e.x,
120:         "y": e.y,
121:         "note": e.note
122:     };
123: }
124: 
125: """Get-or-create the island attached to the given root."""
126: def get_island(r: Root) -> MindIsland {
127:     islands = [r -->[?:MindIsland]];
128:     if len(islands) > 0 {
129:         return islands[0];
130:     }
131:     island = MindIsland();
132:     r ++> island;
133:     return island;
134: }
135: 
136: """Resolve an entity id to an EmotionalEntity, or None."""
137: def find_entity(entity_id: str) -> EmotionalEntity | None {
138:     if not entity_id {
139:         return None;
140:     }
141:     found: any = None;
142:     try {
143:         found = jobj(entity_id);
144:     } except Exception {
145:         return None;
146:     }
147:     if isinstance(found, EmotionalEntity) {
148:         return found;
149:     }
150:     return None;
151: }
152: 
153: def clamp(v: int) -> int {
154:     if v < 5 {
155:         return 5;
156:     }
157:     if v > 95 {
158:         return 95;
159:     }
160:     return v;
161: }
162: 
163: walker:pub get_world {
164:     has reports: list[dict] = [];
165: 
166:     can run with Root entry {
167:         island = get_island(here);
168:         entities = [island -->[?:EmotionalEntity]];
169:         report {
170:             "entities": [entity_view(e) for e in entities],
171:             "interactions": INTERACTIONS
172:         };
173:     }
174: }
175: 
176: walker:pub manifest_emotion {
177:     has text: str = "";
178:     has reports: list[dict] = [];
179: 
180:     can run with Root entry {
181:         t = self.text.strip();
182:         if not t {
183:             report {"crisis": False, "error": "Describe how you feel first.", "message": "", "entities": []};
184:             disengage;
185:         }
186:         if is_crisis(t) {
187:             report {"crisis": True, "message": CRISIS_MESSAGE, "entities": []};
188:             disengage;
189:         }
190:         island = get_island(here);
191:         created: list[dict] = [];
192:         for spec in detect_emotions(t) {
193:             e = EmotionalEntity(
194:                 label=spec["label"],
195:                 emotion=spec["emotion"],
196:                 intensity=spec["intensity"],
197:                 shape=spec["shape"],
198:                 color=spec["color"],
199:                 note=t
200:             );
201:             island ++> e;
202:             created.append(entity_view(e));
203:         }
204:         report {"crisis": False, "message": "", "entities": created};
205:     }
206: }
207: 
208: walker:pub place_entity {
209:     has entity_id: str = "";
210:     has x: int = 0;
211:     has y: int = 0;
212:     has reports: list[dict] = [];
213: 
214:     can run with Root entry {
215:         e = find_entity(self.entity_id);
216:         if e is None {
217:             report {"error": "Feeling not found."};
218:             disengage;
219:         }
220:         e.placed = True;
221:         e.x = clamp(self.x);
222:         e.y = clamp(self.y);
223:         report {"entity": entity_view(e)};
224:     }
225: }
226: 
227: walker:pub apply_interaction {
228:     has entity_id: str = "";
229:     has kind: str = "";
230:     has reports: list[dict] = [];
231: 
232:     can run with Root entry {
233:         e = find_entity(self.entity_id);
234:         if e is None {
235:             report {"error": "Feeling not found."};
236:             disengage;
237:         }
238:         if not e.placed {
239:             report {"error": "Place the feeling on the island first."};
240:             disengage;
241:         }
242:         if self.kind not in INTERACTIONS {
243:             report {"error": "Unknown interaction."};
244:             disengage;
245:         }
246:         if self.kind == "soften" and e.intensity > 1 {
247:             e.intensity = e.intensity - 1;
248:         }
249:         result = INTERACTION_RESULTS[self.kind];
250:         ev = InteractionEvent(kind=self.kind, result=result);
251:         e ++> ev;
252:         report {"entity": entity_view(e), "event": {"kind": ev.kind, "result": ev.result}};
253:     }
254: }
255: 
256: walker:pub commit_value_action {
257:     has entity_id: str = "";
258:     has value: str = "";
259:     has action: str = "";
260:     has reports: list[dict] = [];
261: 
262:     can run with Root entry {
263:         e = find_entity(self.entity_id);
264:         if e is None {
265:             report {"error": "Feeling not found."};
266:             disengage;
267:         }
268:         if not e.placed {
269:             report {"error": "Place the feeling on the island first."};
270:             disengage;
271:         }
272:         v = self.value.strip();
273:         a = self.action.strip();
274:         if not v or not a {
275:             report {"error": "Add both what matters to you and one concrete next action."};
276:             disengage;
277:         }
278:         va = ValueAction(value=v, action=a);
279:         e ++> va;
280:         report {"entity": entity_view(e), "action": {"value": va.value, "action": va.action}};
281:     }
282: }
283: 
284: walker:pub get_act_path {
285:     has entity_id: str = "";
286:     has reports: list[dict] = [];
287: 
288:     can run with Root entry {
289:         e = find_entity(self.entity_id);
290:         if e is None {
291:             report {"error": "Feeling not found."};
292:             disengage;
293:         }
294:         events = [e -->[?:InteractionEvent]];
295:         actions = [e -->[?:ValueAction]];
296:         report {
297:             "entity": entity_view(e),
298:             "events": [{"kind": ev.kind, "result": ev.result} for ev in events],
299:             "actions": [{"value": va.value, "action": va.action} for va in actions]
300:         };
301:     }
302: }
303: 
304: walker:pub reset_demo {
305:     has reports: list[dict] = [];
306: 
307:     can run with Root entry {
308:         island = get_island(here);
309:         entities = [island -->[?:EmotionalEntity]];
310:         cleared = len(entities);
311:         for e in entities {
312:             for ev in [e -->[?:InteractionEvent]] {
313:                 del ev;
314:             }
315:             for va in [e -->[?:ValueAction]] {
316:                 del va;
317:             }
318:             del e;
319:         }
320:         report {"cleared": cleared};
321:     }
322: }

1: """Mindcraft single-page check-in UI: island, check-in form, interactions, intention and path."""
2: 
3: sv import from ..services.island {
4:     get_world,
5:     manifest_emotion,
6:     place_entity,
7:     apply_interaction,
8:     commit_value_action,
9:     get_act_path,
10:     reset_demo
11: }
12: 
13: def:pub MindcraftApp() -> JsxElement {
14:     has entities: list[dict] = [];
15:     has interactions: list[str] = [];
16:     has text: str = "";
17:     has crisisMsg: str = "";
18:     has selectedId: str = "";
19:     has value: str = "";
20:     has action: str = "";
21:     has pathEvents: list[dict] = [];
22:     has pathActions: list[dict] = [];
23:     has pathLoaded: bool = False;
24:     has notice: str = "";
25:     has error: str = "";
26:     has loading: bool = True;
27:     has busy: bool = False;
28: 
29:     async def load_world() -> None {
30:         try {
31:             result = root spawn get_world();
32:             if result.reports and len(result.reports) > 0 {
33:                 data = result.reports[0];
34:                 entities = data["entities"];
35:                 interactions = data["interactions"];
36:             }
37:         } except Exception {
38:             error = "Could not load the island. Try refreshing.";
39:         }
40:         loading = False;
41:     }
42: 
43:     async can with entry {
44:         await load_world();
45:     }
46: 
47:     async def load_path(eid: str) -> None {
48:         result = root spawn get_act_path(entity_id=eid);
49:         if result.reports and len(result.reports) > 0 {
50:             data = result.reports[0];
51:             if data["error"] {
52:                 error = str(data["error"]);
53:             } else {
54:                 pathEvents = data["events"];
55:                 pathActions = data["actions"];
56:                 pathLoaded = True;
57:             }
58:         }
59:     }
60: 
61:     async def check_in() -> None {
62:         error = "";
63:         notice = "";
64:         crisisMsg = "";
65:         if not text.strip() {
66:             error = "Describe how you feel first.";
67:             return;
68:         }
69:         busy = True;
70:         result = root spawn manifest_emotion(text=text);
71:         if result.reports and len(result.reports) > 0 {
72:             data = result.reports[0];
73:             if data["crisis"] {
74:                 crisisMsg = str(data["message"]);
75:             } elif data["error"] {
76:                 error = str(data["error"]);
77:             } else {
78:                 notice = str(len(data["entities"])) + " feeling(s) arrived. Place them on the island.";
79:                 text = "";
80:             }
81:         }
82:         await load_world();
83:         busy = False;
84:     }
85: 
86:     async def select(eid: str) -> None {
87:         selectedId = eid;
88:         pathEvents = [];
89:         pathActions = [];
90:         pathLoaded = False;
91:         error = "";
92:         await load_path(eid);
93:     }
94: 
95:     async def place(eid: str, idx: int) -> None {
96:         error = "";
97:         px = 20 + (idx * 23) % 60;
98:         py = 30 + (idx * 17) % 40;
99:         result = root spawn place_entity(entity_id=eid, x=px, y=py);
100:         if result.reports and len(result.reports) > 0 {
101:             data = result.reports[0];
102:             if data["error"] {
103:                 error = str(data["error"]);
104:             }
105:         }
106:         selectedId = eid;
107:         await load_world();
108:         await load_path(eid);
109:     }
110: 
111:     async def interact(kind: str) -> None {
112:         error = "";
113:         result = root spawn apply_interaction(entity_id=selectedId, kind=kind);
114:         if result.reports and len(result.reports) > 0 {
115:             data = result.reports[0];
116:             if data["error"] {
117:                 error = str(data["error"]);
118:             } else {
119:                 notice = str(data["event"]["result"]);
120:             }
121:         }
122:         await load_world();
123:         await load_path(selectedId);
124:     }
125: 
126:     async def commit() -> None {
127:         error = "";
128:         result = root spawn commit_value_action(entity_id=selectedId, value=value, action=action);
129:         if result.reports and len(result.reports) > 0 {
130:             data = result.reports[0];
131:             if data["error"] {
132:                 error = str(data["error"]);
133:             } else {
134:                 notice = "Next action saved: " + str(data["action"]["action"]);
135:                 value = "";
136:                 action = "";
137:             }
138:         }
139:         await load_path(selectedId);
140:     }
141: 
142:     async def reset() -> None {
143:         error = "";
144:         crisisMsg = "";
145:         result = root spawn reset_demo();
146:         if result.reports and len(result.reports) > 0 {
147:             notice = "Island cleared (" + str(result.reports[0]["cleared"]) + " feeling(s) released).";
148:         }
149:         selectedId = "";
150:         pathEvents = [];
151:         pathActions = [];
152:         pathLoaded = False;
153:         await load_world();
154:     }
155: 
156:     def on_text(e: ChangeEvent) { text = e.target.value; }
157:     def on_value(e: ChangeEvent) { value = e.target.value; }
158:     def on_action(e: ChangeEvent) { action = e.target.value; }
159: 
160:     pending = [en for en in entities if not en["placed"]];
161:     placed = [en for en in entities if en["placed"]];
162:     selected: dict | None = None;
163:     for en in entities {
164:         if en["id"] == selectedId {
165:             selected = en;
166:         }
167:     }
168:     selected_placed: bool = selected is not None and selected["placed"];
169:     selected_label: str = str(selected["label"]) if selected is not None else "";
170:     selected_note: str = str(selected["note"]) if selected is not None else "";
171: 
172:     return <main className="mc-shell">
173:         <header className="mc-header">
174:             <h1>Mindcraft</h1>
175:             <p>Name how you feel, give it a place on your island, and choose one gentle next step.</p>
176:         </header>
177:         {crisisMsg and <div className="mc-crisis" role="alert">
