3: FleetModule.jac is a client-only module, so jac test cannot import it
4: directly. These tests read its source and check the demo records it declares.
5: """
6: 
7: import os;
8: 
9: def fleet_source() -> str {
10:     here = os.path.dirname(os.path.abspath(__file__));
11:     path = os.path.join(here, "..", "components", "FleetModule.jac");
12:     with open(path) as fh {
13:         return fh.read();
14:     }
15: }
16: 
17: def count_status(status: str) -> int {
18:     return fleet_source().count(f'"status": "{status}"');
19: }
20: 
21: test "fleet has six vehicles" {
22:     assert fleet_source().count('{"plate": "ORB-') == 6;
23: }
24: 
25: test "summary counts match the demo fleet" {
