29: }
30: 
31: test "filters cover All, Active, Maintenance, and Idle" {
32:     assert 'glob FILTERS: list = ["All", "Active", "Maintenance", "Idle"];' in fleet_source();
33:     assert 'selected == "All" or v["status"] == selected' in fleet_source();
34: }
