{"file_path": "/workspace/components/FleetModule.jac", "content": """"Fleet registry: demo vehicles, status counts, status filter, and vehicle table."""

glob VEHICLES: list = [
    {"plate": "ORB-101", "type": "Box Truck", "driver": "Maria Lopez", "status": "Active", "fuel": 82, "speed": 54, "location": "Depot North"},
    {"plate": "ORB-102", "type": "Cargo Van", "driver": "James Chen", "status": "Active", "fuel": 67, "speed": 38, "location": "Harbor Road"},
    {"plate": "ORB-103", "type": "Flatbed", "driver": "Aisha Khan", "status": "Maintenance", "fuel": 15, "speed": 0, "location": "Service Bay 2"},
    {"plate": "ORB-104", "type": "Pickup", "driver": "Tom Becker", "status": "Active", "fuel": 91, "speed": 62, "location": "Route 9"},
    {"plate": "ORB-105", "type": "Refrigerated Truck", "driver": "Lena Novak", "status": "Idle", "fuel": 48, "speed": 0, "location": "Depot South"},
    {"plate": "ORB-106", "type": "Cargo Van", "driver": "Omar Haddad", "status": "Active", "fuel": 73, "speed": 45, "location": "Central Market"}
];

def VehicleRow(vehicle: dict) -> JsxElement {
    status = str(vehicle["status"]);
    badge = f"status-badge status-{status.lower()}";
    return <tr data-testid="vehicle-row">
        <td>{vehicle["plate"]}</td>
        <td>{vehicle["type"]}</td>
        <td>{vehicle["driver"]}</td>
        <td><span className={badge}>{status}</span></td>
        <td>{f"{vehicle['fuel']}%"}</td>
        <td>{f"{vehicle['speed']} km/h"}</td>
        <td>{vehicle["location"]}</td>
    </tr>;
}

def:pub FleetModule() -> JsxElement {
    has selected: str = "all";

    active = len([v for v in VEHICLES if str(v["status"]).lower() == "active"]);
    maintenance = len([v for v in VEHICLES if str(v["status"]).lower() == "maintenance"]);
    idle = len([v for v in VEHICLES if str(v["status"]).lower() == "idle"]);
    shown = [v for v in VEHICLES if selected == "all" or str(v["status"]).lower() == selected.lower()];

    def on_status(e: any) -> None {
        selected = e.target.value;
    }

    return <div className="fleet-page">
        <header className="fleet-header">
            <h1>Fleet Management</h1>
            <p>Vehicle registry for the operations team.</p>
        </header>
        <section className="summary-grid">
            <div className="summary-card"><div className="summary-label">Total Fleet</div><div className="summary-value" data-testid="count-total">{len(VEHICLES)}</div></div>
            <div className="summary-card"><div className="summary-label">Active Now</div><div className="summary-value" data-testid="count-active">{active}</div></div>
            <div className="summary-card"><div className="summary-label">In Maintenance</div><div className="summary-value" data-testid="count-maintenance">{maintenance}</div></div>
            <div className="summary-card"><div className="summary-label">Idle</div><div className="summary-value" data-testid="count-idle">{idle}</div></div>
        </section>
        <div className="toolbar">
            <label className="filter-group">
                <span className="filter-label">Status</span>
                <select className="status-select" data-testid="status-filter" value={selected} onChange={on_status}>
                    <option value="all">All</option>
                    <option value="active">Active</option>
                    <option value="maintenance">Maintenance</option>
                    <option value="idle">Idle</option>
                </select>
            </label>
            <span className="shown-count" data-testid="shown-count">{f"Showing {len(shown)} of {len(VEHICLES)} vehicles"}</span>
        </div>
        <div className="table-wrap">
            <table className="fleet-table">
                <thead>
                    <tr><th>Plate</th><th>Type</th><th>Driver</th><th>Status</th><th>Fuel</th><th>Speed</th><th>Location</th></tr>
                </thead>
                <tbody>
                    {[<VehicleRow key={v["plate"]} vehicle={v} /> for v in shown]}
                </tbody>
            </table>
        </div>
    </div>;
}
"}

