1: """Graph data and public Pomodoro timer/settings endpoints."""
2: 
3: import from datetime { datetime, timezone }
4: 
5: node Event {
6:     has year: int,
7:         month: int,
8:         day: int,
9:         hour: int,
10:         minute: int,
11:         title: str,
12:         description: str = "",
13:         work_min: int = 25,
14:         break_min: int = 5,
15:         cycles: int = 4;
16: }
17: 
18: node Session {
19:     has event_id: str,
20:         phase: str = "work",
21:         cycle_ix: int = 0,
22:         running: bool = True,
23:         phase_started_at: str = "",
24:         phase_elapsed_before_pause: int = 0;
25: }
26: 
27: node Settings {
28:     has idle_text: str = "Ready to focus";
29: }
30: 
31: def now_iso() -> str {
32:     return datetime.now(timezone.utc).isoformat();
33: }
34: 
35: def find_event(event_id: str) -> Event | None {
36:     for e in [root -->[?:Event]] {
37:         if jid(e) == event_id {
38:             return e;
39:         }
40:     }
41:     return None;
42: }
43: 
44: def find_session(session_id: str) -> Session | None {
45:     for s in [root -->[?:Session]] {
46:         if jid(s) == session_id {
47:             return s;
48:         }
49:     }
50:     return None;
51: }
52: 
53: def:pub create_event(
54:     year: int,
55:     month: int,
56:     day: int,
57:     hour: int,
58:     minute: int,
59:     title: str,
60:     description: str,
61:     work_min: int,
62:     break_min: int,
63:     cycles: int
64: ) -> Event {
65:     ev = Event(
66:         year=year,
67:         month=month,
68:         day=day,
69:         hour=hour,
70:         minute=minute,
71:         title=title,
72:         description=description,
73:         work_min=work_min,
74:         break_min=break_min,
75:         cycles=max(1, cycles)
76:     );
77:     root ++> ev;
78:     return ev;
79: }
80: 
81: def:pub start_pomodoro(event_id: str) -> Session {
82:     for s in [root -->[?:Session]] {
83:         if s.phase != "done" {
84:             s.phase = "done";
85:             s.running = False;
86:         }
87:     }
88:     sess = Session(
89:         event_id=event_id,
90:         phase="work",
91:         cycle_ix=0,
92:         running=True,
93:         phase_started_at=now_iso(),
94:         phase_elapsed_before_pause=0
95:     );
96:     root ++> sess;
97:     return sess;
98: }
99: 
100: def:pub advance_phase(session_id: str) -> Session | None {
101:     sess = find_session(session_id);
102:     if sess is None {
103:         return None;
104:     }
105:     if sess.phase == "done" {
106:         return sess;
107:     }
108:     ev = find_event(sess.event_id);
109:     cycles = ev.cycles if ev is not None else 1;
110:     if sess.phase == "work" {
111:         if sess.cycle_ix + 1 >= cycles {
112:             sess.phase = "done";
113:             sess.running = False;
114:         } else {
115:             sess.phase = "break";
116:         }
117:     } else {
118:         sess.phase = "work";
119:         sess.cycle_ix += 1;
120:     }
121:     sess.phase_started_at = now_iso();
122:     sess.phase_elapsed_before_pause = 0;
123:     return sess;
124: }
125: 
126: def:pub get_settings() -> Settings {
127:     found = [root -->[?:Settings]];
128:     if found {
129:         return found[0];
130:     }
131:     st = Settings();
132:     root ++> st;
133:     return st;
134: }
135: 
136: def:pub set_idle_text(text: str) -> Settings {
137:     st = get_settings();
138:     st.idle_text = text;
139:     return st;
140: }

