{"file_path": "/workspace/endpoints.test.jac", "content": """"Tests for Pomodoro session transitions and settings persistence."""

test "new session retires previous active session" {
    ev = create_event(2026, 11, 1, 9, 0, "Focus", "", 25, 5, 2);
    first = start_pomodoro(jid(ev));
    assert first.phase == "work";
    assert first.cycle_ix == 0;
    assert first.running;
    second = start_pomodoro(jid(ev));
    assert first.phase == "done";
    assert not first.running;
    assert second.phase == "work";
    assert second.running;
}

test "two-cycle event advances break0 work1 done" {
    ev = create_event(2026, 11, 1, 10, 0, "Deep work", "", 25, 5, 2);
    sess = start_pomodoro(jid(ev));
    sid = jid(sess);
    s1 = advance_phase(sid);
    assert s1.phase == "break";
    assert s1.cycle_ix == 0;
    s2 = advance_phase(sid);
    assert s2.phase == "work";
    assert s2.cycle_ix == 1;
    s3 = advance_phase(sid);
    assert s3.phase == "done";
    assert not s3.running;
    s4 = advance_phase(sid);
    assert s4.phase == "done";
}

test "advance_phase unknown session returns None" {
    assert advance_phase("missing") is None;
}

test "settings use one persistent node" {
    a = get_settings();
    assert a.idle_text == "Ready to focus";
    set_idle_text("Take a breath");
    b = get_settings();
    assert b.idle_text == "Take a breath";
    assert jid(a) == jid(b);
    assert len([root -->[?:Settings]]) == 1;
}
"}

