14: walker PathfinderWalker {
15:     has start_category: str = "";
16:     has max_hops: int = 3;
17:     has max_paths: int = 3;
18:     has seed_resource_names: list[str] = [];
19:     has summary: dict = {};
20: 
21:     can search with Root entry {
22:         seeds: list = [];
23:         seen: list[str] = [];
24:         for r in [root --> [?:ResourceNode]] {
25:             if r.agency_name in self.seed_resource_names or r.category == self.start_category {
26:                 if r.agency_name not in seen {
27:                     seen.append(r.agency_name);
28:                     seeds.append(r);
29:                 }
30:             }
31:         }
32:         paths: list[dict] = [];
33:         for seed in seeds {
34:             if len(paths) >= self.max_paths {
35:                 break;
36:             }
37:             queue: list = [(seed, [], [seed.agency_name])];
38:             while len(queue) > 0 and len(paths) < self.max_paths {
39:                 item = queue.pop(0);
40:                 cur = item[0];
41:                 hops: list = item[1];
42:                 visited: list = item[2];
43:                 if len(hops) >= 2 {
44:                     paths.append({
45:                         "start": seed.agency_name,
46:                         "end": cur.agency_name,
47:                         "hops": hops,
48:                         "hop_count": len(hops),
49:                         "total_days": _sum_days(hops)
50:                     });
51:                     continue;
52:                 }
53:                 if len(hops) >= self.max_hops {
54:                     continue;
55:                 }
56:                 nexts = [cur ->:leads_to:-> [?:ResourceNode]];
57:                 links = [edge cur ->:leads_to:->];
58:                 for (i, nxt) in enumerate(nexts) {
59:                     if nxt.agency_name in visited {
60:                         continue;
61:                     }
62:                     e = links[i];
63:                     hop = {
64:                         "from": cur.agency_name,
65:                         "to": nxt.agency_name,
66:                         "reason": e.transition_reason,
67:                         "days": e.typical_days,
68:                         "difficulty": e.difficulty
69:                     };
70:                     queue.append((nxt, hops + [hop], visited + [nxt.agency_name]));
71:                 }
72:             }
73:         }
74:         ranked = sorted([(p["total_days"], p["hop_count"], i) for (i, p) in enumerate(paths)]);
75:         ordered: list = [paths[t[2]] for t in ranked];
76:         self.summary = {
77:             "ok": True,
78:             "start_category": self.start_category,
79:             "max_hops": self.max_hops,
80:             "path_count": len(ordered),
81:             "paths": ordered
82:         };
83:         report self.summary;
84:     }
85: }
86: 
