88: sem PathfinderWalker = "Finds two-hop progression paths from the resources of a start category.";
89: sem PathfinderWalker.start_category = "Need category whose resources seed the search.";
90: sem PathfinderWalker.max_hops = "Maximum BFS depth over leads_to edges.";
91: sem PathfinderWalker.max_paths = "Maximum number of paths to report.";
