{"file_path": "/workspace/revdev_acceptance.jac", "content": """"Acceptance tests for the CivicMesh ImpactWalker and PathfinderWalker reports."""

import from graph.nodes { PersonNode, NeedNode, ResourceNode, ApplicationNode }
import from graph.edges { has_need, applied_to, leads_to }
import from walkers.impact { ImpactWalker }
import from walkers.pathfinder { PathfinderWalker }

def _lang_count(summary: dict, lang: str) -> int {
    for row in summary["languages"] {
        if row["lang"] == lang {
            return row["count"];
        }
    }
    return 0;
}

def _cat_count(summary: dict, cat: str) -> int {
    for row in summary["need_categories"] {
        if row["category"] == cat {
            return row["count"];
        }
    }
    return 0;
}

test "impact walker reports languages needs statuses and top resources" {
    p1 = PersonNode(user_id="u1", language="en");
    p2 = PersonNode(user_id="u2", language="es");
    p3 = PersonNode(user_id="u3", language="es");
    root ++> p1;
    root ++> p2;
    root ++> p3;
    p1 +>:has_need:+> NeedNode(category="housing");
    p1 +>:has_need:+> NeedNode(category="food");
    p2 +>:has_need:+> NeedNode(category="housing");
    p3 +>:has_need:+> NeedNode(category="legal");
    p1 +>:applied_to:+> ApplicationNode(application_id="a1", status="approved", resource_name="Food Bank");
    p1 +>:applied_to:+> ApplicationNode(application_id="a2", status="denied", resource_name="Shelter");
    p2 +>:applied_to:+> ApplicationNode(application_id="a3", status="approved", resource_name="Food Bank");
    p2 +>:applied_to:+> ApplicationNode(application_id="a4", status="pending", resource_name="Food Bank");
    p3 +>:applied_to:+> ApplicationNode(application_id="a5", status="archived", resource_name="Shelter");
    p3 +>:applied_to:+> ApplicationNode(application_id="a6", status="archived", resource_name="Legal Aid");
    w = root spawn ImpactWalker();
    s = w.reports[0];
    assert s == w.summary;
    assert s["total_users"] == 3;
    assert _lang_count(s, "en") == 1;
    assert _lang_count(s, "es") == 2;
    assert _cat_count(s, "housing") == 2;
    assert _cat_count(s, "food") == 1;
    assert _cat_count(s, "legal") == 1;
    assert s["total_applications"] == 4;
    assert s["app_status_counts"]["approved"] == 2;
    assert s["app_status_counts"]["denied"] == 1;
    assert s["app_status_counts"]["pending"] == 1;
    assert s["app_status_counts"]["withdrawn"] == 0;
    assert "archived" not in s["app_status_counts"];
    assert s["approval_rate"] == 66;
    assert len(s["top_resources"]) == 2;
    assert s["top_resources"][0]["name"] == "Food Bank";
    assert s["top_resources"][0]["count"] == 3;
    assert s["top_resources"][1]["name"] == "Shelter";
    assert s["top_resources"][1]["count"] == 1;
}

test "pathfinder reports a two hop path" {
    a = ResourceNode(agency_name="Emergency Shelter", category="housing");
    b = ResourceNode(agency_name="Transitional Housing", category="housing_mid");
    c = ResourceNode(agency_name="Section 8", category="housing_long");
    root ++> a;
    root ++> b;
    root ++> c;
    a +>:leads_to:transition_reason="stabilized", typical_days=30, difficulty="easy":+> b;
    b +>:leads_to:transition_reason="income verified", typical_days=90, difficulty="hard":+> c;
    w = root spawn PathfinderWalker(start_category="housing");
    s = w.reports[0];
    assert s["ok"] == True;
    assert s["path_count"] == 1;
    p = s["paths"][0];
    assert p["start"] == "Emergency Shelter";
    assert p["end"] == "Section 8";
    assert p["hop_count"] == 2;
    assert len(p["hops"]) == 2;
    assert p["hops"][0]["from"] == "Emergency Shelter";
    assert p["hops"][0]["to"] == "Transitional Housing";
    assert p["hops"][0]["reason"] == "stabilized";
    assert p["hops"][1]["difficulty"] == "hard";
    assert p["total_days"] == 120;
}

test "pathfinder reports one path per chain and honours max paths" {
    for i in range(3) {
        s0 = ResourceNode(agency_name=f"Food Start {i}", category="food");
        s1 = ResourceNode(agency_name=f"Food Mid {i}", category="food_mid");
        s2 = ResourceNode(agency_name=f"Food End {i}", category="food_end");
        root ++> s0;
        root ++> s1;
        root ++> s2;
        s0 +>:leads_to:typical_days=10 + i:+> s1;
        s1 +>:leads_to:typical_days=10:+> s2;
    }
    w = root spawn PathfinderWalker(start_category="food", max_paths=5);
    s = w.reports[0];
    assert s["path_count"] == 3;
    starts = sorted([p["start"] for p in s["paths"]]);
    assert starts == ["Food Start 0", "Food Start 1", "Food Start 2"];
    assert s["paths"][0]["total_days"] <= s["paths"][1]["total_days"];
    w2 = root spawn PathfinderWalker(start_category="food", max_paths=2);
    assert w2.reports[0]["path_count"] == 2;
}

test "pathfinder reports zero paths without transitions" {
    root ++> ResourceNode(agency_name="Isolated Clinic", category="medical");
    root ++> ResourceNode(agency_name="Isolated Pharmacy", category="medical");
    w = root spawn PathfinderWalker(start_category="medical");
    s = w.reports[0];
    assert s["ok"] == True;
    assert s["path_count"] == 0;
    assert s["paths"] == [];
}
"}

