import uuid;
import from main {
    list_properties,
    list_units,
    list_tickets,
    register_tenant,
    list_tenants,
    add_property_node,
    delete_property_node,
    match_tenant,
    approve_dispatch,
    resolve_ticket
}
import from services.graph.models { Property, Unit, Ticket, HasUnit, HasTicket }

test "rentora owner flow" {
    tag = uuid.uuid4().hex[:8];
    prop_name = "Maple Court " + tag;
    phone = "+1555" + tag;
    tid = "TCK-" + tag;

    # Add a property with unit numbers.
    created = (root spawn add_property_node(
        name=prop_name, address="12 Maple St", unit_numbers=["1A", "1B", "2A"]
    )).reports[0];
    assert created["status"] == "created";
    assert created["units"] == 3;
    pid = created["id"];

    props = (root spawn list_properties()).reports[0];
    mine = [p for p in props if p["id"] == pid];
    assert len(mine) == 1;
    assert mine[0]["unit_count"] == 3;

    # Register a tenant, then refuse a duplicate phone.
    reg = (root spawn register_tenant(
        tenant_name="Ana Ruiz", tenant_phone=phone, unit_number="1a",
        rent_amount=1200.0, lease_start="2026-01-01", lease_end="2026-12-31",
        property_name=prop_name
    )).reports[0];
    assert reg["status"] == "registered";
    assert reg["unit"] == "1A";
    dup = (root spawn register_tenant(
        tenant_name="Ana Ruiz", tenant_phone=phone, unit_number="1A",
        property_name=prop_name
    )).reports[0];
    assert dup["status"] == "already_registered";

    tenants = (root spawn list_tenants()).reports[0];
    mine_t = [t for t in tenants if t["phone_number"] == phone];
    assert len(mine_t) == 1;
    assert mine_t[0]["property_id"] == pid;
    assert mine_t[0]["unit_number"] == "1A";

    units = (root spawn list_units()).reports;
    unit_rows = [u for u in units if u["property"] == prop_name and u["unit"] == "1A"];
    assert len(unit_rows) == 1;
    assert unit_rows[0]["tenant_phone"] == phone;

    m = (root spawn match_tenant(phone=phone)).reports[0];
    assert m["matched"] == True;
    assert m["tenant_name"] == "Ana Ruiz";
    assert m["unit"] == "1A";
    miss = (root spawn match_tenant(phone="+10000000000-" + tag)).reports[0];
    assert miss["matched"] == False;

    # Attach a ticket to unit 1A, then dispatch and resolve it.
    for p in [root -->][?:Property] {
        if jid(p) == pid {
            for u in [p ->:HasUnit:->][?:Unit] {
                if u.number == "1A" {
                    u +>:HasTicket:+> Ticket(
                        ticket_id=tid, category="plumbing", description="Leaky sink"
                    );
                }
            }
        }
    }
    disp = (root spawn approve_dispatch(ticket_id=tid)).reports[0];
    assert disp["status"] == "dispatched";
    tickets = [t for t in (root spawn list_tickets()).reports if t["ticket_id"] == tid];
    assert len(tickets) == 1;
    assert tickets[0]["status"] == "dispatched";

    res = (root spawn resolve_ticket(ticket_id=tid)).reports[0];
    assert res["status"] == "resolved";
    assert res["resolved_at"] != "";
    tickets = [t for t in (root spawn list_tickets()).reports if t["ticket_id"] == tid];
    assert tickets[0]["status"] == "resolved";

    # Delete the property, then report not_found for an unknown id.
    gone = (root spawn delete_property_node(property_id=pid)).reports[0];
    assert gone["status"] == "deleted";
    props = (root spawn list_properties()).reports[0];
    assert len([p for p in props if p["id"] == pid]) == 0;
    unknown = (root spawn delete_property_node(property_id="no-such-id-" + tag)).reports[0];
    assert unknown["status"] == "not_found";
}
"}

