3: import json;
4: import from datetime { datetime, timezone }
5: import from graph.nodes { Incident, Person, Claim, Alert, InvestigationRun }
6: import from graph.edges {
7:     Involves,
8:     About,
9:     Asserts,
10:     HasSubscription,
11:     Receives,
12:     HasInvestigation
13: }
14: 
15: glob TIMELINE_LIMIT: int = 50;
16: 
17: """One cited row in a person's timeline (kind: claim, alert or investigation)."""
18: obj TimelineEntry {
19:     has id: str,
20:         kind: str,
21:         person_id: str,
22:         claim_id: str = "",
23:         source_name: str = "",
24:         source_ids: list[str] = [],
25:         claim_type: str = "",
26:         reported_at: str = "",
27:         ingested_at: str = "",
28:         source_reference: str = "",
29:         recorded_at: str = "",
30:         text: str = "",
31:         status: str = "",
32:         mode: str = "",
33:         subscriber_names: list[str] = [],
34:         status_changed: bool = False,
35:         previous_claim_id: str = "",
36:         previous_claim_type: str = "",
37:         total_entries: int = 0;
38: }
39: 
40: """Parse an ISO timestamp into epoch seconds; unparseable values sort first."""
41: def _parse_ts(value: str) -> float {
42:     text = value.strip();
43:     if not text {
44:         return 0.0;
45:     }
46:     if text.endswith("Z") {
47:         text = text[:-1] + "+00:00";
48:     }
49:     try {
50:         parsed = datetime.fromisoformat(text);
51:         if parsed.tzinfo is None {
52:             parsed = parsed.replace(tzinfo=timezone.utc);
53:         }
54:         return parsed.timestamp();
55:     } except Exception {
56:         return 0.0;
57:     }
58: }
59: 
60: """Rank used to break ties between rows recorded at the same moment."""
61: def _kind_rank(kind: str) -> int {
62:     if kind == "claim" {
63:         return 0;
64:     }
65:     if kind == "alert" {
66:         return 1;
67:     }
68:     return 2;
69: }
70: 
71: """Sort key for claim rows: reported time, ingested time, source, kind."""
72: def _claim_key(row: TimelineEntry) -> tuple {
73:     return (
74:         _parse_ts(row.reported_at),
75:         _parse_ts(row.ingested_at),
76:         row.source_name,
77:         _kind_rank(row.kind)
78:     );
79: }
80: 
81: """Sort key for all rows: event time (reported or recorded), then kind."""
82: def _row_key(row: TimelineEntry) -> tuple {
83:     moment = row.reported_at if row.kind == "claim" else row.recorded_at;
84:     return (
85:         _parse_ts(moment),
86:         _kind_rank(row.kind),
87:         _parse_ts(row.ingested_at),
88:         row.source_name
89:     );
90: }
91: 
92: """Cited history for one person in one incident: claims, alerts and investigation runs."""
93: def:pub person_timeline(incident_id: str, person_id: str) -> list[TimelineEntry] {
94:     incident: Incident | None = None;
95:     for node_ in [root -->] {
96:         if isinstance(node_, Incident) and jid(node_) == incident_id {
97:             incident = node_;
98:             break;
99:         }
100:     }
101:     if incident is None {
102:         return [];
103:     }
104:     person: Person | None = None;
105:     for candidate in [incident ->:Involves:->] {
106:         if isinstance(candidate, Person) and jid(candidate) == person_id {
107:             person = candidate;
108:             break;
109:         }
110:     }
111:     if person is None {
112:         return [];
113:     }
114: 
115:     claim_rows: list[TimelineEntry] = [];
116:     claim_by_id: dict[str, TimelineEntry] = {};
117:     for claim in [person <-:About:<-] {
118:         if not isinstance(claim, Claim) {
119:             continue;
120:         }
121:         if claim.incident_id and claim.incident_id != incident_id {
122:             continue;
123:         }
124:         cid = jid(claim);
125:         if cid in claim_by_id {
126:             continue;
127:         }
128:         names: list[str] = [];
129:         ids: list[str] = [];
130:         for src in [claim <-:Asserts:<-] {
131:             names.append(src.name);
132:             ids.append(jid(src));
133:         }
134:         row = TimelineEntry(
135:             id=cid,
136:             kind="claim",
137:             person_id=person_id,
138:             claim_id=cid,
139:             source_name="; ".join(names),
140:             source_ids=ids,
141:             claim_type=claim.claim_type,
142:             reported_at=claim.timestamp,
143:             ingested_at=claim.ingested_at,
144:             source_reference=claim.source_reference,
145:             recorded_at=claim.ingested_at,
146:             text=claim.value or claim.notes or claim.original_content
147:         );
148:         claim_rows.append(row);
149:         claim_by_id[cid] = row;
150:     }
151:     claim_rows = sorted(claim_rows, key=_claim_key);
152:     for idx in range(1, len(claim_rows)) {
153:         prior = claim_rows[idx - 1];
154:         current = claim_rows[idx];
155:         current.previous_claim_id = prior.claim_id;
156:         current.previous_claim_type = prior.claim_type;
157:         current.status_changed = prior.claim_type != current.claim_type;
158:     }
159: 
160:     rows: list[TimelineEntry] = list(claim_rows);
161: 
162:     alert_rows: dict[str, TimelineEntry] = {};
163:     for sub in [person ->:HasSubscription:->] {
164:         for alert in [sub ->:Receives:->] {
165:             if not isinstance(alert, Alert) {
166:                 continue;
167:             }
168:             aid = jid(alert);
169:             if aid in alert_rows {
170:                 if sub.subscriber_name not in alert_rows[aid].subscriber_names {
171:                     alert_rows[aid].subscriber_names.append(sub.subscriber_name);
172:                 }
173:                 continue;
174:             }
175:             linked = claim_by_id.get(alert.claim_id) if alert.claim_id else None;
176:             arow = TimelineEntry(
177:                 id=aid,
178:                 kind="alert",
179:                 person_id=person_id,
180:                 claim_id=linked.claim_id if linked is not None else "",
181:                 source_name=linked.source_name if linked is not None else "",
182:                 source_ids=list(linked.source_ids) if linked is not None else [],
183:                 claim_type=linked.claim_type if linked is not None else "",
184:                 source_reference=linked.source_reference if linked is not None else "",
185:                 recorded_at=alert.created_at,
186:                 text=alert.message,
187:                 status=alert.severity,
188:                 subscriber_names=[sub.subscriber_name]
189:             );
190:             alert_rows[aid] = arow;
191:             rows.append(arow);
192:         }
193:     }
