211:             cited_id = str(citations[0].get("claim_id", ""));
212:         }
213:         linked = claim_by_id.get(cited_id) if cited_id else None;
214:         rrow = TimelineEntry(
215:             id=jid(run),
216:             kind="investigation",
217:             person_id=person_id,
218:             claim_id=linked.claim_id if linked is not None else "",
219:             source_name=linked.source_name if linked is not None else "",
220:             source_ids=list(linked.source_ids) if linked is not None else [],
221:             claim_type=linked.claim_type if linked is not None else "",
222:             source_reference=linked.source_reference if linked is not None else "",
223:             recorded_at=str(data.get("run_at", "") or run.created_at),
224:             text=str(data.get("message", "")),
225:             status=str(data.get("status", "")),
226:             mode=str(data.get("mode", "") or run.mode)
227:         );
228:         rows.append(rrow);
229:     }
