{"file_path": "/workspace/test_trace.jac", "content": """"Acceptance tests for the Trace backend: timeline ordering, links, scoping, wording, activity."""

import json;
import from graph.nodes {
    Incident,
    Person,
    Claim,
    Source,
    Subscription,
    Alert,
    ActivityEntry,
    InvestigationRun
}
import from graph.edges {
    Involves,
    Asserts,
    About,
    HasSubscription,
    Receives,
    HasInvestigation
}
import from services.timeline { TimelineEntry, person_timeline }
import from graph.activity { now_iso, plain_status, log_activity }

"""Build one incident with a person, two sourced claims (inserted out of order), an alert and a run."""
def seed_graph() -> dict {
    incident = Incident(name="River Flood", region="North");
    other = Incident(name="Hill Fire", region="East");
    root ++> incident;
    root ++> other;
    person = Person(name="Ana Ruiz", age=34);
    incident +>:Involves:+> person;
    other +>:Involves:+> person;
    shelter = Source(name="Shelter Desk", source_type="organization");
    radio = Source(name="Radio North", source_type="media");
    found = Claim(
        claim_type="FOUND_SAFE",
        value="Checked in at shelter",
        timestamp="2026-03-02T10:00:00Z",
        ingested_at="2026-03-02T10:05:00Z",
        source_reference="intake-17"
    );
    missing = Claim(
        claim_type="MISSING",
        value="Not seen since evening",
        timestamp="2026-03-01T08:00:00Z",
        ingested_at="2026-03-01T08:10:00Z",
        source_reference="call-4"
    );
    shelter +>:Asserts:+> found;
    radio +>:Asserts:+> missing;
    found +>:About:+> person;
    missing +>:About:+> person;
    incident_id = jid(incident);
    found.incident_id = incident_id;
    missing.incident_id = incident_id;
    foreign = Claim(
        claim_type="INJURED",
        timestamp="2026-03-01T09:00:00Z",
        incident_id=jid(other)
    );
    radio +>:Asserts:+> foreign;
    foreign +>:About:+> person;
    sub = Subscription(subscriber_name="Maria Ruiz", subscriber_contact="maria@example.org");
    person +>:HasSubscription:+> sub;
    alert = Alert(
        message="Ana Ruiz reported safe",
        created_at="2026-03-02T10:06:00Z",
        severity="sent",
        claim_id=jid(found)
    );
    sub +>:Receives:+> alert;
    result = {
        "status": "resolved",
        "mode": "deterministic",
        "message": "Latest cited status is found safe",
        "run_at": "2026-03-02T11:00:00Z",
        "citations": [{"claim_id": jid(found)}]
    };
    run = InvestigationRun(
        person_id=jid(person),
        fingerprint="fp-1",
        result_json=json.dumps(result),
        created_at="2026-03-02T11:00:00Z"
    );
    incident +>:HasInvestigation:+> run;
    return {
        "incident_id": incident_id,
        "person_id": jid(person),
        "found_id": jid(found),
        "missing_id": jid(missing),
        "foreign_id": jid(foreign),
        "shelter_id": jid(shelter),
        "radio_id": jid(radio)
    };
}

test "claims follow source-reported order with sources and status change" {
    ids = seed_graph();
    rows = person_timeline(ids["incident_id"], ids["person_id"]);
    claims = [r for r in rows if r.kind == "claim"];
    assert len(claims) == 2;
    assert claims[0].claim_id == ids["missing_id"];
    assert claims[0].source_name == "Radio North";
    assert claims[0].source_ids == [ids["radio_id"]];
    assert claims[0].source_reference == "call-4";
    assert claims[0].status_changed == False;
    assert claims[1].claim_id == ids["found_id"];
    assert claims[1].source_name == "Shelter Desk";
    assert claims[1].source_ids == [ids["shelter_id"]];
    assert claims[1].source_reference == "intake-17";
    assert claims[1].status_changed == True;
    assert claims[1].previous_claim_id == ids["missing_id"];
    assert claims[1].previous_claim_type == "MISSING";
}

test "alerts and investigation runs link to the cited claim" {
    ids = seed_graph();
    rows = person_timeline(ids["incident_id"], ids["person_id"]);
    alerts = [r for r in rows if r.kind == "alert"];
    runs = [r for r in rows if r.kind == "investigation"];
    assert len(alerts) == 1;
    assert alerts[0].claim_id == ids["found_id"];
    assert alerts[0].subscriber_names == ["Maria Ruiz"];
    assert alerts[0].text == "Ana Ruiz reported safe";
    assert alerts[0].source_name == "Shelter Desk";
    assert len(runs) == 1;
    assert runs[0].claim_id == ids["found_id"];
    assert runs[0].mode == "deterministic";
    assert runs[0].status == "resolved";
    assert runs[0].text == "Latest cited status is found safe";
    assert [r.kind for r in rows] == ["claim", "claim", "alert", "investigation"];
}

test "other incidents are excluded and unknown ids are empty" {
    ids = seed_graph();
    rows = person_timeline(ids["incident_id"], ids["person_id"]);
    assert ids["foreign_id"] not in [r.claim_id for r in rows];
    assert len(rows) == 4;
    for r in rows {
        assert r.total_entries == 4;
    }
    assert person_timeline("no-such-incident", ids["person_id"]) == [];
    assert person_timeline(ids["incident_id"], "no-such-person") == [];
}

test "plain_status uses plain words" {
    assert plain_status("FOUND_SAFE") != "FOUND_SAFE";
    assert "safe" in plain_status("FOUND_SAFE").lower();
    assert "missing" in plain_status("MISSING").lower();
    assert plain_status("NEEDS_WATER") == "needs water";
}

test "log_activity attaches an entry to root" {
    log_activity("WatchWalker", "Sent 1 alert", "inc-9");
    entries = [n for n in [root -->] if isinstance(n, ActivityEntry)];
    match = [e for e in entries if e.message == "Sent 1 alert"];
    assert len(match) >= 1;
    assert match[0].walker_name == "WatchWalker";
    assert match[0].incident_id == "inc-9";
    assert match[0].created_at != "";
    assert "T" in now_iso();
}
"}

