        member_id="M123",
        claim_number=claim_number,
        date_of_service="2024-01-01",
        cpt_code="99213",
        billed_amount=250.0,
        plan_name="Gold Plan",
        denial_text="Denied as not medically necessary.",
        policy_text="Section 4.2 covers medically necessary care.",
        clinical_record="Physician documents medical need."
    );
    return w;
}

test "submit_claim stores nodes and reports the letter" {
    mock([
        "NOT_MEDICALLY_NECESSARY",
        "[{\"section\": \"4.2\", \"title\": \"Necessity\", \"text\": \"covers care\"}]",
        "[{\"denial_quote\": \"not necessary\", \"policy_quote\": \"covers care\", \"clause_section\": \"4.2\", \"explanation\": \"record shows need\"}]",
        "STRONG",
        "Letter: {\"subject\": \"Appeal of C-1\", \"salutation\": \"Dear Reviewer,\", \"body\": \"Please reconsider.\", \"citations\": [\"Sec 4.2\"], \"closing\": \"Sincerely, Pat\"}"
    ]);
    w = run_claim("C-1");
    rep = w.reports[0];
    assert rep["claim_id"] == "C-1";
    assert rep["appeal_id"].startswith("APL-");
    assert len(rep["appeal_id"]) == 12;
    assert rep["subject"] == "Appeal of C-1";
    assert rep["letter"] == "Dear Reviewer,\n\nPlease reconsider.\n\nSincerely, Pat";
    assert rep["citations"] == ["Sec 4.2"];

    claims = [root-->[?:Claim]];
    assert any([c.claim_id == "C-1" for c in claims]);
    policies = [root-->[?:Policy]];
    assert any([p.policy_id == "POL-M123" for p in policies]);
    appeals = [a for a in [root-->[?:Appeal]] if a.appeal_id == rep["appeal_id"]];
    assert len(appeals) == 1;
    assert appeals[0].denial_reason == DenialReason.NOT_MEDICALLY_NECESSARY;
    assert appeals[0].strength == AppealStrength.STRONG;
    assert appeals[0].letter_body == rep["letter"];
}

test "submit_claim letter joins empty parts and list_appeals reports rows" {
    mock(["???", "none", "none", "unclear", "no json"]);
    w = run_claim("C-2");
    rep = w.reports[0];
    assert rep["letter"] == "\n\n\n\n";
    assert rep["subject"] == "";
    assert rep["citations"] == [];

    lw = root spawn list_appeals();
    assert len(lw.reports) == 1;
    rows = lw.reports[0];
    assert len(rows) == len([root-->[?:Appeal]]);
    match_rows = [r for r in rows if r["appeal_id"] == rep["appeal_id"]];
    assert len(match_rows) == 1;
    assert match_rows[0]["claim_id"] == "C-2";
    assert match_rows[0]["subject"] == "";
    assert match_rows[0]["created_at"] != "";
}
"}

