{"file_path": "/workspace/services/graph/models.jac", "content": """"Rentora graph schema: property-management nodes, edges and enums."""

enum EventType {
    MAINTENANCE,
    PAYMENT,
    LEASE,
    COMPLAINT,
    INQUIRY
}

sem EventType.MAINTENANCE = "A repair or maintenance request for a unit.";
sem EventType.PAYMENT = "A rent or fee payment question or event.";
sem EventType.LEASE = "A lease signing, renewal or termination matter.";
sem EventType.COMPLAINT = "A tenant complaint about noise, neighbors or service.";
sem EventType.INQUIRY = "A general question from a tenant or prospect.";

enum UrgencyLevel {
    LOW,
    MEDIUM,
    HIGH,
    CRITICAL
}

sem UrgencyLevel.LOW = "Can wait days; no impact on habitability.";
sem UrgencyLevel.MEDIUM = "Should be handled within a few days.";
sem UrgencyLevel.HIGH = "Needs attention within 24 hours.";
sem UrgencyLevel.CRITICAL = "Emergency affecting safety or habitability; act immediately.";

node Property {
    has name: str = "";
    has address: str = "";
    has city: str = "";
    has state: str = "";
    has zip_code: str = "";
}

node Unit {
    has number: str = "";
    has bedrooms: int = 1;
    has bathrooms: int = 1;
    has sq_ft: int = 0;
    has status: str = "occupied";
}

node Lease {
    has start_date: str = "";
    has end_date: str = "";
    has rent_amount: float = 0.0;
    has deposit: float = 0.0;
    has status: str = "active";
}

node Tenant {
    has name: str = "";
    has phone: str = "";
    has email: str = "";
    has payment_status: str = "current";
    has move_in_date: str = "";
}

node Ticket {
    has ticket_id: str = "";
    has category: str = "";
    has description: str = "";
    has urgency: str = "medium";
    has status: str = "open";
    has ai_summary: str = "";
    has ai_diagnosis: str = "";
    has recommended_action: str = "";
    has tenant_reply: str = "";
    has owner_alert: str = "";
    has created_at: str = "";
    has resolved_at: str = "";
    has vendor_name: str = "";
    has estimated_cost: float = 0.0;
}

node Vendor {
    has name: str = "";
    has category: str = "";
    has phone: str = "";
    has email: str = "";
    has rating: float = 0.0;
    has avg_cost: float = 0.0;
    has available: bool = True;
}

edge HasUnit {}

edge HasLease {}

edge HasTenant {}

edge HasTicket {}

edge AssignedTo {}

edge Services {
    has jobs_completed: int = 0;
    has total_spent: float = 0.0;
    has last_service_date: str = "";
}
"}

