node BusinessNode {
    has name: str;
    has location: str;
    has business_type: str;
    has contact: str;
}

"""A shelter that receives food donations."""
node ShelterNode {
    has name: str;
    has location: str;
    has current_capacity: int;
    has max_capacity: int;
    has needed_items: list[str];
}

"""A food donation; status lifecycle is pending -> matched -> completed."""
node DonationNode {
    has food_type: str;
    has quantity: int;
    has expiry_time: str;
    has status: str = "pending";
    has dispatched: bool = False;
}

"""A volunteer driver who can deliver donations."""
node VolunteerNode {
    has name: str;
    has vehicle_type: str;
    has location: str;
    has contact: str;
    has is_available: bool = True;
}

"""BusinessNode -> DonationNode."""
edge Offers {}

"""DonationNode -> ShelterNode."""
edge AllocatedTo {}

"""DonationNode -> VolunteerNode."""
edge AssignedVolunteer {}

"""Domain node -> HubNode."""
edge ConnectedToHub {}
"}

